  t.add("This value should be greater than or equal to {{ compared_value }}.", "\u0627\u0644\u0642\u064A\u0645\u0629 \u064A\u062C\u0628 \u0627\u0646 \u062A\u0643\u0648\u0646 \u0645\u0633\u0627\u0648\u064A\u0629 \u0627\u0648 \u0627\u0639\u0644\u064A \u0645\u0646 {{ compared_value }}.", "validators", "ar");
  t.add("This value should be identical to {{ compared_value_type }} {{ compared_value }}.", "\u0627\u0644\u0642\u064A\u0645\u0629 \u064A\u062C\u0628 \u0627\u0646 \u062A\u0637\u0627\u0628\u0642 {{ compared_value_type }} {{ compared_value }}.", "validators", "ar");
  t.add("This value should be less than {{ compared_value }}.", "\u0627\u0644\u0642\u064A\u0645\u0629 \u064A\u062C\u0628 \u0627\u0646 \u062A\u0643\u0648\u0646 \u0627\u0642\u0644 \u0645\u0646 {{ compared_value }}.", "validators", "ar");
  t.add("This value should be less than or equal to {{ compared_value }}.", "\u0627\u0644\u0642\u064A\u0645\u0629 \u064A\u062C\u0628 \u0627\u0646 \u062A\u0633\u0627\u0648\u064A \u0627\u0648 \u062A\u0642\u0644 \u0639\u0646 {{ compared_value }}.", "validators", "ar");
  t.add("This value should not be equal to {{ compared_value }}.", "\u0627\u0644\u0642\u064A\u0645\u0629 \u064A\u062C\u0628 \u0627\u0646 \u0644\u0627 \u062A\u0633\u0627\u0648\u064A {{ compared_value }}.", "validators", "ar");
  t.add("This value should not be identical to {{ compared_value_type }} {{ compared_value }}.", "\u0627\u0644\u0642\u064A\u0645\u0629 \u064A\u062C\u0628 \u0627\u0646 \u0644\u0627 \u062A\u0637\u0627\u0628\u0642 {{ compared_value_type }} {{ compared_value }}.", "validators", "ar");
  t.add("The image ratio is too big ({{ ratio }}). Allowed maximum ratio is {{ max_ratio }}.", "\u0646\u0633\u0628\u0629 \u0627\u0644\u0639\u0631\u0636 \u0639\u0644\u0649 \u0627\u0644\u0627\u0631\u062A\u0641\u0627\u0639 \u0644\u0644\u0635\u0648\u0631\u0629 \u0643\u0628\u064A\u0631\u0629 \u062C\u062F\u0627 ({{ ratio }}). \u0627\u0644\u062D\u062F \u0627\u0644\u0623\u0642\u0635\u0649 \u0644\u0644\u0646\u0633\u0628\u0629 \u0627\u0644\u0645\u0633\u0645\u0648\u062D \u0628\u0647 \u0647\u0648 {{ max_ratio }}.", "validators", "ar");
  t.add("The image ratio is too small ({{ ratio }}). Minimum ratio expected is {{ min_ratio }}.", "\u0646\u0633\u0628\u0629 \u0627\u0644\u0639\u0631\u0636 \u0639\u0644\u0649 \u0627\u0644\u0627\u0631\u062A\u0641\u0627\u0639 \u0644\u0644\u0635\u0648\u0631\u0629 \u0635\u063A\u064A\u0631\u0629 \u062C\u062F\u0627 ({{ ratio }}). \u0627\u0644\u062D\u062F \u0627\u0644\u0623\u062F\u0646\u0649 \u0644\u0644\u0646\u0633\u0628\u0629 \u0627\u0644\u0645\u0633\u0645\u0648\u062D \u0628\u0647 \u0647\u0648 {{ max_ratio }}.", "validators", "ar");
  t.add("The image is square ({{ width }}x{{ height }}px). Square images are not allowed.", "\u0627\u0644\u0635\u0648\u0631\u0629 \u0645\u0631\u0628\u0639\u0629 ({{ width }}x{{ height }}px). \u0627\u0644\u0635\u0648\u0631 \u0627\u0644\u0645\u0631\u0628\u0639\u0629 \u063A\u064A\u0631 \u0645\u0633\u0645\u0648\u062D \u0628\u0647\u0627.", "validators", "ar");
  t.add("The image is landscape oriented ({{ width }}x{{ height }}px). Landscape oriented images are not allowed.", "\u0627\u0644\u0635\u0648\u0631\u0629 \u0641\u064A \u0648\u0636\u0639 \u0623\u0641\u0642\u064A ({{ width }}x{{ height }}px). \u0627\u0644\u0635\u0648\u0631 \u0641\u064A \u0648\u0636\u0639 \u0623\u0641\u0642\u064A \u063A\u064A\u0631 \u0645\u0633\u0645\u0648\u062D \u0628\u0647\u0627.", "validators", "ar");
  t.add("The image is portrait oriented ({{ width }}x{{ height }}px). Portrait oriented images are not allowed.", "\u0627\u0644\u0635\u0648\u0631\u0629 \u0641\u064A \u0648\u0636\u0639 \u0639\u0645\u0648\u062F\u064A ({{ width }}x{{ height }}px). \u0627\u0644\u0635\u0648\u0631 \u0641\u064A \u0648\u0636\u0639 \u0639\u0645\u0648\u062F\u064A \u063A\u064A\u0631 \u0645\u0633\u0645\u0648\u062D \u0628\u0647\u0627.", "validators", "ar");
  t.add("An empty file is not allowed.", "\u0645\u0644\u0641 \u0641\u0627\u0631\u063A \u063A\u064A\u0631 \u0645\u0633\u0645\u0648\u062D \u0628\u0647.", "validators", "ar");
  t.add("The host could not be resolved.", "\u064A\u062A\u0639\u0630\u0631 \u0627\u0644\u0625\u062A\u0635\u0627\u0644 \u0628\u0627\u0644\u0646\u0637\u0627\u0642.", "validators", "ar");
  t.add("This value does not match the expected {{ charset }} charset.", "\u0647\u0630\u0647 \u0627\u0644\u0642\u064A\u0645\u0629 \u063A\u064A\u0631 \u0645\u062A\u0637\u0627\u0628\u0642\u0629 \u0645\u0639 \u0635\u064A\u063A\u0629 \u0627\u0644\u062A\u062D\u0648\u064A\u0644 {{ charset }}.", "validators", "ar");
  t.add("This is not a valid Business Identifier Code (BIC).", "\u0647\u0630\u0647 \u0627\u0644\u0642\u064A\u0645\u0629 \u0644\u064A\u0633\u062A \u0631\u0645\u0632 \u0645\u0639\u0631\u0641 \u0623\u0639\u0645\u0627\u0644 (BIC) \u0635\u0627\u0644\u062D\u064B\u0627.", "validators", "ar");
  t.add("Error", "\u062E\u0637\u0623", "validators", "ar");
  t.add("This is not a valid UUID.", "\u0647\u0630\u0647 \u0627\u0644\u0642\u064A\u0645\u0629 \u0644\u064A\u0633\u062A UUID \u0635\u0627\u0644\u062D\u064B\u0627.", "validators", "ar");
  t.add("This value should be a multiple of {{ compared_value }}.", "\u0647\u0630\u0647 \u0627\u0644\u0642\u064A\u0645\u0629 \u064A\u062C\u0628 \u0623\u0646 \u062A\u0643\u0648\u0646 \u0645\u0636\u0627\u0639\u0641 \u0644 {{ compared_value }}.", "validators", "ar");
  t.add("This Business Identifier Code (BIC) is not associated with IBAN {{ iban }}.", "\u0631\u0645\u0632 \u0627\u0644\u0645\u0639\u0631\u0651\u0641 \u0646\u0634\u0627\u0637 \u062A\u062C\u0627\u0631\u064A (BIC) \u0647\u0630\u0627 \u0644\u0627 \u064A\u0631\u062A\u0628\u0637 \u0645\u0639 IBAN {{ iban }}.", "validators", "ar");
  t.add("This value should be valid JSON.", "\u0647\u0630\u0647 \u0627\u0644\u0642\u064A\u0645\u0629 \u064A\u062C\u0628 \u0623\u0646 \u062A\u0643\u0648\u0646 \u0635\u0627\u0644\u062D\u0629 \u0644 JSON.", "validators", "ar");
  t.add("This collection should contain only unique elements.", "\u064A\u062C\u0628 \u0623\u0646 \u062A\u062D\u062A\u0648\u064A \u0647\u0630\u0647 \u0627\u0644\u0645\u062C\u0645\u0648\u0639\u0629 \u0639\u0644\u064A \u0639\u0646\u0627\u0635\u0631 \u0641\u0631\u064A\u062F\u0629 \u0641\u0642\u0637.", "validators", "ar");
  t.add("This value should be positive.", "\u064A\u062C\u0628 \u0623\u0646 \u062A\u0643\u0648\u0646 \u0647\u0630\u0647 \u0627\u0644\u0642\u064A\u0645\u0629 \u0645\u0648\u062C\u0628\u0629.", "validators", "ar");
  t.add("This value should be either positive or zero.", "\u064A\u062C\u0628 \u0623\u0646 \u062A\u0643\u0648\u0646 \u0647\u0630\u0647 \u0627\u0644\u0642\u064A\u0645\u0629 \u0625\u0645\u0627 \u0645\u0648\u062C\u0628\u0629 \u0627\u0648 \u0635\u0641\u0631.", "validators", "ar");
  t.add("This value should be negative.", "\u064A\u062C\u0628 \u0623\u0646 \u062A\u0643\u0648\u0646 \u0647\u0630\u0647 \u0627\u0644\u0642\u064A\u0645\u0629 \u0633\u0627\u0644\u0628\u0629.", "validators", "ar");
  t.add("This value should be either negative or zero.", "\u064A\u062C\u0628 \u0623\u0646 \u062A\u0643\u0648\u0646 \u0647\u0630\u0647 \u0627\u0644\u0642\u064A\u0645\u0629 \u0625\u0645\u0627 \u0633\u0627\u0644\u0628\u0629 \u0627\u0648 \u0635\u0641\u0631.", "validators", "ar");
  t.add("This value is not a valid timezone.", "\u0647\u0630\u0647 \u0627\u0644\u0642\u064A\u0645\u0629 \u0644\u064A\u0633\u062A \u0645\u0646\u0637\u0642\u0629 \u0632\u0645\u0646\u064A\u0629 \u0635\u062D\u064A\u062D\u0629.", "validators", "ar");
  t.add("This password has been leaked in a data breach, it must not be used. Please use another password.", "\u062A\u0645 \u062A\u0633\u0631\u064A\u0628 \u0643\u0644\u0645\u0629 \u0627\u0644\u0645\u0631\u0648\u0631 \u0647\u0630\u0647 \u0641\u064A \u062E\u0631\u0642 \u0644\u0644\u0628\u064A\u0627\u0646\u0627\u062A\u060C \u0648\u064A\u062C\u0628 \u0639\u062F\u0645 \u0627\u0633\u062A\u062E\u062F\u0627\u0645\u0647\u0627. \u064A\u0631\u062C\u064A \u0627\u0633\u062A\u062E\u062F\u0627\u0645 \u0643\u0644\u0645\u0629 \u0645\u0631\u0648\u0631 \u0623\u062E\u0631\u064A.", "validators", "ar");
  t.add("This value should be between {{ min }} and {{ max }}.", "\u064A\u062C\u0628 \u0623\u0646 \u062A\u0643\u0648\u0646 \u0647\u0630\u0647 \u0627\u0644\u0642\u064A\u0645\u0629 \u0628\u064A\u0646 {{ min }} \u0648 {{ max }}.", "validators", "ar");
  t.add("This value is not a valid hostname.", "\u0647\u0630\u0647 \u0627\u0644\u0642\u064A\u0645\u0629 \u0644\u064A\u0633\u062A \u0627\u0633\u0645 \u0645\u0636\u064A\u0641 \u0635\u0627\u0644\u062D.", "validators", "ar");
  t.add("The number of elements in this collection should be a multiple of {{ compared_value }}.", "\u064A\u062C\u0628 \u0623\u0646 \u064A\u0643\u0648\u0646 \u0639\u062F\u062F \u0627\u0644\u0639\u0646\u0627\u0635\u0631 \u0641\u064A \u0647\u0630\u0647 \u0627\u0644\u0645\u062C\u0645\u0648\u0639\u0629 \u0645\u0636\u0627\u0639\u0641 {{ compared_value }}.", "validators", "ar");
  t.add("This value should satisfy at least one of the following constraints:", "\u064A\u062C\u0628 \u0623\u0646 \u062A\u0633\u062A\u0648\u0641\u064A \u0647\u0630\u0647 \u0627\u0644\u0642\u064A\u0645\u0629 \u0648\u0627\u062D\u062F\u0629 \u0645\u0646 \u0627\u0644\u0642\u064A\u0648\u062F \u0627\u0644\u062A\u0627\u0644\u064A\u0629:", "validators", "ar");
  t.add("Each element of this collection should satisfy its own set of constraints.", "\u064A\u062C\u0628 \u0623\u0646 \u064A\u0641\u064A \u0643\u0644 \u0639\u0646\u0635\u0631 \u0645\u0646 \u0639\u0646\u0627\u0635\u0631 \u0647\u0630\u0647 \u0627\u0644\u0645\u062C\u0645\u0648\u0639\u0629 \u0628\u0645\u062C\u0645\u0648\u0639\u0629 \u0627\u0644\u0642\u064A\u0648\u062F \u0627\u0644\u062E\u0627\u0635\u0629 \u0628\u0647.", "validators", "ar");
  t.add("This value is not a valid International Securities Identification Number (ISIN).", " \u0635\u0627\u0644\u062D (ISIN) \u0647\u0630\u0647 \u0627\u0644\u0642\u064A\u0645\u0629 \u0644\u064A\u0633\u062A \u0631\u0642\u0645 \u062A\u0639\u0631\u064A\u0641 \u0627\u0644\u0623\u0648\u0631\u0627\u0642 \u0627\u0644\u0645\u0627\u0644\u064A\u0629 \u0627\u0644\u062F\u0648\u0644\u064A.", "validators", "ar");
  t.add("This value should be a valid expression.", "\u064A\u062C\u0628 \u0623\u0646 \u062A\u0643\u0648\u0646 \u0647\u0630\u0647 \u0627\u0644\u0642\u064A\u0645\u0629 \u062A\u0639\u0628\u064A\u0631\u064B\u0627 \u0635\u0627\u0644\u062D\u064B\u0627.", "validators", "ar");
  t.add("This value is not a valid CSS color.", "\u0647\u0630\u0647 \u0627\u0644\u0642\u064A\u0645\u0629 \u0644\u064A\u0633\u062A \u0644\u0648\u0646 CSS \u0635\u0627\u0644\u062D\u064B\u0627.", "validators", "ar");
  t.add("This value is not a valid CIDR notation.", "\u0647\u0630\u0647 \u0627\u0644\u0642\u064A\u0645\u0629 \u0644\u064A\u0633\u062A \u062A\u062F\u0648\u064A\u0646 CIDR \u0635\u0627\u0644\u062D\u064B\u0627.", "validators", "ar");
  t.add("The value of the netmask should be between {{ min }} and {{ max }}.", "\u064A\u062C\u0628 \u0623\u0646 \u062A\u0643\u0648\u0646 \u0642\u064A\u0645\u0629 netmask \u0628\u064A\u0646 {{ min }} \u0648 {{ max }}.", "validators", "ar");
  t.add("The filename is too long. It should have {{ filename_max_length }} character or less.|The filename is too long. It should have {{ filename_max_length }} characters or less.", "\u0627\u0633\u0645 \u0627\u0644\u0645\u0644\u0641 \u0637\u0648\u064A\u0644 \u062C\u062F\u0627. \u064A\u062C\u0628 \u0623\u0646 \u064A\u062D\u062A\u0648\u064A \u0639\u0644\u0649 {{ filename_max_length }} \u062D\u0631\u0641 \u0623\u0648 \u0623\u0642\u0644.|\u0627\u0633\u0645 \u0627\u0644\u0645\u0644\u0641 \u0637\u0648\u064A\u0644 \u062C\u062F\u0627. \u064A\u062C\u0628 \u0623\u0646 \u064A\u062D\u062A\u0648\u064A \u0639\u0644\u0649 {{ filename_max_length }} \u0623\u062D\u0631\u0641 \u0623\u0648 \u0623\u0642\u0644.", "validators", "ar");
  t.add("The password strength is too low. Please use a stronger password.", "\u0642\u0648\u0629 \u0643\u0644\u0645\u0629 \u0627\u0644\u0645\u0631\u0648\u0631 \u0645\u0646\u062E\u0641\u0636\u0629 \u0644\u0644\u063A\u0627\u064A\u0629. \u064A\u0631\u062C\u0649 \u0627\u0633\u062A\u062E\u062F\u0627\u0645 \u0643\u0644\u0645\u0629 \u0645\u0631\u0648\u0631 \u0623\u0642\u0648\u0649.", "validators", "ar");
  t.add("This value contains characters that are not allowed by the current restriction-level.", "\u062A\u062D\u062A\u0648\u064A \u0647\u0630\u0647 \u0627\u0644\u0642\u064A\u0645\u0629 \u0639\u0644\u0649 \u0623\u062D\u0631\u0641 \u063A\u064A\u0631 \u0645\u0633\u0645\u0648\u062D \u0628\u0647\u0627 \u0628\u0648\u0627\u0633\u0637\u0629 \u0645\u0633\u062A\u0648\u0649 \u0627\u0644\u062A\u0642\u064A\u064A\u062F \u0627\u0644\u062D\u0627\u0644\u064A.", "validators", "ar");
  t.add("Using invisible characters is not allowed.", "\u0644\u0627 \u064A\u0633\u0645\u062D \u0628\u0627\u0633\u062A\u062E\u062F\u0627\u0645 \u0623\u062D\u0631\u0641 \u063A\u064A\u0631 \u0645\u0631\u0626\u064A\u0629.", "validators", "ar");
  t.add("Mixing numbers from different scripts is not allowed.", "\u0644\u0627 \u064A\u0633\u0645\u062D \u0628\u062E\u0644\u0637 \u0627\u0644\u0623\u0631\u0642\u0627\u0645 \u0645\u0646 \u0646\u0635\u0648\u0635 \u0645\u062E\u062A\u0644\u0641\u0629.", "validators", "ar");
  t.add("Using hidden overlay characters is not allowed.", "\u0644\u0627 \u064A\u0633\u0645\u062D \u0628\u0627\u0633\u062A\u062E\u062F\u0627\u0645 \u0623\u062D\u0631\u0641 \u0627\u0644\u062A\u0631\u0627\u0643\u0628 \u0627\u0644\u0645\u062E\u0641\u064A\u0629.", "validators", "ar");
  t.add("The extension of the file is invalid ({{ extension }}). Allowed extensions are {{ extensions }}.", "\u0627\u0645\u062A\u062F\u0627\u062F \u0627\u0644\u0645\u0644\u0641 \u063A\u064A\u0631 \u0635\u062D\u064A\u062D ({{ extension }}). \u0627\u0644\u0627\u0645\u062A\u062F\u0627\u062F\u0627\u062A \u0627\u0644\u0645\u0633\u0645\u0648\u062D \u0628\u0647\u0627 \u0647\u064A {{ extensions }}.", "validators", "ar");
  t.add("The detected character encoding is invalid ({{ detected }}). Allowed encodings are {{ encodings }}.", "\u062A\u0645 \u0627\u0643\u062A\u0634\u0627\u0641 \u062A\u0631\u0645\u064A\u0632 \u0623\u062D\u0631\u0641 \u063A\u064A\u0631 \u0635\u0627\u0644\u062D ({{ detected }}). \u0627\u0644\u062A\u0631\u0645\u064A\u0632\u0627\u062A \u0627\u0644\u0645\u0633\u0645\u0648\u062D \u0628\u0647\u0627 \u0647\u064A {{ encodings }}.", "validators", "ar");
  t.add("This value is not a valid MAC address.", "\u0647\u0630\u0647 \u0627\u0644\u0642\u064A\u0645\u0629 \u0644\u064A\u0633\u062A \u0639\u0646\u0648\u0627\u0646 MAC \u0635\u0627\u0644\u062D\u064B\u0627.", "validators", "ar");
  t.add("This URL is missing a top-level domain.", "\u0647\u0630\u0627 \u0627\u0644\u0631\u0627\u0628\u0637 \u064A\u0641\u062A\u0642\u0631 \u0625\u0644\u0649 \u0646\u0637\u0627\u0642 \u0627\u0644\u0645\u0633\u062A\u0648\u0649 \u0627\u0644\u0623\u0639\u0644\u0649.", "validators", "ar");
  t.add("This value is too short. It should contain at least one word.|This value is too short. It should contain at least {{ min }} words.", "This value is too short. It should contain at least one word.|This value is too short. It should contain at least {{ min }} words.", "validators", "ar");
  t.add("This value is too long. It should contain one word.|This value is too long. It should contain {{ max }} words or less.", "This value is too long. It should contain one word.|This value is too long. It should contain {{ max }} words or less.", "validators", "ar");
  t.add("This value does not represent a valid week in the ISO 8601 format.", "This value does not represent a valid week in the ISO 8601 format.", "validators", "ar");
  t.add("This value is not a valid week.", "This value is not a valid week.", "validators", "ar");
  t.add("This value should not be before week \"{{ min }}\".", "This value should not be before week \"{{ min }}\".", "validators", "ar");
  t.add("This value should not be after week \"{{ max }}\".", "This value should not be after week \"{{ max }}\".", "validators", "ar");
  t.add("This form should not contain extra fields.", "\u0647\u0630\u0627 \u0627\u0644\u0646\u0645\u0648\u0630\u062C \u064A\u062C\u0628 \u0627\u0644\u0627 \u064A\u062D\u062A\u0648\u0649 \u0639\u0644\u0649 \u0627\u0649 \u062D\u0642\u0648\u0644 \u0627\u0636\u0627\u0641\u064A\u0629.", "validators", "ar");
  t.add("The uploaded file was too large. Please try to upload a smaller file.", "\u0645\u0633\u0627\u062D\u0629 \u0627\u0644\u0645\u0644\u0641 \u0627\u0644\u0645\u0631\u0633\u0644 \u0643\u0628\u064A\u0631\u0629. \u0645\u0646 \u0641\u0636\u0644\u0643 \u062D\u0627\u0648\u0644 \u0627\u0631\u0633\u0627\u0644 \u0645\u0644\u0641 \u0627\u0635\u063A\u0631.", "validators", "ar");
  t.add("The CSRF token is invalid. Please try to resubmit the form.", "\u0642\u064A\u0645\u0629 \u0631\u0645\u0632 \u0627\u0644\u0645\u0648\u0642\u0639 \u063A\u064A\u0631 \u0635\u062D\u064A\u062D\u0629. \u0645\u0646 \u0641\u0636\u0644\u0643 \u0627\u0639\u062F \u0627\u0631\u0633\u0627\u0644 \u0627\u0644\u0646\u0645\u0648\u0630\u062C.", "validators", "ar");
  t.add("This value is not a valid HTML5 color.", "\u0647\u0630\u0647 \u0627\u0644\u0642\u064A\u0645\u0629 \u0644\u064A\u0633\u062A \u0644\u0648\u0646 HTML5 \u0635\u0627\u0644\u062D\u064B\u0627.", "validators", "ar");
  t.add("Please enter a valid birthdate.", "\u0627\u0644\u0631\u062C\u0627\u0621 \u0627\u062F\u062E\u0627\u0644 \u062A\u0627\u0631\u064A\u062E \u0645\u064A\u0644\u0627\u062F \u0635\u0627\u0644\u062D.", "validators", "ar");
  t.add("The selected choice is invalid.", "\u0627\u0644\u0627\u062E\u062A\u064A\u0627\u0631 \u0627\u0644\u0645\u062D\u062F\u062F \u063A\u064A\u0631 \u0635\u0627\u0644\u062D.", "validators", "ar");
