  t.add("You must select at most {{ limit }} choice.|You must select at most {{ limit }} choices.", "\u0634\u0645\u0627 \u0628\u0627\u06CC\u062F \u062D\u062F\u0627\u06A9\u062B\u0631 {{ limit }} \u06AF\u0632\u06CC\u0646\u0647 \u0627\u0646\u062A\u062E\u0627\u0628 \u0646\u0645\u0627\u06CC\u06CC\u062F.|\u0634\u0645\u0627 \u0628\u0627\u06CC\u062F \u062D\u062F\u0627\u06A9\u062B\u0631 {{ limit }} \u06AF\u0632\u06CC\u0646\u0647 \u0627\u0646\u062A\u062E\u0627\u0628 \u0646\u0645\u0627\u06CC\u06CC\u062F.", "validators", "fa");
