  t.add("This value is not a valid datetime.", "\u0627\u06CC\u0646 \u0645\u0642\u062F\u0627\u0631 \u06CC\u06A9 \u062A\u0627\u0631\u06CC\u062E \u0648 \u0632\u0645\u0627\u0646 \u0645\u0639\u062A\u0628\u0631 \u0646\u0645\u06CC\u200C\u0628\u0627\u0634\u062F.", "validators", "fa");
  t.add("This value is not a valid email address.", "\u0627\u06CC\u0646 \u06CC\u06A9 \u0622\u062F\u0631\u0633 \u0631\u0627\u06CC\u0627\u0646\u0627\u0645\u0647 (\u0627\u06CC\u0645\u06CC\u0644) \u0645\u0639\u062A\u0628\u0631 \u0646\u0645\u06CC\u200C\u0628\u0627\u0634\u062F.", "validators", "fa");
