  t.add("The mime type of the file is invalid ({{ type }}). Allowed mime types are {{ types }}.", "\u0646\u0648\u0639 mime \u0627\u06CC\u0646 \u0641\u0627\u06CC\u0644 \u0646\u0627\u0645\u0639\u062A\u0628\u0631 \u0627\u0633\u062A({{ type }}). \u0627\u0646\u0648\u0627\u0639 mime \u0645\u062C\u0627\u0632 {{ types }} \u0647\u0633\u062A\u0646\u062F.", "validators", "fa");
  t.add("This value should be {{ limit }} or less.", "\u0627\u06CC\u0646 \u0645\u0642\u062F\u0627\u0631 \u0628\u0627\u06CC\u062F \u06A9\u0648\u0686\u06A9\u062A\u0631 \u0648 \u06CC\u0627 \u0645\u0633\u0627\u0648\u06CC {{ limit }} \u0628\u0627\u0634\u062F.", "validators", "fa");
  t.add("This value is too long. It should have {{ limit }} character or less.|This value is too long. It should have {{ limit }} characters or less.", "\u0627\u06CC\u0646 \u0645\u0642\u062F\u0627\u0631 \u0628\u0633\u06CC\u0627\u0631 \u0637\u0648\u0644\u0627\u0646\u06CC \u0627\u0633\u062A. \u0628\u0627\u06CC\u062F \u062F\u0627\u0631\u0627\u06CC {{limit}} \u06A9\u0627\u0631\u0627\u06A9\u062A\u0631 \u06CC\u0627 \u06A9\u0645\u062A\u0631 \u0628\u0627\u0634\u062F. | \u0627\u06CC\u0646 \u0645\u0642\u062F\u0627\u0631 \u0628\u0633\u06CC\u0627\u0631 \u0637\u0648\u0644\u0627\u0646\u06CC \u0627\u0633\u062A. \u0628\u0627\u06CC\u062F \u062F\u0627\u0631\u0627\u06CC {{limit}} \u06A9\u0627\u0631\u0627\u06A9\u062A\u0631 \u06CC\u0627 \u06A9\u0645\u062A\u0631 \u0628\u0627\u0634\u062F.", "validators", "fa");
  t.add("This value should be {{ limit }} or more.", "\u0627\u06CC\u0646 \u0645\u0642\u062F\u0627\u0631 \u0628\u0627\u06CC\u062F \u0628\u0632\u0631\u06AF\u062A\u0631 \u0648 \u06CC\u0627 \u0645\u0633\u0627\u0648\u06CC {{ limit }} \u0628\u0627\u0634\u062F.", "validators", "fa");
  t.add("This value is too short. It should have {{ limit }} character or more.|This value is too short. It should have {{ limit }} characters or more.", "\u0627\u06CC\u0646 \u0645\u0642\u062F\u0627\u0631 \u0628\u06CC\u0634 \u0627\u0632 \u0627\u0646\u062F\u0627\u0632\u0647 \u06A9\u0648\u062A\u0627\u0647 \u0627\u0633\u062A. \u0628\u0627\u06CC\u062F {{ limit }} \u06A9\u0627\u0631\u0627\u06A9\u062A\u0631 \u06CC\u0627 \u0628\u06CC\u0634\u062A\u0631 \u062F\u0627\u0634\u062A\u0647 \u0628\u0627\u0634\u062F.|\u0627\u06CC\u0646 \u0645\u0642\u062F\u0627\u0631 \u0628\u06CC\u0634 \u0627\u0632 \u0627\u0646\u062F\u0627\u0632\u0647 \u06A9\u0648\u062A\u0627\u0647 \u0627\u0633\u062A. \u0628\u0627\u06CC\u062F {{ limit }} \u06A9\u0627\u0631\u0627\u06A9\u062A\u0631 \u06CC\u0627 \u0628\u06CC\u0634\u062A\u0631 \u062F\u0627\u0634\u062A\u0647 \u0628\u0627\u0634\u062F.", "validators", "fa");
  t.add("This value should not be blank.", "\u0627\u06CC\u0646 \u0645\u0642\u062F\u0627\u0631 \u0646\u0628\u0627\u06CC\u062F \u062E\u0627\u0644\u06CC \u0628\u0627\u0634\u062F.", "validators", "fa");
  t.add("This value should not be null.", "\u0627\u06CC\u0646 \u0645\u0642\u062F\u0627\u0631 \u0646\u0628\u0627\u06CC\u062F \u062E\u0627\u0644\u06CC \u0628\u0627\u0634\u062F.", "validators", "fa");
  t.add("This value should be null.", "\u0627\u06CC\u0646 \u0645\u0642\u062F\u0627\u0631 \u0628\u0627\u06CC\u062F \u062E\u0627\u0644\u06CC \u0628\u0627\u0634\u062F.", "validators", "fa");
  t.add("This value is not valid.", "\u0627\u06CC\u0646 \u0645\u0642\u062F\u0627\u0631 \u0645\u0639\u062A\u0628\u0631 \u0646\u0645\u06CC\u200C\u0628\u0627\u0634\u062F.", "validators", "fa");
  t.add("This value is not a valid time.", "\u0627\u06CC\u0646 \u0645\u0642\u062F\u0627\u0631 \u06CC\u06A9 \u0632\u0645\u0627\u0646 \u0645\u0639\u062A\u0628\u0631 \u0646\u0645\u06CC\u200C\u0628\u0627\u0634\u062F.", "validators", "fa");
  t.add("This value is not a valid URL.", "\u0627\u06CC\u0646 \u0645\u0642\u062F\u0627\u0631 \u0634\u0627\u0645\u0644 \u06CC\u06A9 URL \u0645\u0639\u062A\u0628\u0631 \u0646\u0645\u06CC\u200C\u0628\u0627\u0634\u062F.", "validators", "fa");
  t.add("The two values should be equal.", "\u062F\u0648 \u0645\u0642\u062F\u0627\u0631 \u0628\u0627\u06CC\u062F \u0628\u0627 \u06CC\u06A9\u062F\u06CC\u06AF\u0631 \u0628\u0631\u0627\u0628\u0631 \u0628\u0627\u0634\u0646\u062F.", "validators", "fa");
  t.add("The file is too large. Allowed maximum size is {{ limit }} {{ suffix }}.", "\u0641\u0627\u06CC\u0644 \u0628\u06CC\u0634 \u0627\u0632 \u0627\u0646\u062F\u0627\u0632\u0647 \u0628\u0632\u0631\u06AF \u0627\u0633\u062A. \u0628\u06CC\u0634\u06CC\u0646\u0647 (\u062D\u062F\u0627\u06A9\u062B\u0631) \u0627\u0646\u062F\u0627\u0632\u0647 \u0645\u062C\u0627\u0632 {{ limit }} {{ suffix }} \u0627\u0633\u062A.", "validators", "fa");
  t.add("The file is too large.", "\u0641\u0627\u06CC\u0644 \u0628\u06CC\u0634 \u0627\u0632 \u0627\u0646\u062F\u0627\u0632\u0647 \u0628\u0632\u0631\u06AF \u0627\u0633\u062A.", "validators", "fa");
  t.add("The file could not be uploaded.", "\u0628\u0627\u0631\u06AF\u0630\u0627\u0631\u06CC \u0641\u0627\u06CC\u0644 \u0628\u0627 \u0634\u06A9\u0633\u062A \u0645\u0648\u0627\u062C\u0647 \u06AF\u0631\u062F\u06CC\u062F.", "validators", "fa");
  t.add("This value should be a valid number.", "\u0627\u06CC\u0646 \u0645\u0642\u062F\u0627\u0631 \u0628\u0627\u06CC\u062F \u06CC\u06A9 \u0639\u062F\u062F \u0645\u0639\u062A\u0628\u0631 \u0628\u0627\u0634\u062F.", "validators", "fa");
  t.add("This file is not a valid image.", "\u0627\u06CC\u0646 \u0641\u0627\u06CC\u0644 \u06CC\u06A9 \u062A\u0635\u0648\u06CC\u0631 \u0645\u0639\u062A\u0628\u0631 \u0646\u0645\u06CC\u200C\u0628\u0627\u0634\u062F.", "validators", "fa");
  t.add("This is not a valid IP address.", "\u0627\u06CC\u0646 \u0645\u0642\u062F\u0627\u0631 \u06CC\u0647 \u0622\u062F\u0631\u0633 \u0622\u06CC\u200C\u067E\u06CC \u0645\u0639\u062A\u0628\u0631 \u0646\u0645\u06CC\u200C\u0628\u0627\u0634\u062F.", "validators", "fa");
  t.add("This value is not a valid language.", "\u0627\u06CC\u0646 \u0645\u0642\u062F\u0627\u0631 \u06CC\u06A9 \u0632\u0628\u0627\u0646 \u0645\u0639\u062A\u0628\u0631 \u0646\u0645\u06CC\u200C\u0628\u0627\u0634\u062F.", "validators", "fa");
  t.add("This value is not a valid locale.", "\u0627\u06CC\u0646 \u0645\u0642\u062F\u0627\u0631 \u06CC\u06A9 \u0645\u062D\u0644 (locale) \u0645\u0639\u062A\u0628\u0631 \u0646\u0645\u06CC\u200C\u0628\u0627\u0634\u062F.", "validators", "fa");
  t.add("This value is not a valid country.", "\u0627\u06CC\u0646 \u0645\u0642\u062F\u0627\u0631 \u06CC\u06A9 \u06A9\u0634\u0648\u0631 \u0645\u0639\u062A\u0628\u0631 \u0646\u0645\u06CC\u200C\u0628\u0627\u0634\u062F.", "validators", "fa");
  t.add("This value is already used.", "\u0627\u06CC\u0646 \u0645\u0642\u062F\u0627\u0631 \u0642\u0628\u0644\u0627\u064B \u0627\u0633\u062A\u0641\u0627\u062F\u0647 \u0634\u062F\u0647 \u0627\u0633\u062A.", "validators", "fa");
  t.add("The size of the image could not be detected.", "\u0627\u0646\u062F\u0627\u0632\u0647 \u062A\u0635\u0648\u06CC\u0631 \u0642\u0627\u0628\u0644 \u0634\u0646\u0627\u0633\u0627\u06CC\u06CC \u0646\u0645\u06CC\u200C\u0628\u0627\u0634\u062F.", "validators", "fa");
  t.add("The image width is too big ({{ width }}px). Allowed maximum width is {{ max_width }}px.", "\u0639\u0631\u0636 \u062A\u0635\u0648\u06CC\u0631 \u0628\u0633\u06CC\u0627\u0631 \u0628\u0632\u0631\u06AF \u0627\u0633\u062A({{ width }}px). \u0628\u06CC\u0634\u06CC\u0646\u0647 (\u062D\u062F\u0627\u06A9\u062B\u0631) \u0639\u0631\u0636 \u0645\u062C\u0627\u0632 {{ max_width }}px \u0645\u06CC\u200C\u0628\u0627\u0634\u062F.", "validators", "fa");
  t.add("The image width is too small ({{ width }}px). Minimum width expected is {{ min_width }}px.", "\u0639\u0631\u0636 \u062A\u0635\u0648\u06CC\u0631 \u0628\u0633\u06CC\u0627\u0631 \u06A9\u0648\u0686\u06A9 \u0627\u0633\u062A({{ width }}px). \u06A9\u0645\u06CC\u0646\u0647 (\u062D\u062F\u0627\u0642\u0644) \u0639\u0631\u0636 \u0645\u0648\u0631\u062F \u0627\u0646\u062A\u0638\u0627\u0631 {{ min_width }}px \u0645\u06CC\u200C\u0628\u0627\u0634\u062F.", "validators", "fa");
  t.add("The image height is too big ({{ height }}px). Allowed maximum height is {{ max_height }}px.", "\u0627\u0631\u062A\u0641\u0627\u0639 \u062A\u0635\u0648\u06CC\u0631 \u0628\u0633\u06CC\u0627\u0631 \u0628\u0632\u0631\u06AF \u0627\u0633\u062A({{ height }}px). \u0628\u06CC\u0634\u06CC\u0646\u0647 (\u062D\u062F\u0627\u06A9\u062B\u0631) \u0627\u0631\u062A\u0641\u0627\u0639 \u0645\u062C\u0627\u0632 {{ max_height }}px \u0645\u06CC\u200C\u0628\u0627\u0634\u062F.", "validators", "fa");
  t.add("The image height is too small ({{ height }}px). Minimum height expected is {{ min_height }}px.", "\u0627\u0631\u062A\u0641\u0627\u0639 \u062A\u0635\u0648\u06CC\u0631 \u0628\u0633\u06CC\u0627\u0631 \u06A9\u0648\u0686\u06A9 \u0627\u0633\u062A({{ height }}px). \u06A9\u0645\u06CC\u0646\u0647 (\u062D\u062F\u0627\u0642\u0644) \u0627\u0631\u062A\u0641\u0627\u0639 \u0645\u0648\u0631\u062F \u0627\u0646\u062A\u0638\u0627\u0631 {{ min_height }}px \u0645\u06CC\u200C\u0628\u0627\u0634\u062F.", "validators", "fa");
  t.add("This value should be the user's current password.", "\u0627\u06CC\u0646 \u0645\u0642\u062F\u0627\u0631 \u0628\u0627\u06CC\u062F \u0631\u0645\u0632\u0639\u0628\u0648\u0631 \u0641\u0639\u0644\u06CC \u06A9\u0627\u0631\u0628\u0631 \u0628\u0627\u0634\u062F.", "validators", "fa");
  t.add("This value should have exactly {{ limit }} character.|This value should have exactly {{ limit }} characters.", " \u0627\u06CC\u0646 \u0645\u0642\u062F\u0627\u0631 \u0628\u0627\u06CC\u062F \u062F\u0642\u06CC\u0642\u0627 {{ limit }} \u06A9\u0627\u0631\u0627\u06A9\u062A\u0631 \u062F\u0627\u0634\u062A\u0647 \u0628\u0627\u0634\u062F.| \u0627\u06CC\u0646 \u0645\u0642\u062F\u0627\u0631 \u0628\u0627\u06CC\u062F \u062F\u0642\u06CC\u0642\u0627 {{ limit }} \u06A9\u0627\u0631\u0627\u06A9\u062A\u0631 \u062F\u0627\u0634\u062A\u0647 \u0628\u0627\u0634\u062F.", "validators", "fa");
  t.add("The file was only partially uploaded.", "\u0641\u0627\u06CC\u0644 \u0628\u0647 \u0635\u0648\u0631\u062A \u062C\u0632\u0626\u06CC \u0628\u0627\u0631\u06AF\u0630\u0627\u0631\u06CC \u06AF\u0631\u062F\u06CC\u062F\u0647 \u0627\u0633\u062A.", "validators", "fa");
  t.add("No file was uploaded.", "\u0647\u06CC\u0686 \u0641\u0627\u06CC\u0644\u06CC \u0628\u0627\u0631\u06AF\u0630\u0627\u0631\u06CC \u0646\u0634\u062F.", "validators", "fa");
  t.add("No temporary folder was configured in php.ini.", "\u0647\u06CC\u0686 \u067E\u0648\u0634\u0647 \u0645\u0648\u0642\u062A\u06CC \u062F\u0631 php.ini \u067E\u06CC\u06A9\u0631\u0628\u0646\u062F\u06CC \u0646\u0634\u062F\u0647 \u0627\u0633\u062A\u060C \u06CC\u0627 \u067E\u0648\u0634\u0647 \u067E\u06CC\u06A9\u0631\u0628\u0646\u062F\u06CC \u0634\u062F\u0647 \u0648\u062C\u0648\u062F \u0646\u062F\u0627\u0631\u062F.", "validators", "fa");
  t.add("Cannot write temporary file to disk.", "\u0641\u0627\u06CC\u0644 \u0645\u0648\u0642\u062A\u06CC \u0631\u0627 \u0646\u0645\u06CC\u200C\u062A\u0648\u0627\u0646 \u062F\u0631 \u062F\u06CC\u0633\u06A9 \u0646\u0648\u0634\u062A.", "validators", "fa");
  t.add("A PHP extension caused the upload to fail.", "\u06CC\u06A9 \u0627\u0641\u0632\u0648\u0646\u0647 PHP \u0628\u0627\u0639\u062B \u0634\u062F \u0628\u0627\u0631\u06AF\u0630\u0627\u0631\u06CC \u0646\u0627\u0645\u0648\u0641\u0642 \u0628\u0627\u0634\u062F.", "validators", "fa");
  t.add("This collection should contain {{ limit }} element or more.|This collection should contain {{ limit }} elements or more.", "\u0627\u06CC\u0646 \u0645\u062C\u0645\u0648\u0639\u0647 \u0628\u0627\u06CC\u062F \u062D\u0627\u0648\u06CC {{ limit }} \u0639\u0646\u0635\u0631 \u06CC\u0627 \u0628\u06CC\u0634\u062A\u0631 \u0628\u0627\u0634\u062F.|\u0627\u06CC\u0646 \u0645\u062C\u0645\u0648\u0639\u0647 \u0628\u0627\u06CC\u062F \u062D\u0627\u0648\u06CC {{ limit }} \u0639\u0646\u0635\u0631 \u06CC\u0627 \u0628\u06CC\u0634\u062A\u0631 \u0628\u0627\u0634\u062F.", "validators", "fa");
  t.add("This collection should contain {{ limit }} element or less.|This collection should contain {{ limit }} elements or less.", "\u0627\u06CC\u0646 \u0645\u062C\u0645\u0648\u0639\u0647 \u0628\u0627\u06CC\u062F \u062D\u0627\u0648\u06CC {{ limit }} \u0639\u0646\u0635\u0631 \u06CC\u0627 \u06A9\u0645\u062A\u0631 \u0628\u0627\u0634\u062F.|\u0627\u06CC\u0646 \u0645\u062C\u0645\u0648\u0639\u0647 \u0628\u0627\u06CC\u062F \u062D\u0627\u0648\u06CC {{ limit }} \u0639\u0646\u0635\u0631 \u06CC\u0627 \u06A9\u0645\u062A\u0631 \u0628\u0627\u0634\u062F.", "validators", "fa");
  t.add("This collection should contain exactly {{ limit }} element.|This collection should contain exactly {{ limit }} elements.", "\u0627\u06CC\u0646 \u0645\u062C\u0645\u0648\u0639\u0647 \u0628\u0627\u06CC\u062F \u062F\u0642\u06CC\u0642\u0627 \u062D\u0627\u0648\u06CC {{ limit }} \u0639\u0646\u0635\u0631 \u0628\u0627\u0634\u062F.|\u0627\u06CC\u0646 \u0645\u062C\u0645\u0648\u0639\u0647 \u0628\u0627\u06CC\u062F \u062F\u0642\u06CC\u0642\u0627 \u062D\u0627\u0648\u06CC {{ limit }} \u0639\u0646\u0635\u0631 \u0628\u0627\u0634\u062F.", "validators", "fa");
  t.add("Invalid card number.", "\u0634\u0645\u0627\u0631\u0647 \u06A9\u0627\u0631\u062A \u0646\u0627\u0645\u0639\u062A\u0628\u0631 \u0627\u0633\u062A.", "validators", "fa");
  t.add("Unsupported card type or invalid card number.", "\u0646\u0648\u0639 \u06A9\u0627\u0631\u062A \u067E\u0634\u062A\u06CC\u0628\u0627\u0646\u06CC \u0646\u0645\u06CC\u200C\u0634\u0648\u062F \u0648 \u06CC\u0627 \u0634\u0645\u0627\u0631\u0647 \u06A9\u0627\u0631\u062A \u0646\u0627\u0645\u0639\u062A\u0628\u0631 \u0645\u06CC\u200C\u0628\u0627\u0634\u062F.", "validators", "fa");
  t.add("This is not a valid International Bank Account Number (IBAN).", "\u0627\u06CC\u0646 \u0645\u0642\u062F\u0627\u0631 \u06CC\u06A9 \u0634\u0645\u0627\u0631\u0647 \u0634\u0628\u0627\u06CC \u0645\u0639\u062A\u0628\u0631 \u0646\u0645\u06CC\u200C\u0628\u0627\u0634\u062F.", "validators", "fa");
  t.add("This value is not a valid ISBN-10.", "\u0627\u06CC\u0646 \u0645\u0642\u062F\u0627\u0631 \u06CC\u06A9 ISBN-10 \u0645\u0639\u062A\u0628\u0631 \u0646\u0645\u06CC\u200C\u0628\u0627\u0634\u062F.", "validators", "fa");
  t.add("This value is not a valid ISBN-13.", "\u0627\u06CC\u0646 \u0645\u0642\u062F\u0627\u0631 \u06CC\u06A9 ISBN-13 \u0645\u0639\u062A\u0628\u0631 \u0646\u0645\u06CC\u200C\u0628\u0627\u0634\u062F.", "validators", "fa");
  t.add("This value is neither a valid ISBN-10 nor a valid ISBN-13.", "\u0627\u06CC\u0646 \u0645\u0642\u062F\u0627\u0631 \u06CC\u06A9 ISBN-10 \u0645\u0639\u062A\u0628\u0631 \u0648 \u06CC\u0627 ISBN-13 \u0645\u0639\u062A\u0628\u0631 \u0646\u0645\u06CC\u200C\u0628\u0627\u0634\u062F.", "validators", "fa");
  t.add("This value is not a valid ISSN.", "\u0627\u06CC\u0646 \u0645\u0642\u062F\u0627\u0631 \u06CC\u06A9 ISSN \u0645\u0639\u062A\u0628\u0631 \u0646\u0645\u06CC\u200C\u0628\u0627\u0634\u062F.", "validators", "fa");
  t.add("This value is not a valid currency.", "\u0627\u06CC\u0646 \u0645\u0642\u062F\u0627\u0631 \u06CC\u06A9 \u0648\u0627\u062D\u062F \u067E\u0648\u0644 \u0645\u0639\u062A\u0628\u0631 \u0646\u0645\u06CC\u200C\u0628\u0627\u0634\u062F.", "validators", "fa");
  t.add("This value should be equal to {{ compared_value }}.", "\u0627\u06CC\u0646 \u0645\u0642\u062F\u0627\u0631 \u0628\u0627\u06CC\u062F \u0628\u0631\u0627\u0628\u0631 \u0628\u0627 {{ compared_value }} \u0628\u0627\u0634\u062F.", "validators", "fa");
  t.add("This value should be greater than {{ compared_value }}.", "\u0627\u06CC\u0646 \u0645\u0642\u062F\u0627\u0631 \u0628\u0627\u06CC\u062F \u0627\u0632 {{ compared_value }} \u0628\u06CC\u0634\u062A\u0631 \u0628\u0627\u0634\u062F.", "validators", "fa");
  t.add("This value should be greater than or equal to {{ compared_value }}.", "\u0627\u06CC\u0646 \u0645\u0642\u062F\u0627\u0631 \u0628\u0627\u06CC\u062F \u0628\u0632\u0631\u06AF\u062A\u0631 \u0648 \u06CC\u0627 \u0645\u0633\u0627\u0648\u06CC \u0628\u0627 {{ compared_value }} \u0628\u0627\u0634\u062F.", "validators", "fa");
  t.add("This value should be identical to {{ compared_value_type }} {{ compared_value }}.", "\u0627\u06CC\u0646 \u0645\u0642\u062F\u0627\u0631 \u0628\u0627\u06CC\u062F \u0628\u0631\u0627\u0628\u0631 {{ compared_value_type }} {{ compared_value }} \u0628\u0627\u0634\u062F.", "validators", "fa");
  t.add("This value should be less than {{ compared_value }}.", "\u0627\u06CC\u0646 \u0645\u0642\u062F\u0627\u0631 \u0628\u0627\u06CC\u062F \u06A9\u0645\u062A\u0631 \u0627\u0632 {{ compared_value }} \u0628\u0627\u0634\u062F.", "validators", "fa");
  t.add("This value should be less than or equal to {{ compared_value }}.", "\u0627\u06CC\u0646 \u0645\u0642\u062F\u0627\u0631 \u0628\u0627\u06CC\u062F \u06A9\u0645\u062A\u0631 \u0648 \u06CC\u0627 \u0645\u0633\u0627\u0648\u06CC \u0628\u0627 {{ compared_value }} \u0628\u0627\u0634\u062F.", "validators", "fa");
  t.add("This value should not be equal to {{ compared_value }}.", "\u0627\u06CC\u0646 \u0645\u0642\u062F\u0627\u0631 \u0646\u0628\u0627\u06CC\u062F \u0628\u0627 {{ compared_value }} \u0628\u0631\u0627\u0628\u0631 \u0628\u0627\u0634\u062F.", "validators", "fa");
  t.add("This value should not be identical to {{ compared_value_type }} {{ compared_value }}.", "\u0627\u06CC\u0646 \u0645\u0642\u062F\u0627\u0631 \u0646\u0628\u0627\u06CC\u062F \u0628\u0631\u0627\u0628\u0631 {{ compared_value_type }} {{ compared_value }} \u0628\u0627\u0634\u062F.", "validators", "fa");
  t.add("The image ratio is too big ({{ ratio }}). Allowed maximum ratio is {{ max_ratio }}.", "\u0627\u0628\u0639\u0627\u062F ({{ ratio }}) \u0639\u06A9\u0633 \u0628\u06CC\u0634 \u0627\u0632 \u062D\u062F \u0628\u0632\u0631\u06AF \u0627\u0633\u062A. \u0628\u06CC\u0634\u06CC\u0646\u0647 (\u062D\u062F\u0627\u06A9\u062B\u0631) \u0627\u0628\u0639\u0627\u062F \u0645\u062C\u0627\u0632 {{ max_ratio }} \u0645\u06CC\u200C\u0628\u0627\u0634\u062F.", "validators", "fa");
  t.add("The image ratio is too small ({{ ratio }}). Minimum ratio expected is {{ min_ratio }}.", "\u0627\u0628\u0639\u0627\u062F ({{ ratio }}) \u0639\u06A9\u0633 \u0628\u06CC\u0634 \u0627\u0632 \u062D\u062F \u06A9\u0648\u0686\u06A9 \u0627\u0633\u062A. \u06A9\u0645\u06CC\u0646\u0647 (\u062D\u062F\u0627\u0642\u0644) \u0627\u0628\u0639\u0627\u062F \u0645\u0648\u0631\u062F \u0627\u0646\u062A\u0638\u0627\u0631 {{ min_ratio }} \u0645\u06CC\u200C\u0628\u0627\u0634\u062F.", "validators", "fa");
  t.add("The image is square ({{ width }}x{{ height }}px). Square images are not allowed.", "\u0627\u06CC\u0646 \u062A\u0635\u0648\u06CC\u0631 \u06CC\u06A9 \u0645\u0631\u0628\u0639 ({{ width }}x{{ height }}px) \u0645\u06CC\u200C\u0628\u0627\u0634\u062F. \u062A\u0635\u0627\u0648\u06CC\u0631 \u0645\u0631\u0628\u0639 \u0634\u06A9\u0644 \u0645\u062C\u0627\u0632 \u0646\u0645\u06CC\u200C\u0628\u0627\u0634\u0646\u062F.", "validators", "fa");
  t.add("The image is landscape oriented ({{ width }}x{{ height }}px). Landscape oriented images are not allowed.", "\u0627\u06CC\u0646 \u062A\u0635\u0648\u06CC\u0631 \u0627\u0641\u0642\u06CC ({{ width }}x{{ height }}px) \u0645\u06CC\u200C\u0628\u0627\u0634\u062F. \u062A\u0635\u0627\u0648\u06CC\u0631 \u0627\u0641\u0642\u06CC \u0645\u062C\u0627\u0632 \u0646\u0645\u06CC\u200C\u0628\u0627\u0634\u0646\u062F.", "validators", "fa");
  t.add("The image is portrait oriented ({{ width }}x{{ height }}px). Portrait oriented images are not allowed.", "\u0627\u06CC\u0646 \u062A\u0635\u0648\u06CC\u0631 \u0639\u0645\u0648\u062F\u06CC ({{ width }}x{{ height }}px) \u0645\u06CC\u200C\u0628\u0627\u0634\u062F. \u062A\u0635\u0627\u0648\u06CC\u0631 \u0639\u0645\u0648\u062F\u06CC \u0645\u062C\u0627\u0632 \u0646\u0645\u06CC\u200C\u0628\u0627\u0634\u0646\u062F.", "validators", "fa");
  t.add("An empty file is not allowed.", "\u0641\u0627\u06CC\u0644 \u062E\u0627\u0644\u06CC \u0645\u062C\u0627\u0632 \u0646\u0645\u06CC\u200C\u0628\u0627\u0634\u062F.", "validators", "fa");
  t.add("The host could not be resolved.", "\u0645\u06CC\u0632\u0628\u0627\u0646 (Host) \u0634\u0646\u0627\u0633\u0627\u06CC\u06CC \u0646\u0634\u062F.", "validators", "fa");
  t.add("This value does not match the expected {{ charset }} charset.", "\u0627\u06CC\u0646 \u0645\u0642\u062F\u0627\u0631 \u0645\u0637\u0627\u0628\u0642 charset \u0645\u0648\u0631\u062F \u0627\u0646\u062A\u0638\u0627\u0631 {{ charset }} \u0646\u0645\u06CC \u0628\u0627\u0634\u062F.", "validators", "fa");
  t.add("This is not a valid Business Identifier Code (BIC).", "\u0627\u06CC\u0646 \u0645\u0642\u062F\u0627\u0631 \u06CC\u06A9 \u06A9\u062F \u0634\u0646\u0627\u0633\u0647 \u06A9\u0633\u0628\u200C\u0648\u06A9\u0627\u0631 (BIC) \u0645\u0639\u062A\u0628\u0631 \u0646\u06CC\u0633\u062A.", "validators", "fa");
  t.add("Error", "\u062E\u0637\u0627", "validators", "fa");
  t.add("This is not a valid UUID.", "\u0627\u06CC\u0646 \u0645\u0642\u062F\u0627\u0631 \u06CC\u06A9 UUID \u0645\u0639\u062A\u0628\u0631 \u0646\u06CC\u0633\u062A.", "validators", "fa");
  t.add("This value should be a multiple of {{ compared_value }}.", "\u0627\u06CC\u0646 \u0645\u0642\u062F\u0627\u0631 \u0628\u0627\u06CC\u062F \u0686\u0646\u062F \u0628\u0631\u0627\u0628\u0631 {{ compared_value }} \u0628\u0627\u0634\u062F.", "validators", "fa");
  t.add("This Business Identifier Code (BIC) is not associated with IBAN {{ iban }}.", "\u0627\u06CC\u0646 \u06A9\u062F \u0634\u0646\u0627\u0633\u0627\u06CC\u06CC \u06A9\u0633\u0628\u200C\u0648\u200C\u06A9\u0627\u0631 (BIC) \u0628\u0627 \u0634\u0645\u0627\u0631\u0647 \u062D\u0633\u0627\u0628 \u0628\u0627\u0646\u06A9\u06CC \u0628\u06CC\u0646\u200C\u0627\u0644\u0645\u0644\u0644\u06CC (IBAN) {{ iban }} \u0645\u0631\u062A\u0628\u0637 \u0646\u06CC\u0633\u062A.", "validators", "fa");
  t.add("This value should be valid JSON.", "\u0627\u06CC\u0646 \u0645\u0642\u062F\u0627\u0631 \u0628\u0627\u06CC\u062F \u06CC\u06A9 JSON \u0645\u0639\u062A\u0628\u0631 \u0628\u0627\u0634\u062F.", "validators", "fa");
  t.add("This collection should contain only unique elements.", "\u0627\u06CC\u0646 \u0645\u062C\u0645\u0648\u0639\u0647 \u0628\u0627\u06CC\u062F \u0641\u0642\u0637 \u062D\u0627\u0648\u06CC \u0639\u0646\u0627\u0635\u0631 \u06CC\u06A9\u062A\u0627 \u0628\u0627\u0634\u062F.", "validators", "fa");
  t.add("This value should be positive.", "\u0627\u06CC\u0646 \u0645\u0642\u062F\u0627\u0631 \u0628\u0627\u06CC\u062F \u0645\u062B\u0628\u062A \u0628\u0627\u0634\u062F.", "validators", "fa");
  t.add("This value should be either positive or zero.", "\u0627\u06CC\u0646 \u0645\u0642\u062F\u0627\u0631 \u0628\u0627\u06CC\u062F \u0645\u062B\u0628\u062A \u06CC\u0627 \u0635\u0641\u0631 \u0628\u0627\u0634\u062F.", "validators", "fa");
  t.add("This value should be negative.", "\u0627\u06CC\u0646 \u0645\u0642\u062F\u0627\u0631 \u0628\u0627\u06CC\u062F \u0645\u0646\u0641\u06CC \u0628\u0627\u0634\u062F.", "validators", "fa");
  t.add("This value should be either negative or zero.", "\u0627\u06CC\u0646 \u0645\u0642\u062F\u0627\u0631 \u0628\u0627\u06CC\u062F \u0645\u0646\u0641\u06CC \u06CC\u0627 \u0635\u0641\u0631 \u0628\u0627\u0634\u062F.", "validators", "fa");
  t.add("This value is not a valid timezone.", "\u0627\u06CC\u0646 \u0645\u0642\u062F\u0627\u0631 \u06CC\u06A9 \u0645\u0646\u0637\u0642\u0647\u200C\u0632\u0645\u0627\u0646\u06CC (timezone) \u0645\u0639\u062A\u0628\u0631 \u0646\u06CC\u0633\u062A.", "validators", "fa");
  t.add("This password has been leaked in a data breach, it must not be used. Please use another password.", "\u0627\u06CC\u0646 \u0631\u0645\u0632\u0639\u0628\u0648\u0631 \u062F\u0631 \u06CC\u06A9 \u0631\u062E\u0646\u0647\u200C\u06CC \u0627\u0637\u0644\u0627\u0639\u0627\u062A\u06CC \u0646\u0634\u062A \u06A9\u0631\u062F\u0647 \u0627\u0633\u062A. \u0644\u0637\u0641\u0627\u064B \u0627\u0632 \u06CC\u06A9 \u0631\u0645\u0632\u0639\u0628\u0648\u0631 \u062F\u06CC\u06AF\u0631 \u0627\u0633\u062A\u0641\u0627\u062F\u0647 \u06A9\u0646\u06CC\u062F.", "validators", "fa");
  t.add("This value should be between {{ min }} and {{ max }}.", "\u0627\u06CC\u0646 \u0645\u0642\u062F\u0627\u0631 \u0628\u0627\u06CC\u062F \u0628\u06CC\u0646 {{ min }} \u0648 {{ max }} \u0628\u0627\u0634\u062F", "validators", "fa");
  t.add("This value is not a valid hostname.", "\u0627\u06CC\u0646 \u0645\u0642\u062F\u0627\u0631 \u06CC\u06A9 hostname \u0645\u0639\u062A\u0628\u0631 \u0646\u06CC\u0633\u062A.", "validators", "fa");
  t.add("The number of elements in this collection should be a multiple of {{ compared_value }}.", "\u062A\u0639\u062F\u0627\u062F \u0639\u0646\u0627\u0635\u0631 \u0627\u06CC\u0646 \u0645\u062C\u0645\u0648\u0639\u0647 \u0628\u0627\u06CC\u062F \u0636\u0631\u06CC\u0628\u06CC \u0627\u0632 {{ compared_value }} \u0628\u0627\u0634\u062F.", "validators", "fa");
  t.add("This value should satisfy at least one of the following constraints:", "\u0627\u06CC\u0646 \u0645\u0642\u062F\u0627\u0631 \u0628\u0627\u06CC\u062F \u062D\u062F\u0627\u0642\u0644 \u06CC\u06A9\u06CC \u0627\u0632 \u0645\u062D\u062F\u0648\u062F\u06CC\u062A\u200C\u0647\u0627\u06CC \u0632\u06CC\u0631 \u0631\u0627 \u0627\u0631\u0636\u0627 \u06A9\u0646\u062F:", "validators", "fa");
  t.add("Each element of this collection should satisfy its own set of constraints.", "\u0647\u0631 \u06CC\u06A9 \u0627\u0632 \u0639\u0646\u0627\u0635\u0631 \u0627\u06CC\u0646 \u0645\u062C\u0645\u0648\u0639\u0647 \u0628\u0627\u06CC\u062F \u062F\u0633\u062A\u0647 \u0645\u062D\u062F\u0648\u062F\u06CC\u062A\u200C\u0647\u0627\u06CC \u062E\u0648\u062F\u0634 \u0631\u0627 \u0627\u0631\u0636\u0627 \u06A9\u0646\u062F.", "validators", "fa");
  t.add("This value is not a valid International Securities Identification Number (ISIN).", "\u0627\u06CC\u0646 \u0645\u0642\u062F\u0627\u0631 \u06CC\u06A9 \u0634\u0645\u0627\u0631\u0647 \u0634\u0646\u0627\u0633\u0627\u06CC\u06CC \u0628\u06CC\u0646\u200C\u0627\u0644\u0645\u0644\u0644\u06CC \u0627\u0648\u0631\u0627\u0642 \u0628\u0647\u0627\u062F\u0627\u0631 (ISIN) \u0645\u0639\u062A\u0628\u0631 \u0646\u06CC\u0633\u062A.", "validators", "fa");
  t.add("This value should be a valid expression.", "\u0627\u06CC\u0646 \u0645\u0642\u062F\u0627\u0631 \u0628\u0627\u06CC\u062F \u06CC\u06A9 \u0639\u0628\u0627\u0631\u062A \u0645\u0639\u062A\u0628\u0631 \u0628\u0627\u0634\u062F.", "validators", "fa");
  t.add("This value is not a valid CSS color.", "\u0627\u06CC\u0646 \u0645\u0642\u062F\u0627\u0631 \u06CC\u06A9 \u0631\u0646\u06AF \u0645\u0639\u062A\u0628\u0631 \u062F\u0631 CSS \u0646\u06CC\u0633\u062A.", "validators", "fa");
  t.add("This value is not a valid CIDR notation.", "\u0627\u06CC\u0646 \u0645\u0642\u062F\u0627\u0631 \u06CC\u06A9 \u0646\u0645\u0627\u062F \u0645\u0639\u062A\u0628\u0631 \u062F\u0631 CIDR \u0646\u06CC\u0633\u062A.", "validators", "fa");
  t.add("The value of the netmask should be between {{ min }} and {{ max }}.", "\u0645\u0642\u062F\u0627\u0631 \u0645\u0627\u0633\u06A9 \u0634\u0628\u06A9\u0647 (NetMask) \u0628\u0627\u06CC\u062F \u0628\u06CC\u0646 {{ min }} \u0648 {{ max }} \u0628\u0627\u0634\u062F.", "validators", "fa");
  t.add("The filename is too long. It should have {{ filename_max_length }} character or less.|The filename is too long. It should have {{ filename_max_length }} characters or less.", "\u0646\u0627\u0645 \u0641\u0627\u06CC\u0644 \u0637\u0648\u0644\u0627\u0646\u06CC \u0627\u0633\u062A. \u0646\u0627\u0645 \u0641\u0627\u06CC\u0644 \u0628\u0627\u06CC\u062F {{ filename_max_length }} \u06A9\u0627\u0631\u0627\u06A9\u062A\u0631 \u06CC\u0627 \u06A9\u0645\u062A\u0631 \u0628\u0627\u0634\u062F.|\u0646\u0627\u0645 \u0641\u0627\u06CC\u0644 \u0637\u0648\u0644\u0627\u0646\u06CC \u0627\u0633\u062A. \u0646\u0627\u0645 \u0641\u0627\u06CC\u0644 \u0628\u0627\u06CC\u062F {{ filename_max_length }} \u06A9\u0627\u0631\u0627\u06A9\u062A\u0631 \u06CC\u0627 \u06A9\u0645\u062A\u0631 \u0628\u0627\u0634\u062F.", "validators", "fa");
  t.add("The password strength is too low. Please use a stronger password.", "\u0631\u0645\u0632 \u0639\u0628\u0648\u0631 \u0636\u0639\u06CC\u0641 \u0627\u0633\u062A. \u0644\u0637\u0641\u0627 \u0627\u0632 \u0631\u0645\u0632 \u0639\u0628\u0648\u0631 \u0642\u0648\u06CC\u200C\u062A\u0631\u06CC \u0627\u0633\u062A\u0641\u0627\u062F\u0647 \u06A9\u0646\u06CC\u062F.", "validators", "fa");
  t.add("This value contains characters that are not allowed by the current restriction-level.", "\u0627\u06CC\u0646 \u0645\u0642\u062F\u0627\u0631 \u062D\u0627\u0648\u06CC \u06A9\u0627\u0631\u0627\u06A9\u062A\u0631\u0647\u0627\u06CC\u06CC \u0627\u0633\u062A \u06A9\u0647 \u062F\u0631 \u0633\u0637\u062D \u0645\u062D\u062F\u0648\u062F\u06CC\u062A \u0641\u0639\u0644\u06CC \u0645\u062C\u0627\u0632 \u0646\u06CC\u0633\u062A\u0646\u062F.", "validators", "fa");
  t.add("Using invisible characters is not allowed.", "\u0627\u0633\u062A\u0641\u0627\u062F\u0647 \u0627\u0632 \u06A9\u0627\u0631\u0627\u06A9\u062A\u0631\u0647\u0627\u06CC \u0646\u0627\u0645\u0631\u0626\u06CC \u0645\u062C\u0627\u0632 \u0646\u0645\u06CC\u200C\u0628\u0627\u0634\u062F.", "validators", "fa");
  t.add("Mixing numbers from different scripts is not allowed.", "\u0645\u062E\u0644\u0648\u0637 \u06A9\u0631\u062F\u0646 \u0627\u0639\u062F\u0627\u062F \u0627\u0632 \u0627\u0633\u06A9\u0631\u06CC\u067E\u062A \u0647\u0627\u06CC \u0645\u062E\u062A\u0644\u0641 \u0645\u062C\u0627\u0632 \u0646\u06CC\u0633\u062A.", "validators", "fa");
  t.add("Using hidden overlay characters is not allowed.", "\u0627\u0633\u062A\u0641\u0627\u062F\u0647 \u0627\u0632 \u06A9\u0627\u0631\u0627\u06A9\u062A\u0631\u0647\u0627\u06CC \u0647\u0645\u067E\u0648\u0634\u0627\u0646\u06CC \u067E\u0646\u0647\u0627\u0646 (hidden overlay characters) \u0645\u062C\u0627\u0632 \u0646\u06CC\u0633\u062A.", "validators", "fa");
  t.add("The extension of the file is invalid ({{ extension }}). Allowed extensions are {{ extensions }}.", "\u067E\u0633\u0648\u0646\u062F \u0641\u0627\u06CC\u0644 ({{ extension }}) \u0646\u0627\u0645\u0639\u062A\u0628\u0631 \u0627\u0633\u062A. \u067E\u0633\u0648\u0646\u062F\u0647\u0627\u06CC \u0645\u062C\u0627\u0632 {{ extensions }} \u0647\u0633\u062A\u0646\u062F.", "validators", "fa");
  t.add("The detected character encoding is invalid ({{ detected }}). Allowed encodings are {{ encodings }}.", "\u0631\u0645\u0632\u06AF\u0630\u0627\u0631\u06CC \u06A9\u0627\u0631\u0627\u06A9\u062A\u0631 \u062A\u0634\u062E\u06CC\u0635 \u062F\u0627\u062F\u0647 \u0634\u062F\u0647 ({{ detected }}) \u0646\u0627\u0645\u0639\u062A\u0628\u0631 \u0627\u0633\u062A. \u0631\u0645\u0632\u06AF\u0630\u0627\u0631\u06CC\u200C\u0647\u0627\u06CC \u0645\u062C\u0627\u0632 {{ encodings }} \u0647\u0633\u062A\u0646\u062F.", "validators", "fa");
  t.add("This value is not a valid MAC address.", "\u0627\u06CC\u0646 \u0645\u0642\u062F\u0627\u0631 \u06CC\u06A9 \u0622\u062F\u0631\u0633 MAC \u0645\u0639\u062A\u0628\u0631 \u0646\u06CC\u0633\u062A.", "validators", "fa");
  t.add("This URL is missing a top-level domain.", "\u0627\u06CC\u0646 \u0622\u062F\u0631\u0633 \u062F\u0627\u0631\u0627\u06CC \u062F\u0627\u0645\u0646\u0647 \u0646\u0645\u06CC\u200C\u0628\u0627\u0634\u062F.", "validators", "fa");
