  t.add("This field is missing.", "\u05E9\u05D3\u05D4 \u05D6\u05D4 \u05D7\u05E1\u05E8.", "validators", "he");
  t.add("This value is not a valid date.", "\u05D4\u05E2\u05E8\u05DA \u05D0\u05D9\u05E0\u05D5 \u05EA\u05D0\u05E8\u05D9\u05DA \u05D7\u05D5\u05E7\u05D9.", "validators", "he");
  t.add("This value is not a valid datetime.", "\u05D4\u05E2\u05E8\u05DA \u05D0\u05D9\u05E0\u05D5 \u05EA\u05D0\u05E8\u05D9\u05DA \u05D5\u05E9\u05E2\u05D4 \u05D7\u05D5\u05E7\u05D9\u05D9\u05DD.", "validators", "he");
  t.add("This value is not a valid email address.", "\u05DB\u05EA\u05D5\u05D1\u05EA \u05D4\u05DE\u05D9\u05D9\u05DC \u05D0\u05D9\u05E0\u05D4 \u05EA\u05E7\u05D9\u05E0\u05D4.", "validators", "he");
  t.add("The file could not be found.", "\u05D4\u05E7\u05D5\u05D1\u05E5 \u05DC\u05D0 \u05E0\u05DE\u05E6\u05D0.", "validators", "he");
  t.add("The file is not readable.", "\u05DC\u05D0 \u05E0\u05D9\u05EA\u05DF \u05DC\u05E7\u05E8\u05D5\u05D0 \u05D0\u05EA \u05D4\u05E7\u05D5\u05D1\u05E5.", "validators", "he");
  t.add("The file is too large ({{ size }} {{ suffix }}). Allowed maximum size is {{ limit }} {{ suffix }}.", "\u05D4\u05E7\u05D5\u05D1\u05E5 \u05D2\u05D3\u05D5\u05DC \u05DE\u05D3\u05D9 ({{ size }} {{ suffix }}). \u05D4\u05D2\u05D5\u05D3\u05DC \u05D4\u05DE\u05E8\u05D1\u05D9 \u05D4\u05DE\u05D5\u05EA\u05E8 \u05D4\u05D5\u05D0 {{ limit }} {{ suffix }}.", "validators", "he");
  t.add("The mime type of the file is invalid ({{ type }}). Allowed mime types are {{ types }}.", "\u05E1\u05D5\u05D2 MIME \u05E9\u05DC \u05D4\u05E7\u05D5\u05D1\u05E5 \u05D0\u05D9\u05E0\u05D5 \u05D7\u05D5\u05E7\u05D9 ({{ type }}). \u05DE\u05D5\u05EA\u05E8\u05D9\u05DD \u05E1\u05D5\u05D2\u05D9 MIME {{ types }}.", "validators", "he");
  t.add("This value should be {{ limit }} or less.", "\u05D4\u05E2\u05E8\u05DA \u05E6\u05E8\u05D9\u05DA \u05DC\u05D4\u05DB\u05D9\u05DC {{ limit }} \u05EA\u05D5\u05D5\u05D9\u05DD \u05DC\u05DB\u05DC \u05D4\u05D9\u05D5\u05EA\u05E8.", "validators", "he");
  t.add("This value is too long. It should have {{ limit }} character or less.|This value is too long. It should have {{ limit }} characters or less.", "\u05D4\u05E2\u05E8\u05DA \u05D0\u05E8\u05D5\u05DA \u05DE\u05D9\u05D3\u05D9. \u05D4\u05D5\u05D0 \u05E6\u05E8\u05D9\u05DA \u05DC\u05D4\u05DB\u05D9\u05DC {{ limit }} \u05EA\u05D5\u05D5\u05D9\u05DD \u05DC\u05DB\u05DC \u05D4\u05D9\u05D5\u05EA\u05E8.|\u05D4\u05E2\u05E8\u05DA \u05D0\u05E8\u05D5\u05DA \u05DE\u05D9\u05D3\u05D9. \u05D4\u05D5\u05D0 \u05E6\u05E8\u05D9\u05DA \u05DC\u05D4\u05DB\u05D9\u05DC {{ limit }} \u05EA\u05D5\u05D5\u05D9\u05DD \u05DC\u05DB\u05DC \u05D4\u05D9\u05D5\u05EA\u05E8.", "validators", "he");
  t.add("This value should be {{ limit }} or more.", "\u05D4\u05E2\u05E8\u05DA \u05E6\u05E8\u05D9\u05DA \u05DC\u05D4\u05DB\u05D9\u05DC {{ limit }} \u05EA\u05D5\u05D5\u05D9\u05DD \u05DC\u05E4\u05D7\u05D5\u05EA.", "validators", "he");
  t.add("This value is too short. It should have {{ limit }} character or more.|This value is too short. It should have {{ limit }} characters or more.", "\u05D4\u05E2\u05E8\u05DA \u05E7\u05E6\u05E8 \u05DE\u05D9\u05D3\u05D9. \u05D4\u05D5\u05D0 \u05E6\u05E8\u05D9\u05DA \u05DC\u05D4\u05DB\u05D9\u05DC {{ limit }} \u05EA\u05D5\u05D5\u05D9\u05DD \u05DC\u05E4\u05D7\u05D5\u05EA.|\u05D4\u05E2\u05E8\u05DA \u05E7\u05E6\u05E8 \u05DE\u05D9\u05D3\u05D9. \u05D4\u05E2\u05E8\u05DA \u05E6\u05E8\u05D9\u05DA \u05DC\u05D4\u05DB\u05D9\u05DC {{ limit }} \u05EA\u05D5\u05D5\u05D9\u05DD \u05DC\u05E4\u05D7\u05D5\u05EA.", "validators", "he");
  t.add("This value should not be blank.", "\u05D4\u05E2\u05E8\u05DA \u05DC\u05D0 \u05D0\u05DE\u05D5\u05E8 \u05DC\u05D4\u05D9\u05D5\u05EA \u05E8\u05D9\u05E7.", "validators", "he");
  t.add("This value should not be null.", "\u05D4\u05E2\u05E8\u05DA \u05DC\u05D0 \u05D0\u05DE\u05D5\u05E8 \u05DC\u05D4\u05D9\u05D5\u05EA \u05E8\u05D9\u05E7.", "validators", "he");
  t.add("This value should be null.", "\u05D4\u05E2\u05E8\u05DA \u05E6\u05E8\u05D9\u05DA \u05DC\u05D4\u05D9\u05D5\u05EA \u05E8\u05D9\u05E7.", "validators", "he");
  t.add("This value is not valid.", "\u05D4\u05E2\u05E8\u05DA \u05D0\u05D9\u05E0\u05D5 \u05D7\u05D5\u05E7\u05D9.", "validators", "he");
  t.add("This value is not a valid time.", "\u05D4\u05E2\u05E8\u05DA \u05D0\u05D9\u05E0\u05D5 \u05D6\u05DE\u05DF \u05EA\u05E7\u05D9\u05DF.", "validators", "he");
  t.add("This value is not a valid URL.", "\u05D6\u05D0\u05EA \u05D0\u05D9\u05E0\u05D4 \u05DB\u05EA\u05D5\u05D1\u05EA \u05D0\u05EA\u05E8 \u05EA\u05E7\u05D9\u05E0\u05D4.", "validators", "he");
  t.add("The two values should be equal.", "\u05E9\u05E0\u05D9 \u05D4\u05E2\u05E8\u05DB\u05D9\u05DD \u05E6\u05E8\u05D9\u05DB\u05D9\u05DD \u05DC\u05D4\u05D9\u05D5\u05EA \u05E9\u05D5\u05D5\u05D9\u05DD.", "validators", "he");
  t.add("The file is too large. Allowed maximum size is {{ limit }} {{ suffix }}.", "\u05D4\u05E7\u05D5\u05D1\u05E5 \u05D2\u05D3\u05D5\u05DC \u05DE\u05D3\u05D9. \u05D4\u05D2\u05D5\u05D3\u05DC \u05D4\u05DE\u05E8\u05D1\u05D9 \u05D4\u05DE\u05D5\u05EA\u05E8 \u05D4\u05D5\u05D0 {{ limit }} {{ suffix }}.", "validators", "he");
  t.add("The file is too large.", "\u05D4\u05E7\u05D5\u05D1\u05E5 \u05D2\u05D3\u05D5\u05DC \u05DE\u05D3\u05D9.", "validators", "he");
  t.add("The file could not be uploaded.", "\u05DC\u05D0 \u05E0\u05D9\u05EA\u05DF \u05DC\u05E2\u05DC\u05D5\u05EA \u05D0\u05EA \u05D4\u05E7\u05D5\u05D1\u05E5.", "validators", "he");
  t.add("This value should be a valid number.", "\u05D4\u05E2\u05E8\u05DA \u05E6\u05E8\u05D9\u05DA \u05DC\u05D4\u05D9\u05D5\u05EA \u05DE\u05E1\u05E4\u05E8 \u05D7\u05D5\u05E7\u05D9.", "validators", "he");
  t.add("This file is not a valid image.", "\u05D4\u05E7\u05D5\u05D1\u05E5 \u05D4\u05D6\u05D4 \u05D0\u05D9\u05E0\u05D5 \u05EA\u05DE\u05D5\u05E0\u05D4 \u05EA\u05E7\u05D9\u05E0\u05D4.", "validators", "he");
  t.add("This is not a valid IP address.", "\u05E2\u05E8\u05DA \u05D6\u05D4 \u05D0\u05D9\u05E0\u05D5 \u05DB\u05EA\u05D5\u05D1\u05EA IP \u05EA\u05E7\u05E4\u05D4.", "validators", "he");
  t.add("This value is not a valid language.", "\u05D4\u05E2\u05E8\u05DA \u05D0\u05D9\u05E0\u05D5 \u05E9\u05E4\u05D4 \u05D7\u05D5\u05E7\u05D9\u05EA.", "validators", "he");
  t.add("This value is not a valid locale.", "\u05D4\u05E2\u05E8\u05DA \u05D0\u05D9\u05E0\u05D5 \u05D0\u05D6\u05D5\u05E8 \u05EA\u05E7\u05E3.", "validators", "he");
  t.add("This value is not a valid country.", "\u05D4\u05E2\u05E8\u05DA \u05D0\u05D9\u05E0\u05D5 \u05D0\u05E8\u05E5 \u05D7\u05D5\u05E7\u05D9\u05EA.", "validators", "he");
  t.add("This value is already used.", "\u05D4\u05E2\u05E8\u05DA \u05DB\u05D1\u05E8 \u05D1\u05E9\u05D9\u05DE\u05D5\u05E9.", "validators", "he");
  t.add("The size of the image could not be detected.", "\u05DC\u05D0 \u05E0\u05D9\u05EA\u05DF \u05DC\u05E7\u05D1\u05D5\u05E2 \u05D0\u05EA \u05D2\u05D5\u05D3\u05DC \u05D4\u05EA\u05DE\u05D5\u05E0\u05D4.", "validators", "he");
  t.add("The image width is too big ({{ width }}px). Allowed maximum width is {{ max_width }}px.", "\u05E8\u05D5\u05D7\u05D1 \u05D4\u05EA\u05DE\u05D5\u05E0\u05D4 \u05D2\u05D3\u05D5\u05DC \u05DE\u05D3\u05D9 ({{ width }}px). \u05D4\u05E8\u05D5\u05D7\u05D1 \u05D4\u05DE\u05E7\u05E1\u05D9\u05DE\u05DC\u05D9 \u05D4\u05D5\u05D0 {{ max_width }}px.", "validators", "he");
  t.add("The image width is too small ({{ width }}px). Minimum width expected is {{ min_width }}px.", "\u05E8\u05D5\u05D7\u05D1 \u05D4\u05EA\u05DE\u05D5\u05E0\u05D4 \u05E7\u05D8\u05DF \u05DE\u05D3\u05D9 ({{ width }}px). \u05D4\u05E8\u05D5\u05D7\u05D1 \u05D4\u05DE\u05D9\u05E0\u05D9\u05DE\u05DC\u05D9 \u05D4\u05D5\u05D0 {{ min_width }}px.", "validators", "he");
  t.add("The image height is too big ({{ height }}px). Allowed maximum height is {{ max_height }}px.", "\u05D2\u05D5\u05D1\u05D4 \u05D4\u05EA\u05DE\u05D5\u05E0\u05D4 \u05D2\u05D3\u05D5\u05DC \u05DE\u05D3\u05D9 ({{ height }}px). \u05D4\u05D2\u05D5\u05D1\u05D4 \u05D4\u05DE\u05E7\u05E1\u05D9\u05DE\u05DC\u05D9 \u05D4\u05D5\u05D0 {{ max_height }}px.", "validators", "he");
  t.add("The image height is too small ({{ height }}px). Minimum height expected is {{ min_height }}px.", "\u05D2\u05D5\u05D1\u05D4 \u05D4\u05EA\u05DE\u05D5\u05E0\u05D4 \u05E7\u05D8\u05DF \u05DE\u05D3\u05D9 ({{ height }}px). \u05D4\u05D2\u05D5\u05D1\u05D4 \u05D4\u05DE\u05D9\u05E0\u05D9\u05DE\u05DC\u05D9 \u05D4\u05D5\u05D0 {{ min_height }}px.", "validators", "he");
  t.add("This value should be the user's current password.", "\u05D4\u05E2\u05E8\u05DA \u05E6\u05E8\u05D9\u05DA \u05DC\u05D4\u05D9\u05D5\u05EA \u05E1\u05D9\u05E1\u05DE\u05EA \u05D4\u05DE\u05E9\u05EA\u05DE\u05E9 \u05D4\u05E0\u05D5\u05DB\u05D7\u05D9.", "validators", "he");
  t.add("This value should have exactly {{ limit }} character.|This value should have exactly {{ limit }} characters.", "\u05D4\u05E2\u05E8\u05DA \u05E6\u05E8\u05D9\u05DA \u05DC\u05D4\u05D9\u05D5\u05EA \u05D1\u05D3\u05D9\u05D5\u05E7 {{ limit }} \u05EA\u05D5\u05D5\u05D9\u05DD.|\u05D4\u05E2\u05E8\u05DA \u05E6\u05E8\u05D9\u05DA \u05DC\u05D4\u05D9\u05D5\u05EA \u05D1\u05D3\u05D9\u05D5\u05E7 {{ limit }} \u05EA\u05D5\u05D5\u05D9\u05DD.", "validators", "he");
  t.add("The file was only partially uploaded.", "\u05D4\u05E7\u05D5\u05D1\u05E5 \u05D4\u05D5\u05E2\u05DC\u05D4 \u05D1\u05D0\u05D5\u05E4\u05DF \u05D7\u05DC\u05E7\u05D9.", "validators", "he");
  t.add("No file was uploaded.", "\u05D4\u05E7\u05D5\u05D1\u05E5 \u05DC\u05D0 \u05D4\u05D5\u05E2\u05DC\u05D4.", "validators", "he");
  t.add("No temporary folder was configured in php.ini.", "\u05DC\u05D0 \u05D4\u05D5\u05D2\u05D3\u05E8\u05D4 \u05EA\u05D9\u05E7\u05D9\u05D9\u05D4 \u05D6\u05DE\u05E0\u05D9\u05EA \u05D1-php.ini, \u05D0\u05D5 \u05E9\u05D4\u05EA\u05D9\u05E7\u05D9\u05D9\u05D4 \u05D4\u05DE\u05D5\u05D2\u05D3\u05E8\u05EA \u05D0\u05D9\u05E0\u05D4 \u05E7\u05D9\u05D9\u05DE\u05EA.", "validators", "he");
  t.add("Cannot write temporary file to disk.", "\u05DC\u05D0 \u05E0\u05D9\u05EA\u05DF \u05DC\u05DB\u05EA\u05D5\u05D1 \u05E7\u05D5\u05D1\u05E5 \u05D6\u05DE\u05E0\u05D9 \u05DC\u05D3\u05D9\u05E1\u05E7.", "validators", "he");
  t.add("A PHP extension caused the upload to fail.", "\u05E1\u05D9\u05D5\u05DE\u05EA PHP \u05D2\u05E8\u05DD \u05DC\u05D4\u05E2\u05DC\u05D0\u05D4 \u05DC\u05D4\u05D9\u05DB\u05E9\u05DC.", "validators", "he");
  t.add("This collection should contain {{ limit }} element or more.|This collection should contain {{ limit }} elements or more.", "\u05D4\u05D0\u05D5\u05E1\u05E3 \u05D0\u05DE\u05D5\u05E8 \u05DC\u05D4\u05DB\u05D9\u05DC {{ limit }} \u05D0\u05DC\u05DE\u05E0\u05D8\u05D9\u05DD \u05D0\u05D5 \u05D9\u05D5\u05EA\u05E8.|\u05D4\u05D0\u05D5\u05E1\u05E3 \u05D0\u05DE\u05D5\u05E8 \u05DC\u05D4\u05DB\u05D9\u05DC {{ limit }} \u05D0\u05DC\u05DE\u05E0\u05D8\u05D9\u05DD \u05D0\u05D5 \u05D9\u05D5\u05EA\u05E8.", "validators", "he");
  t.add("This collection should contain {{ limit }} element or less.|This collection should contain {{ limit }} elements or less.", "\u05D4\u05D0\u05D5\u05E1\u05E3 \u05D0\u05DE\u05D5\u05E8 \u05DC\u05D4\u05DB\u05D9\u05DC {{ limit }} \u05D0\u05DC\u05DE\u05E0\u05D8\u05D9\u05DD \u05D0\u05D5 \u05E4\u05D7\u05D5\u05EA.|\u05D4\u05D0\u05D5\u05E1\u05E3 \u05D0\u05DE\u05D5\u05E8 \u05DC\u05D4\u05DB\u05D9\u05DC {{ limit }} \u05D0\u05DC\u05DE\u05E0\u05D8\u05D9\u05DD \u05D0\u05D5 \u05E4\u05D7\u05D5\u05EA.", "validators", "he");
  t.add("This collection should contain exactly {{ limit }} element.|This collection should contain exactly {{ limit }} elements.", "\u05D4\u05D0\u05D5\u05E1\u05E3 \u05E6\u05E8\u05D9\u05DA \u05DC\u05D4\u05DB\u05D9\u05DC \u05D1\u05D3\u05D9\u05D5\u05E7 {{ limit }} \u05D0\u05DC\u05DE\u05E0\u05D8\u05D9\u05DD.|\u05D4\u05D0\u05D5\u05E1\u05E3 \u05E6\u05E8\u05D9\u05DA \u05DC\u05D4\u05DB\u05D9\u05DC \u05D1\u05D3\u05D9\u05D5\u05E7 {{ limit }} \u05D0\u05DC\u05DE\u05E0\u05D8\u05D9\u05DD.", "validators", "he");
  t.add("Invalid card number.", "\u05DE\u05E1\u05E4\u05E8 \u05D4\u05DB\u05E8\u05D8\u05D9\u05E1 \u05D0\u05D9\u05E0\u05D5 \u05D7\u05D5\u05E7\u05D9.", "validators", "he");
  t.add("Unsupported card type or invalid card number.", "\u05E1\u05D5\u05D2 \u05D4\u05DB\u05E8\u05D8\u05D9\u05E1 \u05D0\u05D9\u05E0\u05D5 \u05E0\u05EA\u05DE\u05DA \u05D0\u05D5 \u05DC\u05D0 \u05D7\u05D5\u05E7\u05D9.", "validators", "he");
  t.add("This is not a valid International Bank Account Number (IBAN).", "\u05E2\u05E8\u05DA \u05D6\u05D4 \u05D0\u05D9\u05E0\u05D5 \u05DE\u05E1\u05E4\u05E8 \u05D7\u05E9\u05D1\u05D5\u05DF \u05D1\u05E0\u05E7 \u05D1\u05D9\u05E0\u05DC\u05D0\u05D5\u05DE\u05D9 (IBAN) \u05EA\u05E7\u05E3.", "validators", "he");
  t.add("This value is not a valid ISBN-10.", "\u05D4\u05E2\u05E8\u05DA \u05D0\u05D9\u05E0\u05D5 \u05E2\u05E8\u05DA ISBN-10 \u05D7\u05D5\u05E7\u05D9.", "validators", "he");
  t.add("This value is not a valid ISBN-13.", "\u05D4\u05E2\u05E8\u05DA \u05D0\u05D9\u05E0\u05D5 \u05E2\u05E8\u05DA ISBN-13 \u05D7\u05D5\u05E7\u05D9.", "validators", "he");
  t.add("This value is neither a valid ISBN-10 nor a valid ISBN-13.", "\u05D4\u05E2\u05E8\u05DA \u05D0\u05D9\u05E0\u05D5 \u05E2\u05E8\u05DA ISBN-10 \u05D7\u05D5\u05E7\u05D9 \u05D0\u05D5 \u05E2\u05E8\u05DA ISBN-13 \u05D7\u05D5\u05E7\u05D9.", "validators", "he");
  t.add("This value is not a valid ISSN.", "\u05D4\u05E2\u05E8\u05DA \u05D0\u05D9\u05E0\u05D5 \u05E2\u05E8\u05DA ISSN \u05D7\u05D5\u05E7\u05D9.", "validators", "he");
  t.add("This value is not a valid currency.", "\u05D4\u05E2\u05E8\u05DA \u05D0\u05D9\u05E0\u05D5 \u05E2\u05E8\u05DA \u05DE\u05D8\u05D1\u05E2 \u05D7\u05D5\u05E7\u05D9.", "validators", "he");
  t.add("This value should be equal to {{ compared_value }}.", "\u05D4\u05E2\u05E8\u05DA \u05D7\u05D9\u05D9\u05D1 \u05DC\u05D4\u05D9\u05D5\u05EA \u05E9\u05D5\u05D5\u05D4 \u05DC {{ compared_value }}.", "validators", "he");
  t.add("This value should be greater than {{ compared_value }}.", "\u05D4\u05E2\u05E8\u05DA \u05D7\u05D9\u05D9\u05D1 \u05DC\u05D4\u05D9\u05D5\u05EA \u05D2\u05D3\u05D5\u05DC \u05DE {{ compared_value }}.", "validators", "he");
  t.add("This value should be greater than or equal to {{ compared_value }}.", "\u05D4\u05E2\u05E8\u05DA \u05D7\u05D9\u05D9\u05D1 \u05DC\u05D4\u05D9\u05D5\u05EA \u05D2\u05D3\u05D5\u05DC \u05D0\u05D5 \u05E9\u05D5\u05D5\u05D4 \u05DC {{ compared_value }}.", "validators", "he");
  t.add("This value should be identical to {{ compared_value_type }} {{ compared_value }}.", "\u05D4\u05E2\u05E8\u05DA \u05D7\u05D9\u05D9\u05D1 \u05DC\u05D4\u05D9\u05D5\u05EA \u05D6\u05D4\u05D4 \u05DC {{ compared_value_type }} {{ compared_value }}.", "validators", "he");
  t.add("This value should be less than {{ compared_value }}.", "\u05D4\u05E2\u05E8\u05DA \u05D7\u05D9\u05D9\u05D1 \u05DC\u05D4\u05D9\u05D5\u05EA \u05E7\u05D8\u05DF \u05DE {{ compared_value }}.", "validators", "he");
  t.add("This value should be less than or equal to {{ compared_value }}.", "\u05D4\u05E2\u05E8\u05DA \u05D7\u05D9\u05D9\u05D1 \u05DC\u05D4\u05D9\u05D5\u05EA \u05E7\u05D8\u05DF \u05D0\u05D5 \u05E9\u05D5\u05D5\u05D4 \u05DC {{ compared_value }}.", "validators", "he");
  t.add("This value should not be equal to {{ compared_value }}.", "\u05D4\u05E2\u05E8\u05DA \u05D7\u05D9\u05D9\u05D1 \u05DC\u05D4\u05D9\u05D5\u05EA \u05DC\u05D0 \u05E9\u05D5\u05D5\u05D4 \u05DC {{ compared_value }}.", "validators", "he");
  t.add("This value should not be identical to {{ compared_value_type }} {{ compared_value }}.", "\u05D4\u05E2\u05E8\u05DA \u05D7\u05D9\u05D9\u05D1 \u05DC\u05D4\u05D9\u05D5\u05EA \u05DC\u05D0 \u05D6\u05D4\u05D4 \u05DC {{ compared_value_type }} {{ compared_value }}.", "validators", "he");
  t.add("The image ratio is too big ({{ ratio }}). Allowed maximum ratio is {{ max_ratio }}.", "\u05D4\u05D9\u05D7\u05E1 \u05E9\u05DC \u05D4\u05EA\u05DE\u05D5\u05E0\u05D4 \u05D4\u05D5\u05D0 \u05D2\u05D3\u05D5\u05DC \u05DE\u05D3\u05D9 ({{ ratio }}). \u05D4\u05D9\u05D7\u05E1 \u05D4\u05DE\u05E7\u05E1\u05D9\u05DE\u05DC\u05D9 \u05D4\u05D0\u05E4\u05E9\u05E8\u05D9 \u05D4\u05D5\u05D0 {{ max_ratio }}.", "validators", "he");
  t.add("The image ratio is too small ({{ ratio }}). Minimum ratio expected is {{ min_ratio }}.", "\u05D4\u05D9\u05D7\u05E1 \u05E9\u05DC \u05D4\u05EA\u05DE\u05D5\u05E0\u05D4 \u05D4\u05D5\u05D0 \u05E7\u05D8\u05DF \u05DE\u05D3\u05D9 ({{ ratio }}). \u05D4\u05D9\u05D7\u05E1 \u05D4\u05DE\u05D9\u05E0\u05D9\u05DE\u05DC\u05D9 \u05D4\u05D0\u05E4\u05E9\u05E8\u05D9 \u05D4\u05D5\u05D0 {{ min_ratio }}.", "validators", "he");
  t.add("The image is square ({{ width }}x{{ height }}px). Square images are not allowed.", "\u05D4\u05EA\u05DE\u05D5\u05E0\u05D4 \u05DE\u05E8\u05D5\u05D1\u05E2\u05EA ({{ width }}x{{ height }}px). \u05D0\u05E1\u05D5\u05E8\u05D5\u05EA \u05EA\u05DE\u05D5\u05E0\u05D5\u05EA \u05DE\u05E8\u05D5\u05D1\u05E2\u05D5\u05EA.", "validators", "he");
  t.add("The image is landscape oriented ({{ width }}x{{ height }}px). Landscape oriented images are not allowed.", "\u05D4\u05EA\u05DE\u05D5\u05E0\u05D4 \u05D4\u05D9\u05D0 \u05DC\u05E8\u05D5\u05D7\u05D1 ({{ width }}x{{ height }}px). \u05D0\u05E1\u05D5\u05E8\u05D5\u05EA \u05EA\u05DE\u05D5\u05E0\u05D5\u05EA \u05DC\u05E8\u05D5\u05D7\u05D1.", "validators", "he");
  t.add("The image is portrait oriented ({{ width }}x{{ height }}px). Portrait oriented images are not allowed.", "\u05D4\u05EA\u05DE\u05D5\u05E0\u05D4 \u05D4\u05D9\u05D0 \u05DC\u05D0\u05D5\u05E8\u05DA ({{ width }}x{{ height }}px). \u05D0\u05E1\u05D5\u05E8\u05D5\u05EA \u05EA\u05DE\u05D5\u05E0\u05D5\u05EA \u05DC\u05D0\u05D5\u05E8\u05DA.", "validators", "he");
  t.add("An empty file is not allowed.", "\u05D0\u05E1\u05D5\u05E8 \u05E7\u05D5\u05D1\u05E5 \u05E8\u05D9\u05E7.", "validators", "he");
  t.add("The host could not be resolved.", "\u05DC\u05D0 \u05D4\u05D9\u05D9\u05EA\u05D4 \u05D0\u05E4\u05E9\u05E8\u05D5\u05EA \u05DC\u05D6\u05D4\u05D5\u05EA \u05D0\u05EA \u05D4\u05DE\u05D0\u05E8\u05D7.", "validators", "he");
  t.add("This value does not match the expected {{ charset }} charset.", "\u05D4\u05E2\u05E8\u05DA \u05D0\u05D9\u05E0\u05D5 \u05EA\u05D5\u05D0\u05DD \u05DC\u05DE\u05E2\u05E8\u05DA \u05D4\u05EA\u05D5\u05D5\u05D9\u05DD {{ charset }} \u05D4\u05E6\u05E4\u05D5\u05D9.", "validators", "he");
  t.add("This is not a valid Business Identifier Code (BIC).", "\u05E2\u05E8\u05DA \u05D6\u05D4 \u05D0\u05D9\u05E0\u05D5 \u05E7\u05D5\u05D3 \u05DE\u05D6\u05D4\u05D4 \u05E2\u05E1\u05E7\u05D9 (BIC) \u05EA\u05E7\u05E3.", "validators", "he");
  t.add("Error", "\u05E9\u05D2\u05D9\u05D0\u05D4", "validators", "he");
  t.add("This is not a valid UUID.", "\u05E2\u05E8\u05DA \u05D6\u05D4 \u05D0\u05D9\u05E0\u05D5 UUID \u05EA\u05E7\u05E3.", "validators", "he");
  t.add("This value should be a multiple of {{ compared_value }}.", "\u05D4\u05E2\u05E8\u05DA \u05D7\u05D9\u05D9\u05D1 \u05DC\u05D4\u05D9\u05D5\u05EA \u05DB\u05E4\u05D5\u05DC\u05D4 \u05E9\u05DC {{ compared_value }}.", "validators", "he");
  t.add("This Business Identifier Code (BIC) is not associated with IBAN {{ iban }}.", "\u05D4\u05E7\u05D5\u05D3 \u05D6\u05D9\u05D4\u05D5\u05D9 \u05E2\u05E1\u05E7\u05D9 (BIC) \u05D0\u05D9\u05E0\u05D5 \u05DE\u05E9\u05D5\u05D9\u05D9\u05DA \u05DC IBAN {{ iban }}.", "validators", "he");
  t.add("This value should be valid JSON.", "\u05D4\u05E2\u05E8\u05DA \u05D0\u05D9\u05E0\u05D5 \u05E2\u05E8\u05DA JSON \u05EA\u05E7\u05D9\u05DF.", "validators", "he");
  t.add("This collection should contain only unique elements.", "\u05D4\u05D0\u05D5\u05E1\u05E3 \u05D7\u05D9\u05D9\u05D1 \u05DC\u05D4\u05DB\u05D9\u05DC \u05E8\u05E7 \u05D0\u05DC\u05DE\u05E0\u05D8\u05D9\u05DD \u05D9\u05D9\u05D7\u05D5\u05D3\u05D9\u05D9\u05DD.", "validators", "he");
  t.add("This value should be positive.", "\u05D4\u05E2\u05E8\u05DA \u05D7\u05D9\u05D9\u05D1 \u05DC\u05D4\u05D9\u05D5\u05EA \u05D7\u05D9\u05D5\u05D1\u05D9.", "validators", "he");
  t.add("This value should be either positive or zero.", "\u05D4\u05E2\u05E8\u05DA \u05D7\u05D9\u05D9\u05D1 \u05DC\u05D4\u05D9\u05D5\u05EA \u05D7\u05D9\u05D5\u05D1\u05D9 \u05D0\u05D5 \u05D0\u05E4\u05E1.", "validators", "he");
  t.add("This value should be negative.", "\u05D4\u05E2\u05E8\u05DA \u05D7\u05D9\u05D9\u05D1 \u05DC\u05D4\u05D9\u05D5\u05EA \u05E9\u05DC\u05D9\u05DC\u05D9.", "validators", "he");
  t.add("This value should be either negative or zero.", "\u05D4\u05E2\u05E8\u05DA \u05D7\u05D9\u05D9\u05D1 \u05DC\u05D4\u05D9\u05D5\u05EA \u05E9\u05DC\u05D9\u05DC\u05D9 \u05D0\u05D5 \u05D0\u05E4\u05E1.", "validators", "he");
  t.add("This value is not a valid timezone.", "\u05D4\u05E2\u05E8\u05DA \u05D0\u05D9\u05E0\u05D5 \u05D0\u05D6\u05D5\u05E8 \u05D6\u05DE\u05DF \u05EA\u05E7\u05D9\u05DF.", "validators", "he");
  t.add("This password has been leaked in a data breach, it must not be used. Please use another password.", "\u05E1\u05D9\u05E1\u05DE\u05D0 \u05D6\u05D5 \u05D4\u05D5\u05D3\u05DC\u05E4\u05D4 \u05D1\u05D4\u05D3\u05DC\u05E4\u05EA \u05DE\u05D9\u05D3\u05E2, \u05D0\u05E1\u05D5\u05E8 \u05DC\u05D4\u05E9\u05EA\u05DE\u05E9 \u05D1\u05D4. \u05D0\u05E0\u05D0 \u05D4\u05E9\u05EA\u05DE\u05E9 \u05D1\u05E1\u05D9\u05E1\u05DE\u05D4 \u05D0\u05D7\u05E8\u05EA.", "validators", "he");
  t.add("This value should be between {{ min }} and {{ max }}.", "\u05D4\u05E2\u05E8\u05DA \u05D7\u05D9\u05D9\u05D1 \u05DC\u05D4\u05D9\u05D5\u05EA \u05D1\u05D9\u05DF {{ min }} \u05D5- {{ max }}.", "validators", "he");
  t.add("This value is not a valid hostname.", "\u05E2\u05E8\u05DA \u05D6\u05D4 \u05D0\u05D9\u05E0\u05D5 \u05E9\u05DD \u05DE\u05D0\u05E8\u05D7 \u05D7\u05D5\u05E7\u05D9.", "validators", "he");
  t.add("The number of elements in this collection should be a multiple of {{ compared_value }}.", "\u05DE\u05E1\u05E4\u05E8 \u05D4\u05D0\u05DC\u05DE\u05E0\u05D8\u05D9\u05DD \u05D1\u05D0\u05D5\u05E1\u05E3 \u05D6\u05D4 \u05E6\u05E8\u05D9\u05DA \u05DC\u05D4\u05D9\u05D5\u05EA \u05DE\u05DB\u05E4\u05D9\u05DC \u05E9\u05DC {{ compared_value }}.", "validators", "he");
  t.add("This value should satisfy at least one of the following constraints:", "\u05E2\u05E8\u05DA \u05D6\u05D4 \u05D0\u05DE\u05D5\u05E8 \u05DC\u05E2\u05DE\u05D5\u05D3 \u05DC\u05E4\u05D7\u05D5\u05EA \u05D1\u05D0\u05D7\u05D3 \u05D4\u05EA\u05E0\u05D0\u05D9\u05DD \u05D4\u05D1\u05D0\u05D9\u05DD:", "validators", "he");
  t.add("Each element of this collection should satisfy its own set of constraints.", "\u05DB\u05DC \u05D0\u05DC\u05DE\u05E0\u05D8 \u05D1\u05D0\u05D5\u05E1\u05E3 \u05D6\u05D4 \u05D0\u05DE\u05D5\u05E8 \u05DC\u05E2\u05DE\u05D5\u05D3 \u05D1\u05E7\u05D1\u05D5\u05E6\u05EA \u05D4\u05EA\u05E0\u05D0\u05D9\u05DD \u05E9\u05DC\u05D5.", "validators", "he");
  t.add("This value is not a valid International Securities Identification Number (ISIN).", "\u05E2\u05E8\u05DA \u05D6\u05D4 \u05D0\u05D9\u05E0\u05D5 \u05DE\u05E1\u05E4\u05E8 \u05D6\u05D9\u05D4\u05D5\u05D9 \u05E0\u05D9\u05D9\u05E8\u05D5\u05EA \u05E2\u05E8\u05DA \u05D1\u05D9\u05E0\u05DC\u05D0\u05D5\u05DE\u05D9 \u05EA\u05E7\u05E3 (ISIN).", "validators", "he");
  t.add("This value should be a valid expression.", "\u05E2\u05E8\u05DA \u05D6\u05D4 \u05D7\u05D9\u05D9\u05D1 \u05DC\u05D4\u05D9\u05D5\u05EA \u05D1\u05D9\u05D8\u05D5\u05D9 \u05D7\u05D5\u05E7\u05D9.", "validators", "he");
  t.add("This value is not a valid CSS color.", "\u05E2\u05E8\u05DA \u05D6\u05D4 \u05D0\u05D9\u05E0\u05D5 \u05E6\u05D1\u05E2 CSS \u05D7\u05D5\u05E7\u05D9.", "validators", "he");
  t.add("This value is not a valid CIDR notation.", "\u05E2\u05E8\u05DA \u05D6\u05D4 \u05D0\u05D9\u05E0\u05D5 \u05E1\u05D9\u05DE\u05D5\u05DF CIDR \u05D7\u05D5\u05E7\u05D9.", "validators", "he");
  t.add("The value of the netmask should be between {{ min }} and {{ max }}.", "\u05D4\u05E2\u05E8\u05DA \u05E9\u05DC \u05DE\u05E1\u05DB\u05EA \u05D4\u05E8\u05E9\u05EA \u05D7\u05D9\u05D9\u05D1 \u05DC\u05D4\u05D9\u05D5\u05EA \u05D1\u05D9\u05DF {{ min }} \u05D5 {{ max }}.", "validators", "he");
  t.add("The filename is too long. It should have {{ filename_max_length }} character or less.|The filename is too long. It should have {{ filename_max_length }} characters or less.", "\u05E9\u05DD \u05D4\u05E7\u05D5\u05D1\u05E5 \u05D0\u05E8\u05D5\u05DA \u05DE\u05D3\u05D9. \u05E2\u05DC\u05D9\u05D5 \u05DC\u05D4\u05DB\u05D9\u05DC {{ filename_max_length }} \u05EA\u05D5\u05D5\u05D9\u05DD \u05D0\u05D5 \u05E4\u05D7\u05D5\u05EA.", "validators", "he");
  t.add("The password strength is too low. Please use a stronger password.", "\u05D7\u05D5\u05D6\u05E7 \u05D4\u05E1\u05D9\u05E1\u05DE\u05D4 \u05E0\u05DE\u05D5\u05DA \u05DE\u05D3\u05D9. \u05D0\u05E0\u05D0 \u05D4\u05E9\u05EA\u05DE\u05E9 \u05D1\u05E1\u05D9\u05E1\u05DE\u05D4 \u05D7\u05D6\u05E7\u05D4 \u05D9\u05D5\u05EA\u05E8.", "validators", "he");
  t.add("This value contains characters that are not allowed by the current restriction-level.", "\u05D4\u05E2\u05E8\u05DA \u05DB\u05D5\u05DC\u05DC \u05EA\u05D5\u05D5\u05D9\u05DD \u05E9\u05D0\u05D9\u05E0\u05DD \u05DE\u05D5\u05EA\u05E8\u05D9\u05DD \u05E2\u05DC \u05E4\u05D9 \u05E8\u05DE\u05EA \u05D4\u05D4\u05D2\u05D1\u05DC\u05D4 \u05D4\u05E0\u05D5\u05DB\u05D7\u05D9\u05EA.", "validators", "he");
  t.add("Using invisible characters is not allowed.", "\u05D0\u05E1\u05D5\u05E8 \u05DC\u05D4\u05E9\u05EA\u05DE\u05E9 \u05D1\u05EA\u05D5\u05D5\u05D9\u05DD \u05D1\u05DC\u05EA\u05D9 \u05E0\u05E8\u05D0\u05D9\u05DD.", "validators", "he");
  t.add("Mixing numbers from different scripts is not allowed.", "\u05D0\u05E1\u05D5\u05E8 \u05DC\u05E2\u05E8\u05D1\u05D1 \u05DE\u05E1\u05E4\u05E8\u05D9\u05DD \u05DE\u05EA\u05E1\u05E8\u05D9\u05D8\u05D9\u05DD \u05E9\u05D5\u05E0\u05D9\u05DD.", "validators", "he");
  t.add("Using hidden overlay characters is not allowed.", "\u05D0\u05E1\u05D5\u05E8 \u05DC\u05D4\u05E9\u05EA\u05DE\u05E9 \u05D1\u05EA\u05D5\u05D5\u05D9\u05DD \u05DE\u05D5\u05E1\u05EA\u05E8\u05D9\u05DD \u05E9\u05DC \u05D7\u05E4\u05D9\u05E4\u05D4.", "validators", "he");
  t.add("The extension of the file is invalid ({{ extension }}). Allowed extensions are {{ extensions }}.", "\u05E1\u05D9\u05D5\u05DE\u05EA \u05D4\u05E7\u05D5\u05D1\u05E5 \u05D0\u05D9\u05E0\u05D4 \u05EA\u05E7\u05D9\u05E0\u05D4 ({{ extension }}). \u05D4\u05E1\u05D9\u05D5\u05DE\u05D5\u05EA \u05D4\u05DE\u05D5\u05EA\u05E8\u05D5\u05EA \u05D4\u05DF {{ extensions }}.", "validators", "he");
  t.add("The detected character encoding is invalid ({{ detected }}). Allowed encodings are {{ encodings }}.", "\u05E7\u05D9\u05D3\u05D5\u05D3 \u05D4\u05EA\u05D5\u05D5\u05D9\u05DD \u05E9\u05D6\u05D5\u05D4\u05D4 \u05D0\u05D9\u05E0\u05D5 \u05D7\u05D5\u05E7\u05D9 ({{ detected }}). \u05D4\u05E7\u05D9\u05D3\u05D5\u05D3\u05D9\u05DD \u05D4\u05DE\u05D5\u05EA\u05E8\u05D9\u05DD \u05D4\u05DD {{ encodings }}.", "validators", "he");
  t.add("This value is not a valid MAC address.", "\u05E2\u05E8\u05DA \u05D6\u05D4 \u05D0\u05D9\u05E0\u05D5 \u05DB\u05EA\u05D5\u05D1\u05EA MAC \u05EA\u05E7\u05E4\u05D4.", "validators", "he");
  t.add("This URL is missing a top-level domain.", "\u05DC\u05DB\u05EA\u05D5\u05D1\u05EA URL \u05D6\u05D5 \u05D7\u05E1\u05E8 \u05D3\u05D5\u05DE\u05D9\u05D9\u05DF \u05E8\u05DE\u05D4 \u05E2\u05DC\u05D9\u05D5\u05E0\u05D4.", "validators", "he");
  t.add("This value is too short. It should contain at least one word.|This value is too short. It should contain at least {{ min }} words.", "This value is too short. It should contain at least one word.|This value is too short. It should contain at least {{ min }} words.", "validators", "he");
  t.add("This value is too long. It should contain one word.|This value is too long. It should contain {{ max }} words or less.", "This value is too long. It should contain one word.|This value is too long. It should contain {{ max }} words or less.", "validators", "he");
  t.add("This value does not represent a valid week in the ISO 8601 format.", "This value does not represent a valid week in the ISO 8601 format.", "validators", "he");
  t.add("This value is not a valid week.", "This value is not a valid week.", "validators", "he");
  t.add("This value should not be before week \"{{ min }}\".", "This value should not be before week \"{{ min }}\".", "validators", "he");
  t.add("This value should not be after week \"{{ max }}\".", "This value should not be after week \"{{ max }}\".", "validators", "he");
  t.add("This form should not contain extra fields.", "\u05D4\u05D8\u05D5\u05E4\u05E1 \u05DC\u05D0 \u05E6\u05E8\u05D9\u05DA \u05DC\u05D4\u05DB\u05D9\u05DC \u05E9\u05D3\u05D5\u05EA \u05E0\u05D5\u05E1\u05E4\u05D9\u05DD.", "validators", "he");
