  t.add("This value is not a valid currency.", "\u0531\u0580\u056A\u0565\u0584\u0568 \u057E\u0561\u057E\u0565\u0580 \u057F\u0561\u0580\u0561\u0564\u0580\u0561\u0574 \u0579\u0567\u0589", "validators", "hy");
