  t.add("Error", "\u054D\u056D\u0561\u056C", "validators", "hy");
  t.add("This is not a valid UUID.", "\u0531\u0575\u057D \u0561\u0580\u056A\u0565\u0584\u0568 \u057E\u0561\u057E\u0565\u0580 UUID \u0579\u0567\u0589", "validators", "hy");
  t.add("This value should be a multiple of {{ compared_value }}.", "\u0531\u0575\u057D \u0561\u0580\u056A\u0565\u0584\u0568 \u057A\u0565\u057F\u0584 \u0567 \u056C\u056B\u0576\u056B \u0562\u0561\u0566\u0574\u0561\u056F\u056B {{ compared_value }}\u0589", "validators", "hy");
  t.add("This Business Identifier Code (BIC) is not associated with IBAN {{ iban }}.", "\u0532\u056B\u0566\u0576\u0565\u057D\u056B \u0576\u0578\u0582\u0575\u0576\u0561\u056F\u0561\u0576\u0561\u0581\u0574\u0561\u0576 \u056F\u0578\u0564\u0568 (BIC) \u056F\u0561\u057A\u057E\u0561\u056E \u0579\u0567 IBAN- \u056B \u0570\u0565\u057F {{ iban }}\u0589", "validators", "hy");
  t.add("This value should be valid JSON.", "\u0531\u0575\u057D \u0561\u0580\u056A\u0565\u0584\u0568 \u057A\u0565\u057F\u0584 \u0567 \u056C\u056B\u0576\u056B \u057E\u0561\u057E\u0565\u0580 JSON\u0589", "validators", "hy");
  t.add("This collection should contain only unique elements.", "\u0531\u0575\u057D \u0570\u0561\u0574\u0561\u056D\u0578\u0582\u0574\u0562\u0568 \u057A\u0565\u057F\u0584 \u0567 \u057A\u0561\u0580\u0578\u0582\u0576\u0561\u056F\u056B \u0574\u056B\u0561\u0575\u0576 \u0565\u0566\u0561\u056F\u056B \u057F\u0561\u0580\u0580\u0565\u0580\u0589", "validators", "hy");
  t.add("This value should be positive.", "\u0531\u0575\u057D \u0561\u0580\u056A\u0565\u0584\u0568 \u057A\u0565\u057F\u0584 \u0567 \u056C\u056B\u0576\u056B \u0564\u0580\u0561\u056F\u0561\u0576\u0589", "validators", "hy");
  t.add("This value should be either positive or zero.", "\u0531\u0575\u057D \u0561\u0580\u056A\u0565\u0584\u0568 \u057A\u0565\u057F\u0584 \u0567 \u056C\u056B\u0576\u056B \u0564\u0580\u0561\u056F\u0561\u0576 \u056F\u0561\u0574 \u0566\u0580\u0578\u0575\u0561\u056F\u0561\u0576\u0589", "validators", "hy");
  t.add("This value should be negative.", "\u0531\u0575\u057D \u0561\u0580\u056A\u0565\u0584\u0568 \u057A\u0565\u057F\u0584 \u0567 \u056C\u056B\u0576\u056B \u0562\u0561\u0581\u0561\u057D\u0561\u056F\u0561\u0576\u0589", "validators", "hy");
  t.add("This value should be either negative or zero.", "\u0531\u0575\u057D \u0561\u0580\u056A\u0565\u0584\u0568 \u057A\u0565\u057F\u0584 \u0567 \u056C\u056B\u0576\u056B \u0562\u0561\u0581\u0561\u057D\u0561\u056F\u0561\u0576 \u056F\u0561\u0574 \u0566\u0580\u0578\u0575\u0561\u056F\u0561\u0576\u0589", "validators", "hy");
  t.add("This value is not a valid timezone.", "\u0531\u0575\u057D \u0561\u0580\u056A\u0565\u0584\u0568 \u057E\u0561\u057E\u0565\u0580 \u056A\u0561\u0574\u0561\u0575\u056B\u0576 \u0563\u0578\u057F\u056B \u0579\u0567\u0589", "validators", "hy");
  t.add("This password has been leaked in a data breach, it must not be used. Please use another password.", "\u0533\u0561\u0572\u057F\u0576\u0561\u0562\u0561\u057C\u0568 \u0563\u057F\u0576\u057E\u0565\u056C \u0567 \u057F\u057E\u0575\u0561\u056C\u0576\u0565\u0580\u056B \u0561\u0580\u057F\u0561\u0570\u0578\u057D\u0584\u0578\u0582\u0574. \u0561\u0575\u0576 \u0579\u057A\u0565\u057F\u0584 \u0567 \u0585\u0563\u057F\u0561\u0563\u0578\u0580\u056E\u057E\u056B: \u053D\u0576\u0564\u0580\u0578\u0582\u0574 \u0565\u0576\u0584 \u0585\u0563\u057F\u0561\u0563\u0578\u0580\u056E\u0565\u056C \u0574\u0565\u056F \u0561\u0575\u056C \u0563\u0561\u0572\u057F\u0576\u0561\u0562\u0561\u057C\u0589", "validators", "hy");
  t.add("This value should be between {{ min }} and {{ max }}.", "\u0531\u0575\u057D \u0561\u0580\u056A\u0565\u0584\u0568 \u057A\u0565\u057F\u0584 \u0567 \u056C\u056B\u0576\u056B  {{ min }}-\u056B \u0587 {{ max }}-\u056B \u0574\u056B\u057B\u0587\u0589", "validators", "hy");
  t.add("This value is not a valid hostname.", "\u0531\u0575\u057D \u0570\u0578\u057D\u057F\u056B \u0561\u0576\u0578\u0582\u0576\u0568 \u057E\u0561\u057E\u0565\u0580 \u0579\u0567\u0589", "validators", "hy");
  t.add("The number of elements in this collection should be a multiple of {{ compared_value }}.", "\u0531\u0575\u057D \u0570\u0561\u0574\u0561\u056D\u0574\u0562\u056B \u057F\u0561\u0580\u0580\u0565\u0580\u056B \u0584\u0561\u0576\u0561\u056F\u0568 \u057A\u0565\u057F\u0584 \u0567 \u0570\u0561\u057E\u0561\u057D\u0561\u0580 \u056C\u056B\u0576\u056B {{ compared_value }}-\u056B \u0562\u0561\u0566\u0574\u0561\u057A\u0561\u057F\u056B\u056F\u0576\u0565\u0580\u056B\u0576\u0589", "validators", "hy");
  t.add("This value should satisfy at least one of the following constraints:", "\u0531\u0575\u057D \u0561\u0580\u056A\u0565\u0584\u0568 \u057A\u0565\u057F\u0584 \u0567 \u0562\u0561\u057E\u0561\u0580\u0561\u0580\u056B \u0570\u0565\u057F\u0587\u0575\u0561\u056C \u057D\u0561\u0570\u0574\u0561\u0576\u0561\u0583\u0561\u056F\u0578\u0582\u0574\u0576\u0565\u0580\u056B\u0581 \u0561\u057C\u0576\u057E\u0561\u0566\u0576 \u0574\u0565\u056F\u0568\u0589", "validators", "hy");
  t.add("Each element of this collection should satisfy its own set of constraints.", "\u0531\u0575\u057D \u0570\u0561\u0574\u0561\u056D\u0574\u0562\u056B \u0575\u0578\u0582\u0580\u0561\u0584\u0561\u0576\u0579\u0575\u0578\u0582\u0580 \u057F\u0561\u0580\u0580 \u057A\u0565\u057F\u0584 \u0567 \u0562\u0561\u057E\u0561\u0580\u0561\u0580\u056B \u056B\u0580 \u057D\u0565\u0583\u0561\u056F\u0561\u0576 \u057D\u0561\u0570\u0574\u0561\u0576\u0561\u0583\u0561\u056F\u0578\u0582\u0574\u0576\u0565\u0580\u0568\u0589", "validators", "hy");
  t.add("This value is not a valid International Securities Identification Number (ISIN).", "\u0531\u0575\u057D \u0561\u0580\u056A\u0565\u0584\u0568 \u0561\u0580\u056A\u0565\u0569\u0572\u0569\u0565\u0580\u056B \u0576\u0578\u0582\u0575\u0576\u0561\u056F\u0561\u0576\u0561\u0581\u0574\u0561\u0576 \u0574\u056B\u057B\u0561\u0566\u0563\u0561\u0575\u056B\u0576 \u0570\u0561\u0574\u0561\u0580\u0568 \u057E\u0561\u057E\u0565\u0580 \u0579\u0567(ISIN)\u0589", "validators", "hy");
  t.add("This value should be a valid expression.", "\u0531\u0575\u057D \u0561\u0580\u056A\u0565\u0584\u0568 \u057A\u0565\u057F\u0584 \u0567 \u056C\u056B\u0576\u056B \u057E\u0561\u057E\u0565\u0580 \u0561\u0580\u057F\u0561\u0570\u0561\u0575\u057F\u0578\u0582\u0569\u0575\u0578\u0582\u0576:", "validators", "hy");
  t.add("This value is not a valid CSS color.", "\u0531\u0575\u057D \u0561\u0580\u056A\u0565\u0584\u0568 \u057E\u0561\u057E\u0565\u0580 CSS \u0563\u0578\u0582\u0575\u0576 \u0579\u0567\u0589", "validators", "hy");
  t.add("This value is not a valid CIDR notation.", "\u0531\u0575\u057D \u0561\u0580\u056A\u0565\u0584\u0568 \u057E\u0561\u057E\u0565\u0580 CIDR \u0576\u0577\u0578\u0582\u0574 \u0579\u0567\u0589", "validators", "hy");
  t.add("The value of the netmask should be between {{ min }} and {{ max }}.", "\u0551\u0561\u0576\u0581\u0561\u0575\u056B\u0576 \u0564\u056B\u0574\u0561\u056F\u056B \u0561\u0580\u056A\u0565\u0584\u0568 \u057A\u0565\u057F\u0584 \u0567 \u056C\u056B\u0576\u056B {{ min }}-\u056B \u0587 {{ max }}-\u056B \u0574\u056B\u057B\u0587\u0589", "validators", "hy");
  t.add("The filename is too long. It should have {{ filename_max_length }} character or less.|The filename is too long. It should have {{ filename_max_length }} characters or less.", "\u0556\u0561\u0575\u056C\u056B \u0561\u0576\u0578\u0582\u0576\u0568 \u0577\u0561\u057F \u0565\u0580\u056F\u0561\u0580 \u0567\u0589 \u0531\u0575\u0576 \u057A\u0565\u057F\u0584 \u0567 \u0578\u0582\u0576\u0565\u0576\u0561 {{ filename_max_length }} \u0576\u056B\u0577 \u056F\u0561\u0574 \u057A\u0561\u056F\u0561\u057D\u0589", "validators", "hy");
  t.add("The password strength is too low. Please use a stronger password.", "\u0533\u0561\u0572\u057F\u0576\u0561\u0562\u0561\u057C\u056B \u0561\u0576\u057E\u057F\u0561\u0576\u0563\u0578\u0582\u0569\u0575\u0578\u0582\u0576\u0568 \u0577\u0561\u057F \u0581\u0561\u056E\u0580 \u0567\u0589 \u053D\u0576\u0564\u0580\u0578\u0582\u0574 \u0565\u0576\u0584 \u0563\u0578\u0580\u056E\u0561\u056E\u0565\u056C \u0561\u057E\u0565\u056C\u056B \u0561\u0574\u0580\u0561\u0563\u0578\u0582\u0575\u0576 \u0563\u0561\u0572\u057F\u0576\u0561\u0562\u0561\u057C\u0589", "validators", "hy");
  t.add("This value contains characters that are not allowed by the current restriction-level.", "\u0531\u0575\u057D \u0561\u0580\u056A\u0565\u0584\u0568 \u057A\u0561\u0580\u0578\u0582\u0576\u0561\u056F\u0578\u0582\u0574 \u0567 \u0561\u0575\u0576 \u0576\u056B\u0577\u0565\u0580\u0568, \u0578\u0580\u0578\u0576\u0584 \u0579\u0565\u0576 \u0569\u0578\u0582\u0575\u056C\u0561\u057F\u0580\u057E\u0578\u0582\u0574 \u0568\u057D\u057F \u0568\u0576\u0569\u0561\u0581\u056B\u056F \u057D\u0561\u0570\u0574\u0561\u0576\u0578\u0582\u0574\u0576\u0565\u0580\u056B\u0589", "validators", "hy");
  t.add("Using invisible characters is not allowed.", "\u0531\u0576\u057F\u0565\u057D\u0561\u0576\u0565\u056C\u056B \u0576\u056B\u0577\u0565\u0580\u056B \u0585\u0563\u057F\u0561\u0563\u0578\u0580\u056E\u0578\u0582\u0574\u0568 \u0579\u056B \u0569\u0578\u0582\u0575\u056C\u0561\u057F\u0580\u057E\u0578\u0582\u0574\u0589", "validators", "hy");
  t.add("Mixing numbers from different scripts is not allowed.", "\u0539\u057E\u0565\u0580\u056B \u056D\u0561\u057C\u0576\u0578\u0582\u0580\u0564\u0568 \u057F\u0561\u0580\u0562\u0565\u0580 \u057D\u0581\u0565\u0576\u0561\u0580\u0576\u0565\u0580\u056B\u0581 \u0579\u056B \u0569\u0578\u0582\u0575\u056C\u0561\u057F\u0580\u057E\u0578\u0582\u0574\u0589", "validators", "hy");
  t.add("Using hidden overlay characters is not allowed.", "\u0539\u0561\u0584\u0576\u057E\u0561\u056E \u056E\u0561\u056E\u056F\u0561\u0576\u056B\u0577\u0565\u0580\u056B \u0585\u0563\u057F\u0561\u0563\u0578\u0580\u056E\u0578\u0582\u0574\u0568 \u0579\u056B \u0569\u0578\u0582\u0575\u056C\u0561\u057F\u0580\u057E\u0578\u0582\u0574\u0589", "validators", "hy");
  t.add("The extension of the file is invalid ({{ extension }}). Allowed extensions are {{ extensions }}.", "\u0556\u0561\u0575\u056C\u056B \u0568\u0576\u0564\u056C\u0561\u0575\u0576\u0578\u0582\u0574\u0568 \u0561\u0576\u057E\u0561\u057E\u0565\u0580 \u0567 ({{ extension }})\u0589 \u0539\u0578\u0582\u0575\u056C\u0561\u057F\u0580\u057E\u0578\u0572 \u0568\u0576\u0564\u056C\u0561\u0575\u0576\u0578\u0582\u0574\u0576\u0565\u0580\u0576 \u0565\u0576\u055D {{ extensions }}\u0589", "validators", "hy");
  t.add("The detected character encoding is invalid ({{ detected }}). Allowed encodings are {{ encodings }}.", "\u0540\u0561\u0575\u057F\u0576\u0561\u0562\u0565\u0580\u057E\u0561\u056E \u0576\u056B\u0577\u0561\u0563\u0580\u0578\u0582\u0569\u0575\u0561\u0576 \u056F\u0578\u0564\u0568 \u0561\u0576\u057E\u0561\u057E\u0565\u0580 \u0567 ({{ detected }})\u0589 \u0539\u0578\u0582\u0575\u056C\u0561\u057F\u0580\u057E\u0578\u0572 \u056F\u0578\u0564\u0565\u0580\u0576 \u0565\u0576\u055D {{ encodings }}\u0589", "validators", "hy");
  t.add("This value is not a valid MAC address.", "\u0531\u0575\u057D \u0561\u0580\u056A\u0565\u0584\u0568 \u057E\u0561\u057E\u0565\u0580 MAC \u0570\u0561\u057D\u0581\u0565 \u0579\u0567\u0589", "validators", "hy");
  t.add("This URL is missing a top-level domain.", "\u0531\u0575\u057D URL-\u0568 \u0579\u0578\u0582\u0576\u056B \u057E\u0565\u0580\u056B\u0576 \u0574\u0561\u056F\u0561\u0580\u0564\u0561\u056F\u056B \u0564\u0578\u0574\u0565\u0575\u0576:", "validators", "hy");
  t.add("This value is too short. It should contain at least one word.|This value is too short. It should contain at least {{ min }} words.", "This value is too short. It should contain at least one word.|This value is too short. It should contain at least {{ min }} words.", "validators", "hy");
  t.add("This value is too long. It should contain one word.|This value is too long. It should contain {{ max }} words or less.", "This value is too long. It should contain one word.|This value is too long. It should contain {{ max }} words or less.", "validators", "hy");
  t.add("This value does not represent a valid week in the ISO 8601 format.", "This value does not represent a valid week in the ISO 8601 format.", "validators", "hy");
  t.add("This value is not a valid week.", "This value is not a valid week.", "validators", "hy");
  t.add("This value should not be before week \"{{ min }}\".", "This value should not be before week \"{{ min }}\".", "validators", "hy");
  t.add("This value should not be after week \"{{ max }}\".", "This value should not be after week \"{{ max }}\".", "validators", "hy");
  t.add("This form should not contain extra fields.", "\u0531\u0575\u057D \u0571\u0587\u0568 \u0579\u057A\u0565\u057F\u0584 \u0567 \u057A\u0561\u0580\u0578\u0582\u0576\u0561\u056F\u056B \u056C\u0580\u0561\u0581\u0578\u0582\u0581\u056B\u0579 \u057F\u0578\u0572\u0565\u0580\u0589", "validators", "hy");
  t.add("The uploaded file was too large. Please try to upload a smaller file.", "\u054E\u0565\u0580\u0562\u0565\u057C\u0576\u057E\u0561\u056E \u0586\u0561\u0575\u056C\u0568 \u0579\u0561\u0583\u0561\u0566\u0561\u0576\u0581 \u0574\u0565\u056E \u0567. \u053D\u0576\u0564\u0580\u057E\u0578\u0582\u0574 \u0567 \u057E\u0565\u0580\u0562\u0565\u057C\u0576\u0565\u056C \u0561\u057E\u0565\u056C\u056B \u0583\u0578\u0584\u0580 \u0579\u0561\u0583\u057D\u056B \u0586\u0561\u0575\u056C\u0589", "validators", "hy");
  t.add("The CSRF token is invalid. Please try to resubmit the form.", "CSRF \u0561\u0580\u056A\u0565\u0584\u0568 \u0561\u0576\u0569\u0578\u0582\u0575\u056C\u0561\u057F\u0580\u0565\u056C\u056B \u0567. \u0553\u0578\u0580\u0571\u0565\u0584 \u0576\u0578\u0580\u056B\u0581 \u0578\u0582\u0572\u0561\u0580\u056F\u0565\u056C \u0571\u0587\u0568\u0589", "validators", "hy");
  t.add("This value is not a valid HTML5 color.", "\u0531\u0575\u057D \u0561\u0580\u056A\u0565\u0584\u0568 \u057E\u0561\u057E\u0565\u0580 HTML5 \u0563\u0578\u0582\u0575\u0576 \u0579\u0567\u0589", "validators", "hy");
  t.add("Please enter a valid birthdate.", "\u053D\u0576\u0564\u0580\u0578\u0582\u0574 \u0565\u0576\u0584 \u0574\u0578\u0582\u057F\u0584\u0561\u0563\u0580\u0565\u056C \u057E\u0561\u057E\u0565\u0580 \u056E\u0576\u0576\u0564\u0575\u0561\u0576 \u0561\u0574\u057D\u0561\u0569\u056B\u057E\u0589", "validators", "hy");
  t.add("The selected choice is invalid.", "\u0538\u0576\u057F\u0580\u057E\u0561\u056E \u0568\u0576\u057F\u0580\u0578\u0582\u0569\u0575\u0578\u0582\u0576\u0576 \u0561\u0576\u057E\u0561\u057E\u0565\u0580 \u0567\u0589", "validators", "hy");
  t.add("The collection is invalid.", "\u0540\u0561\u0574\u0561\u056D\u0578\u0582\u0574\u0562\u0576 \u0561\u0576\u057E\u0561\u057E\u0565\u0580 \u0567\u0589", "validators", "hy");
  t.add("Please select a valid color.", "\u053D\u0576\u0564\u0580\u0578\u0582\u0574 \u0565\u0576\u0584 \u0568\u0576\u057F\u0580\u0565\u056C \u057E\u0561\u057E\u0565\u0580 \u0563\u0578\u0582\u0575\u0576\u0589", "validators", "hy");
