  t.add("This value should be the user's current password.", "\u0160ai v\u0113rt\u012Bbai ir j\u0101b\u016Bt lietot\u0101ja pa\u0161reiz\u0113jai parolei.", "validators", "lv");
  t.add("This value should have exactly {{ limit }} character.|This value should have exactly {{ limit }} characters.", "\u0160\u012Bs v\u0113rt\u012Bbas garums ir 0 rakstz\u012Bmes.|\u0160ai v\u0113rt\u012Bbai ir j\u0101b\u016Bt tie\u0161i {{ limit }} rakstz\u012Bmi garai.|\u0160ai v\u0113rt\u012Bbai ir j\u0101b\u016Bt tie\u0161i {{ limit }} rakstz\u012Bmes garai.", "validators", "lv");
