  t.add("This collection should contain {{ limit }} element or more.|This collection should contain {{ limit }} elements or more.", "\u0160is kr\u0101jums satur 0 elementu.|\u0160im kr\u0101jumam j\u0101satur vismaz {{ limit }} elements.|\u0160im kr\u0101jumam j\u0101satur vismaz {{ limit }} elementi.", "validators", "lv");
  t.add("This collection should contain {{ limit }} element or less.|This collection should contain {{ limit }} elements or less.", "\u0160is kr\u0101jums satur 0 elementu.|\u0160im kr\u0101jumam j\u0101satur ne vair\u0101k k\u0101 {{ limit }} elements.|\u0160im kr\u0101jumam j\u0101satur ne vair\u0101k k\u0101 {{ limit }} elementi.", "validators", "lv");
  t.add("This collection should contain exactly {{ limit }} element.|This collection should contain exactly {{ limit }} elements.", "\u0160is kr\u0101jums satur 0 elementu.|\u0160im kr\u0101jumam j\u0101satur tie\u0161i {{ limit }} elements.|\u0160im kr\u0101jumam j\u0101satur tie\u0161i {{ limit }} elementi.", "validators", "lv");
  t.add("Invalid card number.", "Neder\u012Bgs kartes numurs.", "validators", "lv");
