  t.add("This value is not a valid ISBN-13.", "\u0160\u012B v\u0113rt\u012Bba nav der\u012Bgs ISBN-13 numurs.", "validators", "lv");
  t.add("This value is neither a valid ISBN-10 nor a valid ISBN-13.", "\u0160\u012B v\u0113rt\u012Bba neatbilst ne der\u012Bgam ISBN-10 numuram, ne der\u012Bgm ISBN-13 numuram.", "validators", "lv");
  t.add("This value is not a valid ISSN.", "\u0160\u012B v\u0113rt\u012Bba nav der\u012Bgs ISSN numurs.", "validators", "lv");
  t.add("This value is not a valid currency.", "\u0160\u012B v\u0113rt\u012Bba nav der\u012Bga val\u016Bta.", "validators", "lv");
  t.add("This value should be equal to {{ compared_value }}.", "\u0160ai v\u0113rt\u012Bbai ir j\u0101b\u016Bt vien\u0101dai ar {{ compared_value }}.", "validators", "lv");
  t.add("This value should be greater than {{ compared_value }}.", "\u0160ai v\u0113rt\u012Bbai ir j\u0101b\u016Bt liel\u0101kai par {{ compared_value }}.", "validators", "lv");
  t.add("This value should be greater than or equal to {{ compared_value }}.", "\u0160ai v\u0113rt\u012Bbai ir j\u0101b\u016Bt liel\u0101kai vai vien\u0101dai ar {{ compared_value }}.", "validators", "lv");
  t.add("This value should be identical to {{ compared_value_type }} {{ compared_value }}.", "\u0160ai v\u0113rt\u012Bbai ir j\u0101b\u016Bt identiskai ar {{ compared_value_type }} {{ compared_value }}.", "validators", "lv");
  t.add("This value should be less than {{ compared_value }}.", "\u0160ai v\u0113rt\u012Bbai ir j\u0101b\u016Bt maz\u0101kai par {{ compared_value }}.", "validators", "lv");
  t.add("This value should be less than or equal to {{ compared_value }}.", "\u0160ai v\u0113rt\u012Bbai ir j\u0101b\u016Bt maz\u0101kai vai vien\u0101dai ar {{ compared_value }}.", "validators", "lv");
  t.add("This value should not be equal to {{ compared_value }}.", "\u0160ai v\u0113rt\u012Bbai ir j\u0101b\u016Bt vien\u0101dai ar {{ compared_value }}.", "validators", "lv");
  t.add("This value should not be identical to {{ compared_value_type }} {{ compared_value }}.", "\u0160ai v\u0113rt\u012Bbai nav j\u0101b\u016Bt identiskai ar {{ compared_value_type }} {{ compared_value }}.", "validators", "lv");
  t.add("The image ratio is too big ({{ ratio }}). Allowed maximum ratio is {{ max_ratio }}.", "Att\u0113la attiec\u012Bba ir p\u0101r\u0101k liela ({{ ratio }}). At\u013Caut\u0101 maksim\u0101l\u0101 attiec\u012Bba ir {{ max_ratio }}.", "validators", "lv");
  t.add("The image ratio is too small ({{ ratio }}). Minimum ratio expected is {{ min_ratio }}.", "Att\u0113la attiec\u012Bba ir p\u0101r\u0101k maza ({{ ratio }}). Minim\u0101l\u0101 sagaid\u0101m\u0101 attiec\u012Bba ir {{ min_ratio }}.", "validators", "lv");
  t.add("The image is square ({{ width }}x{{ height }}px). Square images are not allowed.", "\u0160is att\u0113ls ir kvadr\u0101ts ({{ width }}x{{ height }}px). Kvadr\u0101tveida att\u0113li nav at\u013Cauti.", "validators", "lv");
  t.add("The image is landscape oriented ({{ width }}x{{ height }}px). Landscape oriented images are not allowed.", "Att\u0113ls ir orient\u0113ts k\u0101 ainava ({{ width }}x{{ height }}px). Att\u0113li, kas ir orient\u0113ti k\u0101 ainavas, nav at\u013Cauti.", "validators", "lv");
  t.add("The image is portrait oriented ({{ width }}x{{ height }}px). Portrait oriented images are not allowed.", "Att\u0113ls ir orient\u0113ts k\u0101 portrets ({{ width }}x{{ height }}px). Att\u0113li, kas ir orient\u0113ti k\u0101 portreti, nav at\u013Cauti.", "validators", "lv");
  t.add("An empty file is not allowed.", "Tuk\u0161s fails nav at\u013Cauts.", "validators", "lv");
  t.add("The host could not be resolved.", "Resursdatora nosaukumu nevar atrisin\u0101t.", "validators", "lv");
  t.add("This value does not match the expected {{ charset }} charset.", "\u0160\u012B v\u0113rt\u012Bba neatbilst sagaid\u0101majai rakstz\u012Bmju kopai {{ charset }}.", "validators", "lv");
  t.add("This is not a valid Business Identifier Code (BIC).", "\u0160\u012B v\u0113rt\u012Bba nav der\u012Bgs Uz\u0146\u0113muma Identifik\u0101cijas Kods (BIC).", "validators", "lv");
  t.add("Error", "K\u013C\u016Bda", "validators", "lv");
  t.add("This is not a valid UUID.", "\u0160\u012B v\u0113rt\u012Bba nav der\u012Bgs UUID.", "validators", "lv");
  t.add("This value should be a multiple of {{ compared_value }}.", "\u0160ai v\u0113rt\u012Bbai j\u0101b\u016Bt vair\u0101kas reizes atk\u0101rtotai {{ compared_value }}.", "validators", "lv");
  t.add("This Business Identifier Code (BIC) is not associated with IBAN {{ iban }}.", "\u0160is Biznesa Identifik\u0101cijas Kods (BIC) neatbilst {{ iban }} konta numuram (IBAN).", "validators", "lv");
  t.add("This value should be valid JSON.", "\u0160ai v\u0113rt\u012Bbai j\u0101b\u016Bt der\u012Bgam JSON.", "validators", "lv");
  t.add("This collection should contain only unique elements.", "\u0160ai kolekcijai j\u0101satur tikai unik\u0101li elementi.", "validators", "lv");
  t.add("This value should be positive.", "\u0160ai v\u0113rt\u012Bbai j\u0101b\u016Bt pozit\u012Bvai.", "validators", "lv");
  t.add("This value should be either positive or zero.", "\u0160ai v\u0113rt\u012Bbai j\u0101b\u016Bt pozit\u012Bvai vai vien\u0101dai ar nulli.", "validators", "lv");
  t.add("This value should be negative.", "\u0160ai v\u0113rt\u012Bbai j\u0101b\u016Bt negat\u012Bvai.", "validators", "lv");
  t.add("This value should be either negative or zero.", "\u0160ai v\u0113rt\u012Bbai j\u0101b\u016Bt negat\u012Bvai vai vien\u0101dai ar nulli.", "validators", "lv");
  t.add("This value is not a valid timezone.", "\u0160\u012B v\u0113rt\u012Bba nav der\u012Bga laika zona.", "validators", "lv");
  t.add("This password has been leaked in a data breach, it must not be used. Please use another password.", "\u0160\u012B parole tika public\u0113ta datu nopl\u016Bd\u0113, to nedr\u012Bkst izmantot. L\u016Bdzu, izv\u0113lieties citu paroli.", "validators", "lv");
  t.add("This value should be between {{ min }} and {{ max }}.", "\u0160ai v\u0113rt\u012Bbai j\u0101b\u016Bt starp {{ min }} un {{ max }}.", "validators", "lv");
  t.add("This value is not a valid hostname.", "\u0160\u012B v\u0113rt\u012Bba nav der\u012Bgs t\u012Bmek\u013Ca servera nosaukums.", "validators", "lv");
  t.add("The number of elements in this collection should be a multiple of {{ compared_value }}.", "Elementu skaitam \u0161aj\u0101 kolekcij\u0101 j\u0101b\u016Bt {{ compared_value }} reizin\u0101jumam.", "validators", "lv");
  t.add("This value should satisfy at least one of the following constraints:", "\u0160ai v\u0113rt\u012Bbai j\u0101iek\u013Caujas vismaz vien\u0101 no sekojo\u0161iem ierobe\u017Eojumiem:", "validators", "lv");
  t.add("Each element of this collection should satisfy its own set of constraints.", "\u0160\u012Bs kolekcijas katram elementam j\u0101iek\u013Caujas sav\u0101 ierobe\u017Eojumu kop\u0101.", "validators", "lv");
  t.add("This value is not a valid International Securities Identification Number (ISIN).", "\u0160\u012B v\u0113rt\u012Bba nav der\u012Bgs starptautiskais v\u0113rtspap\u012Bru identifik\u0101cijas numurs (ISIN).", "validators", "lv");
  t.add("This value should be a valid expression.", "\u0160ai v\u0113rt\u012Bbai j\u0101b\u016Bt korektai izteiksmei.", "validators", "lv");
  t.add("This value is not a valid CSS color.", "\u0160\u012B v\u0113rt\u012Bba nav korekta CSS kr\u0101sa.", "validators", "lv");
  t.add("This value is not a valid CIDR notation.", "\u0160\u012B v\u0113rt\u012Bba nav korekts CIDR apz\u012Bm\u0113jums.", "validators", "lv");
  t.add("The value of the netmask should be between {{ min }} and {{ max }}.", "T\u012Bkla maskas (netmask) v\u0113rt\u012Bbai j\u0101b\u016Bt starp {{ min }} un {{ max }}.", "validators", "lv");
  t.add("The filename is too long. It should have {{ filename_max_length }} character or less.|The filename is too long. It should have {{ filename_max_length }} characters or less.", "Faila nosaukums ir p\u0101r\u0101k gar\u0161. Tas var b\u016Bt {{ filename_max_length }} rakstz\u012Bmi gar\u0161 vai \u012Bs\u0101ks.|Faila nosaukums ir p\u0101r\u0101k gar\u0161. Tas var b\u016Bt {{ filename_max_length }} rakstz\u012Bmes gar\u0161 vai \u012Bs\u0101ks.", "validators", "lv");
  t.add("The password strength is too low. Please use a stronger password.", "Paroles stiprums ir p\u0101r\u0101k zems. L\u016Bdzu, izmantojiet sp\u0113c\u012Bg\u0101ku paroli.", "validators", "lv");
  t.add("This value contains characters that are not allowed by the current restriction-level.", "\u0160\u012B v\u0113rt\u012Bba satur rakstz\u012Bmes, kuras nav at\u013Cautas pa\u0161reiz\u0113j\u0101 ierobe\u017Eojuma l\u012Bmen\u012B.", "validators", "lv");
  t.add("Using invisible characters is not allowed.", "Neredzamu rakstz\u012Bmju izmanto\u0161ana nav at\u013Cauta.", "validators", "lv");
  t.add("Mixing numbers from different scripts is not allowed.", "Nav at\u013Cauts sajaukt numurus no da\u017E\u0101diem skriptiem.", "validators", "lv");
  t.add("Using hidden overlay characters is not allowed.", "Sl\u0113ptu p\u0101rkl\u0101juma rakstz\u012Bmju izmanto\u0161ana nav at\u013Cauta.", "validators", "lv");
  t.add("The extension of the file is invalid ({{ extension }}). Allowed extensions are {{ extensions }}.", "Faila papla\u0161in\u0101jums nav der\u012Bgs ({{ extension }}). At\u013Cautie papla\u0161in\u0101jumi ir {{ extensions }}.", "validators", "lv");
  t.add("The detected character encoding is invalid ({{ detected }}). Allowed encodings are {{ encodings }}.", "Noteiktais rakstz\u012Bmju kod\u0113jums nav der\u012Bgs ({{ detected }}). At\u013Cautie kod\u0113jumi ir {{ encodings }}.", "validators", "lv");
  t.add("This value is not a valid MAC address.", "\u0160\u012B v\u0113rt\u012Bba nav der\u012Bga MAC adrese.", "validators", "lv");
  t.add("This URL is missing a top-level domain.", "\u0160im URL tr\u016Bkst aug\u0161\u0113j\u0101 l\u012Bme\u0146a dom\u0113na.", "validators", "lv");
  t.add("This value is too short. It should contain at least one word.|This value is too short. It should contain at least {{ min }} words.", "\u0160\u012B v\u0113rt\u012Bba ir p\u0101r\u0101k \u012Bsa. Tai b\u016Btu j\u0101b\u016Bt vismaz vienu v\u0101rdu garai.|\u0160\u012B v\u0113rt\u012Bba ir p\u0101r\u0101k \u012Bsa. Tai b\u016Btu j\u0101b\u016Bt ne maz\u0101k k\u0101 {{ min }} v\u0101rdus garai.", "validators", "lv");
  t.add("This value is too long. It should contain one word.|This value is too long. It should contain {{ max }} words or less.", "\u0160\u012B v\u0113rt\u012Bba ir p\u0101r\u0101k gara. Tai b\u016Btu j\u0101b\u016Bt vienam v\u0101rdam.|\u0160\u012B v\u0113rt\u012Bba ir p\u0101r\u0101k gara. Tai b\u016Btu j\u0101b\u016Bt ne vair\u0101k k\u0101 {{ max }} v\u0101rdus garai.", "validators", "lv");
  t.add("This value does not represent a valid week in the ISO 8601 format.", "\u0160\u012B v\u0113rt\u012Bba neatspogu\u013Co ned\u0113\u013Cu ISO 8601 format\u0101.", "validators", "lv");
