  t.add("This is not a valid IP address.", "\u041E\u0432\u0430\u0430 \u0432\u0440\u0435\u0434\u043D\u043E\u0441\u0442 \u043D\u0435 \u0435 \u0432\u0430\u043B\u0438\u0434\u043D\u0430 IP \u0430\u0434\u0440\u0435\u0441\u0430.", "validators", "mk");
