  t.add("This value is not a valid locale.", "\u041E\u0432\u0430\u0430 \u0432\u0440\u0435\u0434\u043D\u043E\u0441\u0442 \u043D\u0435 \u0435 \u0432\u0430\u043B\u0438\u0434\u043D\u0430 \u043B\u043E\u043A\u0430\u043B\u0438\u0437\u0430\u0446\u0438\u0458\u0430.", "validators", "mk");
  t.add("This value is not a valid country.", "\u041E\u0432\u0430\u0430 \u0432\u0440\u0435\u0434\u043D\u043E\u0441\u0442 \u043D\u0435 \u0435 \u0432\u0430\u043B\u0438\u0434\u043D\u0430 \u0437\u0435\u043C\u0458\u0430.", "validators", "mk");
  t.add("This value is already used.", "\u041E\u0432\u0430\u0430 \u0432\u0440\u0435\u0434\u043D\u043E\u0441\u0442 \u0432\u0435\u045C\u0435 \u0441\u0435 \u043A\u043E\u0440\u0438\u0441\u0442\u0438.", "validators", "mk");
  t.add("The size of the image could not be detected.", "\u0413\u043E\u043B\u0435\u043C\u0438\u043D\u0430\u0442\u0430 \u043D\u0430 \u0441\u043B\u0438\u043A\u0430\u0442\u0430 \u043D\u0435 \u043C\u043E\u0436\u0435 \u0434\u0430 \u0441\u0435 \u0434\u0435\u0442\u0435\u043A\u0442\u0438\u0440\u0430.", "validators", "mk");
  t.add("The image width is too big ({{ width }}px). Allowed maximum width is {{ max_width }}px.", "\u0428\u0438\u0440\u0438\u043D\u0430\u0442\u0430 \u043D\u0430 \u0441\u043B\u0438\u043A\u0430\u0442\u0430 \u0435 \u043F\u0440\u0435\u0433\u043E\u043B\u0435\u043C\u0430 ({{ width }}px). \u041C\u0430\u043A\u0441\u0438\u043C\u0430\u043B\u043D\u0430\u0442\u0430 \u0434\u043E\u0437\u0432\u043E\u043B\u0435\u043D\u0430 \u0448\u0438\u0440\u0438\u043D\u0430 \u0435 {{ max_width }}px.", "validators", "mk");
  t.add("The image width is too small ({{ width }}px). Minimum width expected is {{ min_width }}px.", "\u0428\u0438\u0440\u0438\u043D\u0430\u0442\u0430 \u043D\u0430 \u0441\u043B\u0438\u043A\u0430\u0442\u0430 \u0435 \u043F\u0440\u0435\u043C\u0430\u043B\u0430 ({{ width }}px). \u041C\u0438\u043D\u0438\u043C\u0430\u043B\u043D\u0430\u0442\u0430 \u0434\u043E\u0437\u0432\u043E\u043B\u0435\u043D\u0430 \u0448\u0438\u0440\u0438\u043D\u0430 \u0435 {{ min_width }}px.", "validators", "mk");
  t.add("The image height is too big ({{ height }}px). Allowed maximum height is {{ max_height }}px.", "\u0412\u0438\u0441\u0438\u043D\u0430\u0442\u0430 \u043D\u0430 \u0441\u043B\u0438\u043A\u0430\u0442\u0430 \u0435 \u043F\u0440\u0435\u0433\u043E\u043B\u0435\u043C\u0430 ({{ height }}px). \u041C\u0430\u043A\u0441\u0438\u043C\u0430\u043B\u043D\u0430\u0442\u0430 \u0434\u043E\u0437\u0432\u043E\u043B\u0435\u043D\u0430 \u0432\u0438\u0441\u0438\u043D\u0430 \u0435 {{ max_height }}px.", "validators", "mk");
  t.add("The image height is too small ({{ height }}px). Minimum height expected is {{ min_height }}px.", "\u0412\u0438\u0441\u0438\u043D\u0430\u0442\u0430 \u043D\u0430 \u0441\u043B\u0438\u043A\u0430\u0442\u0430 \u0435 \u043F\u0440\u0435\u043C\u0430\u043B\u0430 ({{ height }}px). \u041C\u0438\u043D\u0438\u043C\u0430\u043B\u043D\u0430\u0442\u0430 \u0434\u043E\u0437\u0432\u043E\u043B\u0435\u043D\u0430 \u0432\u0438\u0441\u0438\u043D\u0430 \u0435 {{ min_height }}px.", "validators", "mk");
  t.add("This value should be the user's current password.", "\u041E\u0432\u0430\u0430 \u0432\u0440\u0435\u0434\u043D\u043E\u0441\u0442 \u0442\u0440\u0435\u0431\u0430 \u0434\u0430 \u0431\u0438\u0434\u0435 \u0441\u0435\u0433\u0430\u0448\u043D\u0430\u0442\u0430 \u043B\u043E\u0437\u0438\u043D\u043A\u0430 \u043D\u0430 \u043A\u043E\u0440\u0438\u0441\u043D\u0438\u043A\u043E\u0442.", "validators", "mk");
  t.add("This value should have exactly {{ limit }} character.|This value should have exactly {{ limit }} characters.", "\u041E\u0432\u0430\u0430 \u0432\u0440\u0435\u0434\u043D\u043E\u0441\u0442 \u0442\u0440\u0435\u0431\u0430 \u0434\u0430 \u0438\u043C\u0430 \u0442\u043E\u0447\u043D\u043E {{ limit }} \u043A\u0430\u0440\u0430\u043A\u0442\u0435\u0440.|\u041E\u0432\u0430\u0430 \u0432\u0440\u0435\u0434\u043D\u043E\u0441\u0442 \u0442\u0440\u0435\u0431\u0430 \u0434\u0430 \u0438\u043C\u0430 \u0442\u043E\u0447\u043D\u043E {{ limit }} \u043A\u0430\u0440\u0430\u043A\u0442\u0435\u0440\u0438.", "validators", "mk");
  t.add("The file was only partially uploaded.", "\u0414\u0430\u0442\u043E\u0442\u0435\u043A\u0430\u0442\u0430 \u0435 \u0441\u0430\u043C\u043E \u0434\u0435\u043B\u0443\u043C\u043D\u043E \u043F\u043E\u0434\u0438\u0433\u043D\u0430\u0442\u0430.", "validators", "mk");
  t.add("No file was uploaded.", "\u0414\u0430\u0442\u043E\u0442\u0435\u043A\u0430\u0442\u0430 \u043D\u0435 \u0435 \u043F\u043E\u0434\u0438\u0433\u043D\u0430\u0442\u0430.", "validators", "mk");
  t.add("No temporary folder was configured in php.ini.", "\u041D\u0435 \u0435 \u043A\u043E\u043D\u0444\u0438\u0433\u0443\u0440\u0438\u0440\u0430\u043D\u0430 \u043F\u0440\u0438\u0432\u0440\u0435\u043C\u0435\u043D\u0430 \u043F\u0430\u043F\u043A\u0430 \u0432\u043E php.ini, \u0438\u043B\u0438 \u043A\u043E\u043D\u0444\u0438\u0433\u0443\u0440\u0438\u0440\u0430\u043D\u0430\u0442\u0430 \u043F\u0430\u043F\u043A\u0430 \u043D\u0435 \u043F\u043E\u0441\u0442\u043E\u0438.", "validators", "mk");
  t.add("Cannot write temporary file to disk.", "\u041D\u0435 \u043C\u043E\u0436\u0435 \u0434\u0430 \u0441\u0435 \u043D\u0430\u043F\u0438\u0448\u0435 \u043F\u0440\u0438\u0432\u0440\u0435\u043C\u0435\u043D\u0430 \u0434\u0430\u0442\u043E\u0442\u0435\u043A\u0430 \u043D\u0430 \u0434\u0438\u0441\u043A\u043E\u0442.", "validators", "mk");
  t.add("A PHP extension caused the upload to fail.", "PHP \u0435\u043A\u0441\u0442\u0435\u043D\u0437\u0438\u0458\u0430\u0442\u0430 \u043F\u0440\u0435\u0434\u0438\u0437\u0432\u0438\u043A\u0430 \u043F\u043E\u0434\u0438\u0433\u043D\u0443\u0432\u0430\u045A\u0435\u0442\u043E \u0434\u0430 \u0431\u0438\u0434\u0435 \u043D\u0435\u0443\u0441\u043F\u0435\u0448\u043D\u043E.", "validators", "mk");
  t.add("This collection should contain {{ limit }} element or more.|This collection should contain {{ limit }} elements or more.", "\u041E\u0432\u0430\u0430 \u043A\u043E\u043B\u0435\u043A\u0446\u0438\u0458\u0430 \u0442\u0440\u0435\u0431\u0430 \u0434\u0430 \u0441\u043E\u0434\u0440\u0436\u0438 {{ limit }} \u0435\u043B\u0435\u043C\u0435\u043D\u0442 \u0438\u043B\u0438 \u043F\u043E\u0432\u0435\u045C\u0435.|\u041E\u0432\u0430\u0430 \u043A\u043E\u043B\u0435\u043A\u0446\u0438\u0458\u0430 \u0442\u0440\u0435\u0431\u0430 \u0434\u0430 \u0441\u043E\u0434\u0440\u0436\u0438 {{ limit }} \u0435\u043B\u0435\u043C\u0435\u043D\u0442\u0438 \u0438\u043B\u0438 \u043F\u043E\u0432\u0435\u045C\u0435.", "validators", "mk");
  t.add("This collection should contain {{ limit }} element or less.|This collection should contain {{ limit }} elements or less.", "\u041E\u0432\u0430\u0430 \u043A\u043E\u043B\u0435\u043A\u0446\u0438\u0458\u0430 \u0442\u0440\u0435\u0431\u0430 \u0434\u0430 \u0441\u043E\u0434\u0440\u0436\u0438 {{ limit }} \u0435\u043B\u0435\u043C\u0435\u043D\u0442 \u0438\u043B\u0438 \u043F\u043E\u043C\u0430\u043B\u043A\u0443.|\u041E\u0432\u0430\u0430 \u043A\u043E\u043B\u0435\u043A\u0446\u0438\u0458\u0430 \u0442\u0440\u0435\u0431\u0430 \u0434\u0430 \u0441\u043E\u0434\u0440\u0436\u0438 {{ limit }} \u0435\u043B\u0435\u043C\u0435\u043D\u0442\u0438 \u0438\u043B\u0438 \u043F\u043E\u043C\u0430\u043B\u043A\u0443.", "validators", "mk");
  t.add("This collection should contain exactly {{ limit }} element.|This collection should contain exactly {{ limit }} elements.", "\u041E\u0432\u0430\u0430 \u043A\u043E\u043B\u0435\u043A\u0446\u0438\u0458\u0430 \u0442\u0440\u0435\u0431\u0430 \u0434\u0430 \u0441\u043E\u0434\u0440\u0436\u0438 \u0442\u043E\u0447\u043D\u043E {{ limit }} \u0435\u043B\u0435\u043C\u0435\u043D\u0442.|\u041E\u0432\u0430\u0430 \u043A\u043E\u043B\u0435\u043A\u0446\u0438\u0458\u0430 \u0442\u0440\u0435\u0431\u0430 \u0434\u0430 \u0441\u043E\u0434\u0440\u0436\u0438 \u0442\u043E\u0447\u043D\u043E {{ limit }} \u0435\u043B\u0435\u043C\u0435\u043D\u0442\u0438.", "validators", "mk");
  t.add("Invalid card number.", "\u0411\u0440\u043E\u0458\u043E\u0442 \u043D\u0430 \u043A\u0430\u0440\u0442\u0438\u0447\u043A\u0430\u0442\u0430 \u043D\u0435 \u0435 \u0432\u0430\u043B\u0438\u0434\u0435\u043D.", "validators", "mk");
  t.add("Unsupported card type or invalid card number.", "\u041D\u0435\u043F\u043E\u0434\u0434\u0440\u0436\u0430\u043D \u0442\u0438\u043F \u043D\u0430 \u043A\u0430\u0440\u0442\u0438\u0447\u043A\u0430 \u0438\u043B\u0438 \u0431\u0440\u043E\u0458\u043E\u0442 \u043D\u0430 \u043A\u0430\u0440\u0442\u0438\u0447\u043A\u0430\u0442\u0430 \u043D\u0435 \u0435 \u0432\u0430\u043B\u0438\u0434\u0435\u043D.", "validators", "mk");
  t.add("This is not a valid International Bank Account Number (IBAN).", "\u041E\u0432\u0430\u0430 \u0432\u0440\u0435\u0434\u043D\u043E\u0441\u0442 \u043D\u0435 \u0435 \u0432\u0430\u043B\u0438\u0434\u0435\u043D \u041C\u0435\u0453\u0443\u043D\u0430\u0440\u043E\u0434\u0435\u043D \u0411\u0430\u043D\u043A\u0430\u0440\u0441\u043A\u0438 \u0421\u043C\u0435\u0442\u043A\u0430 \u0411\u0440\u043E\u0458 (IBAN).", "validators", "mk");
  t.add("This value is not a valid ISBN-10.", "\u041E\u0432\u0430\u0430 \u0432\u0440\u0435\u0434\u043D\u043E\u0441\u0442 \u043D\u0435 \u0435 \u0432\u0430\u043B\u0438\u0434\u0435\u043D ISBN-10.", "validators", "mk");
  t.add("This value is not a valid ISBN-13.", "\u041E\u0432\u0430\u0430 \u0432\u0440\u0435\u0434\u043D\u043E\u0441\u0442 \u043D\u0435 \u0435 \u0432\u0430\u043B\u0438\u0434\u0435\u043D ISBN-13.", "validators", "mk");
  t.add("This value is neither a valid ISBN-10 nor a valid ISBN-13.", "\u041E\u0432\u0430\u0430 \u0432\u0440\u0435\u0434\u043D\u043E\u0441\u0442 \u043D\u0435 \u0435 \u043D\u0438\u0442\u0443 \u0432\u0430\u043B\u0438\u0434\u0435\u043D ISBN-10 \u043D\u0438\u0442\u0443 \u0432\u0430\u043B\u0438\u0434\u0435\u043D ISBN-13.", "validators", "mk");
  t.add("This value is not a valid ISSN.", "\u041E\u0432\u0430\u0430 \u0432\u0440\u0435\u0434\u043D\u043E\u0441\u0442 \u043D\u0435 \u0435 \u0432\u0430\u043B\u0438\u0434\u0435\u043D ISSN.", "validators", "mk");
  t.add("This value is not a valid currency.", "\u041E\u0432\u0430\u0430 \u0432\u0440\u0435\u0434\u043D\u043E\u0441\u0442 \u043D\u0435 \u0435 \u0432\u0430\u043B\u0438\u0434\u043D\u0430 \u0432\u0430\u043B\u0443\u0442\u0430.", "validators", "mk");
  t.add("This value should be equal to {{ compared_value }}.", "\u041E\u0432\u0430\u0430 \u0432\u0440\u0435\u0434\u043D\u043E\u0441\u0442 \u0442\u0440\u0435\u0431\u0430 \u0434\u0430 \u0431\u0438\u0434\u0435 \u0435\u0434\u043D\u0430\u043A\u0432\u0430 \u043D\u0430 {{ compared_value }}.", "validators", "mk");
  t.add("This value should be greater than {{ compared_value }}.", "\u041E\u0432\u0430\u0430 \u0432\u0440\u0435\u0434\u043D\u043E\u0441\u0442 \u0442\u0440\u0435\u0431\u0430 \u0434\u0430 \u0435 \u043F\u043E\u0433\u043E\u043B\u0435\u043C\u0430 \u043E\u0434 {{ compared_value }}.", "validators", "mk");
  t.add("This value should be greater than or equal to {{ compared_value }}.", "\u041E\u0432\u0430\u0430 \u0432\u0440\u0435\u0434\u043D\u043E\u0441\u0442 \u0442\u0440\u0435\u0431\u0430 \u0434\u0430 \u0435 \u043F\u043E\u0433\u043E\u043B\u0435\u043C\u0430 \u0438\u043B\u0438 \u0435\u0434\u043D\u0430\u043A\u0432\u0430 \u043D\u0430 {{ compared_value }}.", "validators", "mk");
  t.add("This value should be identical to {{ compared_value_type }} {{ compared_value }}.", "\u041E\u0432\u0430\u0430 \u0432\u0440\u0435\u0434\u043D\u043E\u0441\u0442 \u0442\u0440\u0435\u0431\u0430 \u0434\u0430 \u0435 \u0438\u0434\u0435\u043D\u0442\u0438\u0447\u043D\u0430 \u043D\u0430 {{ compared_value_type }} {{ compared_value }}.", "validators", "mk");
  t.add("This value should be less than {{ compared_value }}.", "\u041E\u0432\u0430\u0430 \u0432\u0440\u0435\u0434\u043D\u043E\u0441\u0442 \u0442\u0440\u0435\u0431\u0430 \u0434\u0430 \u0435 \u043F\u043E\u043C\u0430\u043B\u0430 \u043E\u0434 {{ compared_value }}.", "validators", "mk");
  t.add("This value should be less than or equal to {{ compared_value }}.", "\u041E\u0432\u0430\u0430 \u0432\u0440\u0435\u0434\u043D\u043E\u0441\u0442 \u0442\u0440\u0435\u0431\u0430 \u0434\u0430 \u0435 \u043F\u043E\u043C\u0430\u043B\u0430 \u0438\u043B\u0438 \u0435\u0434\u043D\u0430\u043A\u0432\u0430 \u043D\u0430 {{ compared_value }}.", "validators", "mk");
  t.add("This value should not be equal to {{ compared_value }}.", "\u041E\u0432\u0430\u0430 \u0432\u0440\u0435\u0434\u043D\u043E\u0441\u0442 \u0442\u0440\u0435\u0431\u0430 \u0434\u0430 \u043D\u0435 \u0431\u0438\u0434\u0435 \u0435\u0434\u043D\u0430\u043A\u0432\u0430 \u043D\u0430 {{ compared_value }}.", "validators", "mk");
  t.add("This value should not be identical to {{ compared_value_type }} {{ compared_value }}.", "\u041E\u0432\u0430\u0430 \u0432\u0440\u0435\u0434\u043D\u043E\u0441\u0442 \u0442\u0440\u0435\u0431\u0430 \u0434\u0430 \u043D\u0435 \u0431\u0438\u0434\u0435 \u0438\u0434\u0435\u043D\u0442\u0438\u0447\u043D\u0430 \u0441\u043E {{ compared_value_type }} {{ compared_value }}.", "validators", "mk");
  t.add("The image ratio is too big ({{ ratio }}). Allowed maximum ratio is {{ max_ratio }}.", "\u0421\u043E\u043E\u0434\u043D\u043E\u0441\u043E\u0442 \u043D\u0430 \u0441\u043B\u0438\u043A\u0430\u0442\u0430 \u0435 \u043F\u0440\u0435\u0433\u043E\u043B\u0435\u043C ({{ ratio }}).\u041C\u0430\u043A\u0441\u0438\u043C\u0430\u043B\u043D\u0438\u043E\u0442 \u0434\u043E\u0437\u0432\u043E\u043B\u0435\u043D \u0441\u043E\u043E\u0434\u043D\u043E\u0441 \u0435 {{ max_ratio }}.", "validators", "mk");
  t.add("The image ratio is too small ({{ ratio }}). Minimum ratio expected is {{ min_ratio }}.", "\u0421\u043E\u043E\u0434\u043D\u043E\u0441\u043E\u0442 \u043D\u0430 \u0441\u043B\u0438\u043A\u0430\u0442\u0430 \u0435 \u043F\u0440\u0435\u043C\u0430\u043B ({{ ratio }}). \u041C\u0438\u043D\u0438\u043C\u0430\u043B\u043D\u0438\u043E\u0442 \u0434\u043E\u0437\u0432\u043E\u043B\u0435\u043D \u0441\u043E\u043E\u0434\u043D\u043E\u0441 \u0435 {{ min_ratio }}.", "validators", "mk");
  t.add("The image is square ({{ width }}x{{ height }}px). Square images are not allowed.", "\u0421\u043B\u0438\u043A\u0430\u0442\u0430 \u0435 \u043A\u0432\u0430\u0434\u0440\u0430\u0442\u043D\u0430 ({{ width }}x{{ height }}px). \u041A\u0432\u0430\u0434\u0440\u0430\u0442\u043D\u0438 \u0441\u043B\u0438\u043A\u0438 \u043D\u0435 \u0441\u0435 \u0434\u043E\u0437\u0432\u043E\u043B\u0435\u043D\u0438.", "validators", "mk");
  t.add("The image is landscape oriented ({{ width }}x{{ height }}px). Landscape oriented images are not allowed.", "\u0421\u043B\u0438\u043A\u0430\u0442\u0430 \u0435 \u043E\u0440\u0438\u0435\u043D\u0442\u0438\u0440\u0430\u043D\u0430 \u043A\u043E\u043D \u043F\u0435\u0458\u0437\u0430\u0436 ({{ width }}x{{ height }}px). \u0421\u043B\u0438\u043A\u0438\u0442\u0435 \u043E\u0440\u0438\u0435\u043D\u0442\u0438\u0440\u0430\u043D\u0438 \u043A\u043E\u043D \u043F\u0435\u0458\u0437\u0430\u0436 \u043D\u0435 \u0441\u0435 \u0434\u043E\u0437\u0432\u043E\u043B\u0435\u043D\u0438.", "validators", "mk");
  t.add("The image is portrait oriented ({{ width }}x{{ height }}px). Portrait oriented images are not allowed.", "\u0421\u043B\u0438\u043A\u0430\u0442\u0430 \u0435 \u043E\u0440\u0438\u0435\u043D\u0442\u0438\u0440\u0430\u043D\u0430 \u043A\u043E\u043D \u043F\u043E\u0440\u0442\u0440\u0435\u0442 ({{ width }}x{{ height }}px). \u0421\u043B\u0438\u043A\u0438\u0442\u0435 \u043E\u0440\u0438\u0435\u043D\u0442\u0438\u0440\u0430\u043D\u0438 \u043A\u043E\u043D \u043F\u043E\u0440\u0442\u0440\u0435\u0442 \u043D\u0435 \u0441\u0435 \u0434\u043E\u0437\u0432\u043E\u043B\u0435\u043D\u0438.", "validators", "mk");
  t.add("An empty file is not allowed.", "\u041F\u0440\u0430\u0437\u043D\u0430 \u0434\u0430\u0442\u043E\u0442\u0435\u043A\u0430 \u043D\u0435 \u0435 \u0434\u043E\u0437\u0432\u043E\u043B\u0435\u043D\u0430.", "validators", "mk");
  t.add("The host could not be resolved.", "\u0425\u043E\u0441\u0442\u043E\u0442 \u0435 \u043D\u0435\u0434\u043E\u0441\u0442\u0430\u043F\u0435\u043D.", "validators", "mk");
  t.add("This value does not match the expected {{ charset }} charset.", "\u041E\u0432\u0430\u0430 \u0432\u0440\u0435\u0434\u043D\u043E\u0441\u0442 \u043D\u0435 \u0441\u0435 \u0441\u043E\u0432\u043F\u0430\u0453\u0430 \u0441\u043E \u043E\u0447\u0435\u043A\u0443\u0432\u0430\u043D\u0438\u043E\u0442 {{ charset }} \u0441\u0435\u0442 \u043D\u0430 \u043A\u0430\u0440\u0430\u043A\u0442\u0435\u0440\u0438 (charset).", "validators", "mk");
  t.add("This is not a valid Business Identifier Code (BIC).", "\u041E\u0432\u0430\u0430 \u0432\u0440\u0435\u0434\u043D\u043E\u0441\u0442 \u043D\u0435 \u0435 \u0432\u0430\u043B\u0438\u0434\u0435\u043D \u0411\u0438\u0437\u043D\u0438\u0441 \u0418\u0434\u0435\u043D\u0442\u0438\u0444\u0438\u043A\u0430\u0446\u0438\u0441\u043A\u0438 \u041A\u043E\u0434 (BIC).", "validators", "mk");
  t.add("Error", "\u0413\u0440\u0435\u0448\u043A\u0430", "validators", "mk");
  t.add("This is not a valid UUID.", "\u041E\u0432\u0430\u0430 \u0432\u0440\u0435\u0434\u043D\u043E\u0441\u0442 \u043D\u0435 \u0435 \u0432\u0430\u043B\u0438\u0434\u0435\u043D UUID.", "validators", "mk");
  t.add("This value should be a multiple of {{ compared_value }}.", "\u041E\u0432\u0430\u0430 \u0432\u0440\u0435\u0434\u043D\u043E\u0441\u0442 \u0442\u0440\u0435\u0431\u0430 \u0434\u0430 \u0431\u0438\u0434\u0435 \u043F\u043E\u0432\u0435\u045C\u0435\u043A\u0440\u0430\u0442\u043D\u0430 \u043E\u0434 {{ compared_value }}.", "validators", "mk");
  t.add("This Business Identifier Code (BIC) is not associated with IBAN {{ iban }}.", "\u041E\u0432\u043E\u0458 \u0431\u0438\u0437\u043D\u0438\u0441 \u0438\u0434\u0435\u043D\u0442\u0438\u0444\u0438\u043A\u0430\u0446\u0438\u0441\u043A\u0438 \u043A\u043E\u0434 (BIC) \u043D\u0435 \u0435 \u043F\u043E\u0432\u0440\u0437\u0430\u043D \u0441\u043E IBAN {{ iban }}.", "validators", "mk");
  t.add("This value should be valid JSON.", "\u041E\u0432\u0430\u0430 \u0432\u0440\u0435\u0434\u043D\u043E\u0441\u0442 \u0442\u0440\u0435\u0431\u0430 \u0434\u0430 \u0431\u0438\u0434\u0435 \u0432\u0430\u043B\u0438\u0434\u0435\u043D JSON.", "validators", "mk");
  t.add("This collection should contain only unique elements.", "\u041E\u0432\u0430\u0430 \u043A\u043E\u043B\u0435\u043A\u0446\u0438\u0458\u0430 \u0442\u0440\u0435\u0431\u0430 \u0434\u0430 \u0441\u043E\u0434\u0440\u0436\u0438 \u0441\u0430\u043C\u043E \u0443\u043D\u0438\u043A\u0430\u0442\u043D\u0438 \u0435\u043B\u0435\u043C\u0435\u043D\u0442\u0438.", "validators", "mk");
  t.add("This value should be positive.", "\u041E\u0432\u0430\u0430 \u0432\u0440\u0435\u0434\u043D\u043E\u0441\u0442 \u0442\u0440\u0435\u0431\u0430 \u0434\u0430 \u0431\u0438\u0434\u0435 \u043F\u043E\u0437\u0438\u0442\u0438\u0432\u043D\u0430.", "validators", "mk");
  t.add("This value should be either positive or zero.", "\u041E\u0432\u0430\u0430 \u0432\u0440\u0435\u0434\u043D\u043E\u0441\u0442 \u0442\u0440\u0435\u0431\u0430 \u0434\u0430 \u0431\u0438\u0434\u0435 \u0438\u043B\u0438 \u043F\u043E\u0437\u0438\u0442\u0438\u0432\u043D\u0430 \u0438\u043B\u0438 \u043D\u0443\u043B\u0430.", "validators", "mk");
  t.add("This value should be negative.", "\u041E\u0432\u0430\u0430 \u0432\u0440\u0435\u0434\u043D\u043E\u0441\u0442 \u0442\u0440\u0435\u0431\u0430 \u0434\u0430 \u0431\u0438\u0434\u0435 \u043D\u0435\u0433\u0430\u0442\u0438\u0432\u043D\u0430.", "validators", "mk");
  t.add("This value should be either negative or zero.", "\u041E\u0432\u0430\u0430 \u0432\u0440\u0435\u0434\u043D\u043E\u0441\u0442 \u0442\u0440\u0435\u0431\u0430 \u0434\u0430 \u0431\u0438\u0434\u0435 \u0438\u043B\u0438 \u043D\u0435\u0433\u0430\u0442\u0438\u0432\u043D\u0430 \u0438\u043B\u0438 \u043D\u0443\u043B\u0430.", "validators", "mk");
  t.add("This value is not a valid timezone.", "\u041E\u0432\u0430\u0430 \u0432\u0440\u0435\u0434\u043D\u043E\u0441\u0442 \u043D\u0435 \u0435 \u0432\u0430\u043B\u0438\u0434\u043D\u0430 \u0432\u0440\u0435\u043C\u0435\u043D\u0441\u043A\u0430 \u0437\u043E\u043D\u0430.", "validators", "mk");
  t.add("This password has been leaked in a data breach, it must not be used. Please use another password.", "\u041E\u0432\u0430\u0430 \u043B\u043E\u0437\u0438\u043D\u043A\u0430 \u0435 \u043A\u043E\u043C\u043F\u0440\u043E\u043C\u0438\u0442\u0438\u0440\u0430\u043D\u0430 \u0438 \u043D\u0435 \u0441\u043C\u0435\u0435 \u0434\u0430 \u0431\u0438\u0434\u0435 \u043A\u043E\u0440\u0438\u0441\u0442\u0435\u043D\u0430. \u0412\u0435 \u043C\u043E\u043B\u0438\u043C\u0435 \u0443\u043F\u043E\u0442\u0440\u0435\u0431\u0435\u0442\u0435 \u0434\u0440\u0443\u0433\u0430 \u043B\u043E\u0437\u0438\u043D\u043A\u0430.", "validators", "mk");
  t.add("This value should be between {{ min }} and {{ max }}.", "\u041E\u0432\u0430\u0430 \u0432\u0440\u0435\u0434\u043D\u043E\u0441\u0442 \u0442\u0440\u0435\u0431\u0430 \u0434\u0430 \u0435 \u043F\u043E\u043C\u0435\u0453\u0443 {{ min }} \u0438 {{ max }}.", "validators", "mk");
  t.add("This value is not a valid hostname.", "\u041E\u0432\u0430\u0430 \u0432\u0440\u0435\u0434\u043D\u043E\u0441\u0442 \u043D\u0435 \u0435 \u0432\u0430\u043B\u0438\u0434\u043D\u043E \u0438\u043C\u0435 \u0437\u0430 \u043C\u0440\u0435\u0436\u043D\u0438\u043E\u0442 \u0441\u043C\u0435\u0442\u0430\u0447 (hostname).", "validators", "mk");
  t.add("The number of elements in this collection should be a multiple of {{ compared_value }}.", "\u0411\u0440\u043E\u0458\u043E\u0442 \u043D\u0430 \u0435\u043B\u0435\u043C\u0435\u043D\u0442\u0438 \u0432\u043E \u043E\u0432\u0430\u0430 \u043A\u043E\u043B\u0435\u043A\u0446\u0438\u0458\u0430 \u0442\u0440\u0435\u0431\u0430 \u0434\u0430 \u0431\u0438\u0434\u0435 \u043F\u043E\u0432\u0435\u045C\u0435\u043A\u0440\u0430\u0442\u0435\u043D \u043E\u0434 {{ compared_value }}.", "validators", "mk");
  t.add("This value should satisfy at least one of the following constraints:", "\u041E\u0432\u0430\u0430 \u0432\u0440\u0435\u0434\u043D\u043E\u0441\u0442 \u0442\u0440\u0435\u0431\u0430 \u0434\u0430 \u0437\u0430\u0434\u043E\u0432\u043E\u043B\u0443\u0432\u0430 \u043D\u0430\u0458\u043C\u0430\u043B\u043A\u0443 \u0435\u0434\u043D\u043E \u043E\u0434 \u0441\u043B\u0435\u0434\u043D\u0438\u0442\u0435 \u043E\u0433\u0440\u0430\u043D\u0438\u0447\u0443\u0432\u0430\u045A\u0430:", "validators", "mk");
  t.add("Each element of this collection should satisfy its own set of constraints.", "\u0421\u0435\u043A\u043E\u0458 \u0435\u043B\u0435\u043C\u0435\u043D\u0442 \u043E\u0434 \u043E\u0432\u0430\u0430 \u043A\u043E\u043B\u0435\u043A\u0446\u0438\u0458\u0430 \u0442\u0440\u0435\u0431\u0430 \u0434\u0430 \u0437\u0430\u0434\u043E\u0432\u043E\u043B\u0443\u0432\u0430 \u0441\u043E\u043F\u0441\u0442\u0432\u0435\u043D \u0441\u0435\u0442 \u043D\u0430 \u043E\u0433\u0440\u0430\u043D\u0438\u0447\u0443\u0432\u0430\u045A\u0430.", "validators", "mk");
  t.add("This value is not a valid International Securities Identification Number (ISIN).", "\u041E\u0432\u0430\u0430 \u0432\u0440\u0435\u0434\u043D\u043E\u0441\u0442 \u043D\u0435 \u0435 \u0432\u0430\u0436\u0435\u0447\u043A\u0438 \u043C\u0435\u0453\u0443\u043D\u0430\u0440\u043E\u0434\u0435\u043D \u0438\u0434\u0435\u043D\u0442\u0438\u0444\u0438\u043A\u0430\u0446\u0438\u0441\u043A\u0438 \u0431\u0440\u043E\u0458 \u0437\u0430 \u0445\u0430\u0440\u0442\u0438\u0438 \u043E\u0434 \u0432\u0440\u0435\u0434\u043D\u043E\u0441\u0442 (ISIN).", "validators", "mk");
  t.add("This value should be a valid expression.", "\u041E\u0432\u0430\u0430 \u0432\u0440\u0435\u0434\u043D\u043E\u0441\u0442 \u0442\u0440\u0435\u0431\u0430 \u0434\u0430 \u0431\u0438\u0434\u0435 \u0432\u0430\u043B\u0438\u0434\u0435\u043D \u0438\u0437\u0440\u0430\u0437.", "validators", "mk");
  t.add("This value is not a valid CSS color.", "\u041E\u0432\u0430\u0430 \u0432\u0440\u0435\u0434\u043D\u043E\u0441\u0442 \u043D\u0435 \u0435 \u0432\u0430\u043B\u0438\u0434\u043D\u0430 CSS \u0431\u043E\u0458\u0430.", "validators", "mk");
  t.add("This value is not a valid CIDR notation.", "\u041E\u0432\u0430\u0430 \u0432\u0440\u0435\u0434\u043D\u043E\u0441\u0442 \u043D\u0435 \u0435 \u0432\u0430\u043B\u0438\u0434\u043D\u0430 CIDR \u043E\u0437\u043D\u0430\u043A\u0430.", "validators", "mk");
  t.add("The value of the netmask should be between {{ min }} and {{ max }}.", "\u0412\u0440\u0435\u0434\u043D\u043E\u0441\u0442\u0430 \u043D\u0430 \u043C\u0440\u0435\u0436\u043D\u0430\u0442\u0430 \u043C\u0430\u0441\u043A\u0430 (netmask) \u0442\u0440\u0435\u0431\u0430 \u0434\u0430 \u0431\u0438\u0434\u0435 \u043F\u043E\u043C\u0435\u0453\u0443 {{ min }} \u0438 {{ max }}.", "validators", "mk");
  t.add("The filename is too long. It should have {{ filename_max_length }} character or less.|The filename is too long. It should have {{ filename_max_length }} characters or less.", "\u0418\u043C\u0435\u0442\u043E \u043D\u0430 \u0434\u0430\u0442\u043E\u0442\u0435\u043A\u0430\u0442\u0430 \u0435 \u043F\u0440\u0435\u0434\u043E\u043B\u0433\u043E. \u0422\u0440\u0435\u0431\u0430 \u0434\u0430 \u0438\u043C\u0430 {{ filename_max_length }} \u043A\u0430\u0440\u0430\u043A\u0442\u0435\u0440 \u0438\u043C\u0430 \u043F\u043E\u043C\u0430\u043B\u043A\u0443.|\u0418\u043C\u0435\u0442\u043E \u043D\u0430 \u0434\u0430\u0442\u043E\u0442\u0435\u043A\u0430\u0442\u0430 \u0435 \u043F\u0440\u0435\u0434\u043E\u043B\u0433\u043E. \u0422\u0440\u0435\u0431\u0430 \u0434\u0430 \u0438\u043C\u0430 {{ filename_max_length }} \u043A\u0430\u0440\u0430\u043A\u0442\u0435\u0440\u0438 \u0438\u043B\u0438 \u043F\u043E\u043C\u0430\u043B\u043A\u0443.", "validators", "mk");
  t.add("The password strength is too low. Please use a stronger password.", "\u041E\u0432\u0430\u0430 \u043B\u043E\u0437\u0438\u043D\u043A\u0430 \u0435 \u043F\u0440\u0435\u043C\u043D\u043E\u0433\u0443 \u0435\u0434\u043D\u043E\u0441\u0442\u0430\u0432\u043D\u0430. \u0412\u0435 \u043C\u043E\u043B\u0438\u043C\u0435 \u043A\u043E\u0440\u0438\u0441\u0442\u0435\u0442\u0435 \u043F\u043E\u0441\u0438\u043B\u043D\u0430 \u043B\u043E\u0437\u0438\u043D\u043A\u0430.", "validators", "mk");
  t.add("This value contains characters that are not allowed by the current restriction-level.", "\u041E\u0432\u0430\u0430 \u0432\u0440\u0435\u0434\u043D\u043E\u0441\u0442 \u0441\u043E\u0434\u0440\u0436\u0438 \u043A\u0430\u0440\u0430\u043A\u0442\u0435\u0440\u0438 \u043A\u043E\u0438 \u043D\u0435 \u0441\u0435 \u0434\u043E\u0437\u0432\u043E\u043B\u0435\u043D\u0438 \u043E\u0434 \u0442\u0435\u043A\u043E\u0432\u043D\u043E\u0442\u043E \u043D\u0438\u0432\u043E \u043D\u0430 \u043E\u0433\u0440\u0430\u043D\u0438\u0447\u0443\u0432\u0430\u045A\u0435.", "validators", "mk");
  t.add("Using invisible characters is not allowed.", "\u041A\u043E\u0440\u0438\u0441\u0442\u0435\u045A\u0435\u0442\u043E \u043D\u0430 \u043D\u0435\u0432\u0438\u0434\u043B\u0438\u0432\u0438 \u0437\u043D\u0430\u0446\u0438 \u043D\u0435 \u0435 \u0434\u043E\u0437\u0432\u043E\u043B\u0435\u043D\u043E.", "validators", "mk");
  t.add("Mixing numbers from different scripts is not allowed.", "\u041D\u0435 \u0435 \u0434\u043E\u0437\u0432\u043E\u043B\u0435\u043D\u043E \u043C\u0435\u0448\u0430\u045A\u0435 \u043D\u0430 \u0431\u0440\u043E\u0435\u0432\u0438 \u043E\u0434 \u0440\u0430\u0437\u043B\u0438\u0447\u043D\u0438 \u0441\u043A\u0440\u0438\u043F\u0442\u0438.", "validators", "mk");
  t.add("Using hidden overlay characters is not allowed.", "\u041D\u0435 \u0435 \u0434\u043E\u0437\u0432\u043E\u043B\u0435\u043D\u043E \u043A\u043E\u0440\u0438\u0441\u0442\u0435\u045A\u0435 \u043D\u0430 \u0441\u043A\u0440\u0438\u0435\u043D\u0438 \u0437\u043D\u0430\u0446\u0438 \u0437\u0430 \u043F\u0440\u0435\u043A\u043B\u043E\u043F\u0443\u0432\u0430\u045A\u0435.", "validators", "mk");
  t.add("The extension of the file is invalid ({{ extension }}). Allowed extensions are {{ extensions }}.", "\u0417\u0433\u043E\u043B\u0435\u043C\u0443\u0432\u0430\u045A\u0430 \u043D\u0430 \u0434\u0430\u0442\u043E\u0442\u0435\u043A\u0430\u0442\u0430 \u0435 \u043D\u0435\u0432\u0430\u0436\u0435\u0447\u043A\u0430 ({{ extension }}). \u0414\u043E\u0437\u0432\u043E\u043B\u0435\u043D\u0438 \u0437\u0433\u043E\u043B\u0435\u043C\u0443\u0432\u0430\u045A\u0430 \u0441\u0435 ({{ extensions }}).", "validators", "mk");
  t.add("The detected character encoding is invalid ({{ detected }}). Allowed encodings are {{ encodings }}.", "\u041E\u0442\u043A\u0440\u0438\u0435\u043D\u043E\u0442\u043E \u043A\u043E\u0434\u0438\u0440\u0430\u045A\u0435 \u043D\u0430 \u0437\u043D\u0430\u0446\u0438 \u0435 \u043D\u0435\u0432\u0430\u0436\u0435\u0447\u043A\u043E ({{ detected }}). \u0414\u043E\u0437\u0432\u043E\u043B\u0435\u043D\u0438\u0442\u0435 \u0448\u0438\u0444\u0440\u0438\u0440\u0430\u045A\u0430 \u0441\u0435 {{ encodings }}.", "validators", "mk");
  t.add("This value is not a valid MAC address.", "\u041E\u0432\u0430\u0430 \u0432\u0440\u0435\u0434\u043D\u043E\u0441\u0442 \u043D\u0435 \u0435 \u0432\u0430\u043B\u0438\u0434\u043D\u0430 MAC \u0430\u0434\u0440\u0435\u0441\u0430.", "validators", "mk");
  t.add("This URL is missing a top-level domain.", "\u041D\u0430 \u043E\u0432\u043E\u0458 URL \u043D\u0435\u0434\u043E\u0441\u0442\u0430\u0441\u0443\u0432\u0430 \u0434\u043E\u043C\u0435\u043D \u043E\u0434 \u043D\u0430\u0458\u0432\u0438\u0441\u043E\u043A\u043E \u043D\u0438\u0432\u043E.", "validators", "mk");
