  t.add("This value is not a valid date.", "\u042D\u043D\u044D \u0443\u0442\u0433\u0430 \u0431\u0443\u0440\u0443\u0443 date \u0442\u04E9\u0440\u04E9\u043B \u0431\u0430\u0439\u043D\u0430 .", "validators", "mn");
