  t.add("This value should be either positive or zero.", "\u1024\u1010\u1014\u103A\u1016\u102D\u102F\u1038\u101E\u100A\u103A \u1021\u1015\u1031\u102B\u1004\u103A\u1038 (\u101E\u102D\u102F\u1037\u1019\u101F\u102F\u1010\u103A) \u101E\u102F\u100A \u1016\u103C\u1005\u103A\u101E\u1004\u103A\u1037\u101E\u100A\u103A\u104B", "validators", "my");
  t.add("This value should be negative.", "\u1024\u1010\u1014\u103A\u1016\u102D\u102F\u1038\u101E\u100A\u103A \u1021\u1014\u102F\u1010\u103A \u1016\u103C\u1005\u103A\u101E\u1004\u1037\u103A\u101E\u100A\u103A\u104B", "validators", "my");
  t.add("This value should be either negative or zero.", "\u1024\u1010\u1014\u103A\u1016\u102D\u102F\u1038\u101E\u100A\u103A \u1021\u1014\u102F\u1010\u103A (\u101E\u102D\u102F\u1037\u1019\u101F\u102F\u1010\u103A) \u101E\u102F\u100A \u1016\u103C\u1005\u103A\u101E\u1004\u103A\u1037\u101E\u100A\u103A\u104B", "validators", "my");
  t.add("This value is not a valid timezone.", "\u1024\u1010\u1014\u103A\u1016\u102D\u102F\u1038\u101E\u100A\u103A \u1019\u103E\u1014\u103A\u1000\u1014\u103A\u101E\u1031\u102C \u1021\u1001\u103B\u102D\u1014\u103A\u1007\u102F\u1014\u103A\u1019\u101F\u102F\u1010\u103A\u1015\u102B\u104B", "validators", "my");
  t.add("This password has been leaked in a data breach, it must not be used. Please use another password.", "\u1024\u1005\u1000\u102C\u1038\u101D\u103E\u1000\u103A \u101E\u100A\u103A \u1012\u1031\u1010\u102C\u1015\u1031\u102B\u1000\u103A\u1000\u103C\u102C\u1038\u1019\u103E\u102F\u1010\u1005\u103A\u1001\u102F\u1016\u103C\u1005\u103A\u1001\u1032\u1037\u101E\u100A\u103A\u104B \u1024\u1005\u1000\u102C\u1038\u1040\u103E\u1000\u103A\u1000\u102D\u102F\u1021\u101E\u102F\u1036\u1038\u1019\u1015\u103C\u102F\u101B\u1015\u102B\u104B  \u1000\u103B\u1031\u1038\u1007\u1030\u1038\u1015\u103C\u102F\u104D \u1021\u1001\u103C\u102C\u1038\u1005\u1000\u102C\u1038\u101D\u103E\u1000\u103A\u1000\u102D\u102F\u101E\u102F\u1036\u1038\u1015\u102B\u104B", "validators", "my");
  t.add("This value should be between {{ min }} and {{ max }}.", "\u1024\u1010\u1014\u103A\u1016\u102D\u102F\u1038\u101E\u100A\u103A {{ min }} \u1014\u103E\u1004\u103A\u1037 {{ max }} \u1000\u103C\u102C\u1038\u101B\u103E\u102D\u101E\u1004\u103A\u1037\u101E\u100A\u103A\u104B", "validators", "my");
  t.add("This value is not a valid hostname.", "\u1024\u1010\u1014\u103A\u1016\u102D\u102F\u1038\u101E\u100A\u103A \u101E\u1004\u103A\u1037\u101C\u103B\u103E\u1031\u102C\u103A\u101E\u1031\u102C\u103A hostname \u1019\u101F\u102F\u1010\u103A\u1015\u102B\u104B", "validators", "my");
  t.add("The number of elements in this collection should be a multiple of {{ compared_value }}.", "\u1024 collection \u1010\u103D\u1004\u103A\u1015\u102B\u1015\u102B\u1040\u1004\u103A\u101E\u1031\u102C elements \u1021\u101B\u1031\u1021\u1010\u103D\u1000\u103A\u101E\u100A\u103A {{ compared_value }} \u104F \u1005\u1010\u1030\u1016\u103C\u1005\u103A\u101E\u1004\u103A\u1037\u101E\u100A\u103A\u104B ", "validators", "my");
  t.add("This value should satisfy at least one of the following constraints:", "\u1024\u1010\u1014\u103A\u1016\u102D\u102F\u1038\u101E\u100A\u103A \u1021\u1031\u102C\u1000\u103A\u1015\u102B\u1000\u1014\u1037\u103A\u101E\u1010\u103A\u1001\u103B\u1000\u103A\u1019\u103B\u102C\u1038\u1021\u1014\u1000\u103A\u1019\u103E\u1021\u1014\u100A\u103A\u1038\u1006\u102F\u1036\u1038\u1010\u1005\u103A\u1001\u102F \u1016\u103C\u100A\u103A\u1037\u1006\u100A\u103A\u1038\u1015\u1031\u1038\u101E\u1004\u103A\u1037\u101E\u100A\u103A\u104B", "validators", "my");
  t.add("Each element of this collection should satisfy its own set of constraints.", "\u1024 collection \u104F element \u1010\u1005\u103A\u1001\u102F\u1005\u102E\u101E\u100A\u103A\u104E\u1004\u103A\u1038\u104F\u1000\u102D\u102F\u101A\u103A\u1015\u102D\u102F\u1004\u103A\u1000\u1014\u1037\u103A\u101E\u1010\u103A\u1001\u103B\u1000\u103A\u1019\u103B\u102C\u1038\u1000\u102D\u102F\u1016\u103C\u100A\u1037\u103A\u1006\u100A\u103A\u1038\u101E\u1004\u1037\u103A\u101E\u100A\u103A\u104B", "validators", "my");
  t.add("This value is not a valid International Securities Identification Number (ISIN).", "\u1024\u1010\u1014\u103A\u1016\u102D\u102F\u1038\u101E\u100A\u103A \u101E\u1004\u103A\u1037\u101C\u103B\u103E\u1031\u102C\u103A\u101E\u1031\u102C\u103A \u1021\u1015\u103C\u100A\u103A\u1015\u103C\u100A\u103A\u1006\u102D\u102F\u1004\u103A\u101B\u102C\u1004\u103D\u1031\u1001\u103B\u1031\u1038\u101E\u1000\u103A\u101E\u1031\u1001\u1036\u1014\u1036\u1015\u102B\u1010\u103A ,International Securities Identification Number (ISIN) \u1019\u101F\u102F\u1010\u103A\u1015\u102B\u104B", "validators", "my");
  t.add("This value should be a valid expression.", "\u1024\u1010\u1014\u103A\u1016\u102D\u102F\u1038\u101E\u100A\u103A\u1019\u103E\u1014\u103A\u1000\u1014\u103A\u101E\u1031\u102C\u1005\u1000\u102C\u1038\u101B\u1015\u103A\u1016\u103C\u1005\u103A\u101E\u1004\u1037\u103A\u101E\u100A\u103A\u104B", "validators", "my");
  t.add("This value is not a valid CSS color.", "\u1024\u1010\u1014\u103A\u1016\u102D\u102F\u1038\u101E\u100A\u103A CSS \u1021\u101B\u1031\u102C\u1004\u103A\u1019\u103E\u1014\u103A\u1000\u1014\u103A\u1019\u103E\u102F\u1019\u101B\u103E\u102D\u1015\u102B\u104B", "validators", "my");
  t.add("This value is not a valid CIDR notation.", "\u1024\u1010\u1014\u103A\u1016\u102D\u102F\u1038\u101E\u100A\u103A CIDR \u1019\u103E\u1010\u103A\u1005\u102F\u1036\u1019\u103E\u1014\u103A\u1000\u1014\u103A\u1019\u103E\u102F\u1019\u101B\u103E\u102D\u1015\u102B\u104B", "validators", "my");
  t.add("The value of the netmask should be between {{ min }} and {{ max }}.", "\u1000\u103D\u1014\u103A\u101A\u1000\u103A\u1019\u103B\u1000\u103A\u1014\u103E\u102C\u1016\u102F\u1036\u1038\u104F \u1010\u1014\u103A\u1016\u102D\u102F\u1038\u101E\u100A\u103A {{ min }} \u1014\u103E\u1004\u1037\u103A {{ max }} \u1000\u103C\u102C\u1038\u101B\u103E\u102D\u101B\u1019\u100A\u103A\u104B", "validators", "my");
  t.add("The filename is too long. It should have {{ filename_max_length }} character or less.|The filename is too long. It should have {{ filename_max_length }} characters or less.", "\u1016\u102D\u102F\u1004\u103A\u1014\u102C\u1019\u100A\u103A\u101E\u100A\u103A \u1021\u101B\u103E\u100A\u103A\u101C\u103D\u1014\u103A\u1038\u101E\u100A\u103A\u104B \u101E\u1004\u103A\u1039\u1000\u1031\u1010 {{ filename_max_length }} \u101E\u102D\u102F\u1037\u1019\u101F\u102F\u1010\u103A \u1014\u100A\u103A\u1038\u101E\u100A\u1037\u103A\u1021\u101B\u1031\u1021\u1010\u103D\u1000\u103A\u101B\u103E\u102D\u101B\u1019\u100A\u103A\u104B|\u1016\u102D\u102F\u1004\u103A\u1014\u102C\u1019\u100A\u103A\u101E\u100A\u103A \u1021\u101B\u103E\u100A\u103A\u101C\u103D\u1014\u103A\u1038\u101E\u100A\u103A\u104B \u101E\u1004\u103A\u1039\u1000\u1031\u1010 {{ filename_max_length }} \u101E\u102D\u102F\u1037\u1019\u101F\u102F\u1010\u103A \u1014\u100A\u103A\u1038\u101E\u100A\u1037\u103A\u1021\u101B\u1031\u1021\u1010\u103D\u1000\u103A\u101B\u103E\u102D\u101B\u1019\u100A\u103A\u104B", "validators", "my");
  t.add("The password strength is too low. Please use a stronger password.", "\u1005\u1000\u102C\u1038\u101D\u103E\u1000\u103A\u1001\u102D\u102F\u1004\u103A\u1019\u102C\u1019\u103E\u102F\u1014\u100A\u103A\u1038\u1015\u102B\u1038\u101E\u100A\u103A\u104B \u1015\u102D\u102F\u1001\u102D\u102F\u1004\u103A\u1019\u102C\u101E\u1031\u102C \u1005\u1000\u102C\u1038\u101D\u103E\u1000\u103A\u1000\u102D\u102F \u101E\u102F\u1036\u1038\u1015\u102B\u104B", "validators", "my");
  t.add("This value contains characters that are not allowed by the current restriction-level.", "\u1024\u1010\u1014\u103A\u1016\u102D\u102F\u1038\u1010\u103D\u1004\u103A \u101C\u1000\u103A\u101B\u103E\u102D\u1000\u1014\u1037\u103A\u101E\u1010\u103A\u1019\u103E\u102F\u1021\u1006\u1004\u1037\u103A\u1019\u103E \u1001\u103D\u1004\u1037\u103A\u1019\u1015\u103C\u102F\u1011\u102C\u1038\u101E\u1031\u102C \u1007\u102C\u1010\u103A\u1000\u1031\u102C\u1004\u103A\u1019\u103B\u102C\u1038\u1015\u102B\u101D\u1004\u103A\u101E\u100A\u103A\u104B", "validators", "my");
  t.add("Using invisible characters is not allowed.", "\u1019\u1019\u103C\u1004\u103A\u101B\u101E\u1031\u102C \u1007\u102C\u1010\u103A\u1000\u1031\u102C\u1004\u103A\u1019\u103B\u102C\u1038\u1000\u102D\u102F \u101E\u102F\u1036\u1038\u1001\u103C\u1004\u103A\u1038\u1000\u102D\u102F \u1001\u103D\u1004\u1037\u103A\u1019\u1015\u103C\u102F\u1015\u102B\u104B", "validators", "my");
  t.add("Mixing numbers from different scripts is not allowed.", "\u1019\u1010\u1030\u100A\u102E\u101E\u1031\u102C \u1007\u102C\u1010\u103A\u1000\u1031\u102C\u1004\u103A\u1019\u103B\u102C\u1038\u1019\u103E \u1014\u1036\u1015\u102B\u1010\u103A\u1019\u103B\u102C\u1038\u1000\u102D\u102F \u101B\u1031\u102C\u1014\u103E\u1031\u102C\u1005\u1015\u103A\u1001\u103C\u1004\u103A\u1038\u1000\u102D\u102F \u1001\u103D\u1004\u1037\u103A\u1019\u1015\u103C\u102F\u1015\u102B\u104B", "validators", "my");
  t.add("Using hidden overlay characters is not allowed.", "\u1015\u102F\u1014\u103A\u1038\u1011\u102C\u1038\u101E\u1031\u102C \u1021\u1011\u1015\u103A\u1000\u1031\u102C\u1004\u103A\u1038\u1007\u102C\u1010\u103A\u1000\u1031\u102C\u1004\u103A\u1019\u103B\u102C\u1038\u1000\u102D\u102F \u101E\u102F\u1036\u1038\u1001\u103C\u1004\u103A\u1038\u1000\u102D\u102F \u1001\u103D\u1004\u1037\u103A\u1019\u1015\u103C\u102F\u1015\u102B\u104B", "validators", "my");
  t.add("The extension of the file is invalid ({{ extension }}). Allowed extensions are {{ extensions }}.", "\u1016\u102D\u102F\u1004\u103A\u1010\u103D\u1004\u103A\u1038\u1010\u102D\u102F\u1038\u1001\u103C\u1004\u103A\u1038\u101E\u100A\u103A \u1019\u1019\u103E\u1014\u103A\u1000\u1014\u103A\u1015\u102B ({{ extension }})\u104B \u1001\u103D\u1004\u1037\u103A\u1015\u103C\u102F\u1011\u102C\u1038\u101E\u1031\u102C \u1010\u102D\u102F\u1038\u1001\u103C\u1004\u103A\u1038\u1019\u103B\u102C\u1038\u1019\u103E\u102C {{ extensions }} \u1016\u103C\u1005\u103A\u101E\u100A\u103A\u104B", "validators", "my");
  t.add("The detected character encoding is invalid ({{ detected }}). Allowed encodings are {{ encodings }}.", "\u1010\u103D\u1031\u1037\u101B\u103E\u102D\u1011\u102C\u1038\u101E\u1031\u102C \u1005\u102C\u101C\u102F\u1036\u1038\u1000\u102F\u1012\u103A\u1005\u1036\u1014\u1005\u103A\u101E\u100A\u103A \u1019\u1019\u103E\u1014\u103A\u1000\u1014\u103A\u1015\u102B ({{ detected }})\u104B \u1001\u103D\u1004\u1037\u103A\u1015\u103C\u102F\u1011\u102C\u1038\u101E\u1031\u102C \u1000\u102F\u1012\u103A\u1005\u1036\u1014\u1005\u103A\u1019\u103B\u102C\u1038\u1019\u103E\u102C {{ encodings }} \u1016\u103C\u1005\u103A\u101E\u100A\u103A\u104B", "validators", "my");
  t.add("This value is not a valid MAC address.", "\u1024\u1010\u1014\u103A\u1016\u102D\u102F\u1038\u101E\u100A\u103A \u1019\u103E\u1014\u103A\u1000\u1014\u103A\u101E\u1031\u102C MAC \u101C\u102D\u1015\u103A\u1005\u102C \u1019\u101F\u102F\u1010\u103A\u1015\u102B\u104B", "validators", "my");
  t.add("This URL is missing a top-level domain.", "\u1024 URL \u1010\u103D\u1004\u103A \u1021\u1019\u103C\u1004\u1037\u103A\u1006\u102F\u1036\u1038\u1021\u1006\u1004\u1037\u103A\u1012\u102D\u102F\u1019\u102D\u1014\u103A\u1038 \u1015\u102B\u101D\u1004\u103A\u1019\u101B\u103E\u102D\u1015\u102B\u104B", "validators", "my");
  t.add("This value is too short. It should contain at least one word.|This value is too short. It should contain at least {{ min }} words.", "This value is too short. It should contain at least one word.|This value is too short. It should contain at least {{ min }} words.", "validators", "my");
