  t.add("Each element of this collection should satisfy its own set of constraints.", "Bu gruptaki her \xF6\u011Fe kendi k\u0131s\u0131tlamalar\u0131n\u0131 kar\u015F\u0131lamal\u0131d\u0131r.", "validators", "tr");
  t.add("This value is not a valid International Securities Identification Number (ISIN).", "Bu de\u011Fer ge\xE7erli bir Uluslararas\u0131 Menkul K\u0131ymetler Kimlik Numaras\u0131 (ISIN) de\u011Fildir.", "validators", "tr");
  t.add("This value should be a valid expression.", "Bu de\u011Fer ge\xE7erli bir ifade olmal\u0131d\u0131r.", "validators", "tr");
  t.add("This value is not a valid CSS color.", "Bu de\u011Fer ge\xE7erli bir CSS rengi de\u011Fildir.", "validators", "tr");
  t.add("This value is not a valid CIDR notation.", "Bu de\u011Fer ge\xE7erli bir CIDR yaz\u0131m\u0131 de\u011Fildir.", "validators", "tr");
  t.add("The value of the netmask should be between {{ min }} and {{ max }}.", "Netmask'in de\u011Feri {{ min }} ve {{ max }} aras\u0131nda olmald\u0131r.", "validators", "tr");
  t.add("The filename is too long. It should have {{ filename_max_length }} character or less.|The filename is too long. It should have {{ filename_max_length }} characters or less.", "Dosya ad\u0131 \xE7ok uzun. {{ filename_max_length }} karakter veya daha az olmal\u0131d\u0131r.", "validators", "tr");
  t.add("The password strength is too low. Please use a stronger password.", "\u015Eifre g\xFCc\xFC \xE7ok d\xFC\u015F\xFCk. L\xFCtfen daha g\xFC\xE7l\xFC bir \u015Fifre kullan\u0131n.", "validators", "tr");
  t.add("This value contains characters that are not allowed by the current restriction-level.", "Bu de\u011Fer, mevcut k\u0131s\u0131tlama seviyesi taraf\u0131ndan izin verilmeyen karakterler i\xE7eriyor.", "validators", "tr");
  t.add("Using invisible characters is not allowed.", "G\xF6r\xFCnmez karakterlerin kullan\u0131lmas\u0131 izin verilmez.", "validators", "tr");
  t.add("Mixing numbers from different scripts is not allowed.", "Farkl\u0131 yaz\u0131 t\xFCrlerinden say\u0131lar\u0131n kar\u0131\u015Ft\u0131r\u0131lmas\u0131 izin verilmez.", "validators", "tr");
  t.add("Using hidden overlay characters is not allowed.", "Gizli \xFCst\xFC kaplama karakterlerinin kullan\u0131lmas\u0131 izin verilmez.", "validators", "tr");
  t.add("The extension of the file is invalid ({{ extension }}). Allowed extensions are {{ extensions }}.", "Dosya uzant\u0131s\u0131 ge\xE7ersiz ({{ extension }}). \u0130zin verilen uzant\u0131lar {{ extensions }}.", "validators", "tr");
  t.add("The detected character encoding is invalid ({{ detected }}). Allowed encodings are {{ encodings }}.", "Tespit edilen karakter kodlamas\u0131 ge\xE7ersiz ({{ detected }}). \u0130zin verilen kodlamalar: {{ encodings }}.", "validators", "tr");
  t.add("This value is not a valid MAC address.", "Bu de\u011Fer ge\xE7erli bir MAC adresi de\u011Fildir.", "validators", "tr");
  t.add("This URL is missing a top-level domain.", "Bu URL bir \xFCst seviye alan ad\u0131 eksik.", "validators", "tr");
  t.add("This value is too short. It should contain at least one word.|This value is too short. It should contain at least {{ min }} words.", "Bu de\u011Fer \xE7ok k\u0131sa. En az bir kelime i\xE7ermelidir.|Bu de\u011Fer \xE7ok k\u0131sa. En az {{ min }} kelime i\xE7ermelidir.", "validators", "tr");
  t.add("This value is too long. It should contain one word.|This value is too long. It should contain {{ max }} words or less.", "Bu de\u011Fer \xE7ok uzun. Tek bir kelime i\xE7ermelidir.|Bu de\u011Fer \xE7ok uzun. {{ max }} veya daha az kelime i\xE7ermelidir.", "validators", "tr");
  t.add("This value does not represent a valid week in the ISO 8601 format.", "Bu de\u011Fer ISO 8601 format\u0131nda ge\xE7erli bir haftay\u0131 temsil etmezdir.", "validators", "tr");
  t.add("This value is not a valid week.", "Bu de\u011Fer ge\xE7erli hafta de\u011Fildir.", "validators", "tr");
  t.add("This value should not be before week \"{{ min }}\".", "Bu de\u011Fer \u201C{{ min }}\u201D haftas\u0131ndan \xF6nce olmamal\u0131d\u0131r.", "validators", "tr");
  t.add("This value should not be after week \"{{ max }}\".", "Bu de\u011Fer \u201C{{ max }}\u201D haftas\u0131ndan sonra olmamal\u0131d\u0131r", "validators", "tr");
  t.add("This form should not contain extra fields.", "Form ekstra alanlar i\xE7eremez.", "validators", "tr");
  t.add("The uploaded file was too large. Please try to upload a smaller file.", "Y\xFCklenen dosya boyutu \xE7ok y\xFCksek. L\xFCtfen daha k\xFC\xE7\xFCk bir dosya y\xFCklemeyi deneyin.", "validators", "tr");
  t.add("The CSRF token is invalid. Please try to resubmit the form.", "CSRF fi\u015Fi ge\xE7ersiz. Formu tekrar g\xF6ndermeyi deneyin.", "validators", "tr");
