  t.add("This value should be false.", "\u06CC\u06C1 \u0648\u064A\u0644\u064A\u0648 \u063A\u0644\u0637 \u06C1\u0648\u0646\u06CC \u0686\u0627\u06C1\u06CC\u06D2", "validators", "ur");
  t.add("This value should be true.", "\u06CC\u06C1 \u0648\u064A\u0644\u064A\u0648 \u062F\u0631\u0633\u062A \u06C1\u0648\u0646\u06CC \u0686\u0627\u06C1\u06CC\u06D2", "validators", "ur");
  t.add("This value should be of type {{ type }}.", "\u0642\u0633\u0645 \u06A9\u06CC \u06C1\u0648\u0646\u06CC \u0686\u0627\u06C1\u06CC\u06D2 {{type}} \u064A\u06BE \u0648\u064A\u0644\u064A\u0648", "validators", "ur");
  t.add("This value should be blank.", "\u06CC\u06C1 \u0648\u064A\u0644\u064A\u0648 \u062E\u0627\u0644\u06CC \u06C1\u0648\u0646\u06CC \u0686\u0627\u06C1\u06CC\u06D2", "validators", "ur");
  t.add("The value you selected is not a valid choice.", "\u0622\u067E \u0646\u06D2 \u062C\u0648 \u0648\u064A\u0644\u064A\u0648 \u0645\u0646\u062A\u062E\u0628 \u06A9\u06CC \u06C1\u06D2 \u0648\u06C1 \u062F\u0631\u0633\u062A \u0627\u0646\u062A\u062E\u0627\u0628 \u0646\u06C1\u06CC\u06BA \u06C1\u06D2", "validators", "ur");
  t.add("You must select at least {{ limit }} choice.|You must select at least {{ limit }} choices.", "\u06A9\u0627 \u0627\u0646\u062A\u062E\u0627\u0628 \u06A9\u0631\u0646\u0627 \u0686\u0627\u06C1\u06CC\u06D2 {{limit}} \u06A9\u0627 \u0627\u0646\u062A\u062E\u0627\u0628 \u06A9\u0631\u0646\u0627 \u0686\u0627\u06C1\u06CC\u06D2 \u06D4\u0622\u0651\u067E \u06A9\u0648 \u06A9\u0645 \u0627\u0630 \u06A9\u0645 {{limit}} \u0622\u067E \u06A9\u0648 \u06A9\u0645 \u0627\u0632 \u06A9\u0645", "validators", "ur");
