  t.add("One or more of the given values is invalid.", "\u062F\u06CC \u06AF\u0626\u06CC \u0648\u064A\u0644\u064A\u0648\u0630 \u0645\u06CC\u06BA \u0633\u06D2 \u0627\u06CC\u06A9 \u06CC\u0627 \u0632\u06CC\u0627\u062F\u06BE \u0648\u064A\u0644\u064A\u0648\u0630 \u063A\u0644\u0637 \u06C1\u06CC\u06BA", "validators", "ur");
