  t.add("This field is missing.", "\u06CC\u06C1 \u0641\u06CC\u0644\u0688 \u063A\u0627\u0626\u0628 \u06C1\u06D2", "validators", "ur");
  t.add("This value is not a valid date.", "\u06CC\u06C1 \u0648\u064A\u0644\u064A\u0648 \u062F\u0631\u0633\u062A \u062A\u0627\u0631\u06CC\u062E \u0646\u06C1\u06CC\u06BA \u06C1\u06D2", "validators", "ur");
  t.add("This value is not a valid datetime.", "\u06CC\u06C1 \u0648\u064A\u0644\u064A\u0648 \u062F\u0631\u0633\u062A \u062A\u0627\u0631\u06CC\u062E \u0648\u0642\u062A \u0646\u06C1\u06CC\u06BA \u06C1\u06D2", "validators", "ur");
  t.add("This value is not a valid email address.", "\u06CC\u06C1 \u0648\u064A\u0644\u064A\u0648 \u062F\u0631\u0633\u062A \u0627\u06CC \u0645\u06CC\u0644 \u0627\u06CC\u0688\u0631\u06CC\u0633 \u0646\u06C1\u06CC\u06BA \u06C1\u06D2", "validators", "ur");
  t.add("The file could not be found.", "\u0641\u0627\u0626\u0644 \u0646\u06C1\u06CC\u06BA \u0645\u0644 \u0633\u06A9\u06CC", "validators", "ur");
