  t.add("The file is too large ({{ size }} {{ suffix }}). Allowed maximum size is {{ limit }} {{ suffix }}.", "{{ suffix }} {{ limit }} \u0632\u06CC\u0627\u062F\u06C1 \u0633\u06D2 \u0632\u06CC\u0627\u062F\u06C1 \u0633\u0627\u0626\u0632 \u06A9\u06CC \u0627\u062C\u0627\u0632\u062A \u06C1\u06D2 {{ suffix }}) ({{ size }} \u0641\u0627\u0626\u0644 \u0628\u06C1\u062A \u0628\u0691\u06CC \u06C1\u06D2", "validators", "ur");
