  t.add("This value should be {{ limit }} or less.", "\u06CC\u0627 \u0627\u0633 \u0633\u06D2 \u06A9\u0645 \u06C1\u0648\u0646\u06CC \u0686\u0627\u06C1\u06CC\u06D2 {{ limit }} \u06CC\u06C1 \u0648\u064A\u0644\u064A\u0648", "validators", "ur");
  t.add("This value is too long. It should have {{ limit }} character or less.|This value is too long. It should have {{ limit }} characters or less.", "\u062D\u0631\u0648\u0641 \u06CC\u0627 \u0627\u0633 \u0633\u06D2 \u06A9\u0645 \u06C1\u0648\u0646\u06D2 \u0686\u0627\u06C1\u0626\u06CC\u06BA {{ limit }} \u062D\u0631\u0641 \u06CC\u0627 \u0627\u0633 \u0633\u06D2 \u06A9\u0645 \u06C1\u0648\u0646\u0627 \u0686\u0627\u06C1\u06CC\u06D2\u06D4|\u06CC\u06C1 \u0648\u064A\u0644\u064A\u0648 \u0628\u06C1\u062A \u0644\u0645\u0628\u06CC \u06C1\u06D2\u06D4 \u0627\u0633 \u0645\u06CC\u06BA{{ limit }} \u06CC\u06C1 \u0648\u064A\u0644\u064A\u0648 \u0628\u06C1\u062A \u0644\u0645\u0628\u06CC \u06C1\u06D2\u06D4 \u0627\u0633 \u0645\u06CC\u06BA", "validators", "ur");
  t.add("This value should be {{ limit }} or more.", "\u06CC\u0627 \u0627\u0633 \u0633\u06D2 \u0632\u06CC\u0627\u062F\u06C1 \u06C1\u0648\u0646\u06CC \u0686\u0627\u06C1\u06CC\u06D2 {{ limit }} \u06CC\u06C1 \u0648\u064A\u0644\u064A\u0648", "validators", "ur");
