  t.add("This value should not be null.", "\u06CC\u06C1 \u0648\u064A\u0644\u064A\u0648 \u062E\u0627\u0644\u06CC \u0646\u06C1\u06CC\u06BA \u06C1\u0648\u0646\u06CC \u0686\u0627\u06C1\u06CC\u06D2", "validators", "ur");
  t.add("This value should be null.", "\u06CC\u06C1 \u0648\u064A\u0644\u064A\u0648 \u062E\u0627\u0644\u06CC \u06C1\u0648\u0646\u06CC \u0686\u0627\u06C1\u06CC\u06D2", "validators", "ur");
