  t.add("This is not a valid IP address.", "\u06CC\u06C1 \u0642\u06CC\u0645\u062A \u06A9\u0648\u0626\u06CC \u062F\u0631\u0633\u062A IP \u067E\u062A\u06C1 \u0646\u06C1\u06CC\u06BA \u06C1\u06D2\u06D4", "validators", "ur");
