  t.add("This value is not a valid locale.", "\u06CC\u06C1 \u0648\u064A\u0644\u064A\u0648 \u062F\u0631\u0633\u062A \u0645\u0642\u0627\u0645 \u0646\u06C1\u06CC\u06BA \u06C1\u06D2", "validators", "ur");
