  t.add("The size of the image could not be detected.", "\u062A\u0635\u0648\u06CC\u0631 \u06A9\u06D2 \u0633\u0627\u0626\u0632 \u06A9\u0627 \u067E\u062A\u06C1 \u0646\u06C1\u06CC\u06BA \u0686\u0644 \u0633\u06A9\u0627", "validators", "ur");
