  t.add("The image height is too big ({{ height }}px). Allowed maximum height is {{ max_height }}px.", "\u06C1\u06D2 {{ max_height }}px \u0627\u062C\u0627\u0632\u062A \u062F\u06CC \u06AF\u0626\u06CC \u0632\u06CC\u0627\u062F\u06C1 \u0633\u06D2 \u0632\u06CC\u0627\u062F \u0627\u0648\u0646\u0686\u0627\u0626\u06CC ({{ height }}px) \u062A\u0635\u0648\u06CC\u0631 \u06A9\u06CC \u0627\u0648\u0646\u0686\u0627\u0626\u06CC \u0628\u06C1\u062A \u0628\u0691\u06CC \u06C1\u06D2", "validators", "ur");
  t.add("The image height is too small ({{ height }}px). Minimum height expected is {{ min_height }}px.", "\u06C1\u06D2 {{ min_height }}px  \u0645\u062A\u0648\u0642\u0639 \u06A9\u0645 \u0627\u0632 \u06A9\u0645 \u0627\u0648\u0646\u0686\u0627\u0626\u06CC ({{ height }}px) \u062A\u0635\u0648\u06CC\u0631 \u06A9\u06CC \u0627\u0648\u0646\u0686\u0627\u0626\u06CC \u0628\u06C1\u062A \u0686\u06BE\u0648\u0679\u06CC \u06C1\u06D2", "validators", "ur");
  t.add("This value should be the user's current password.", "\u06CC\u06C1 \u0648\u064A\u0644\u064A\u0648 \u0635\u0627\u0631\u0641 \u06A9\u0627 \u0645\u0648\u062C\u0648\u062F\u06C1 \u067E\u0627\u0633 \u0648\u0631\u0688 \u06C1\u0648\u0646\u0627 \u0686\u0627\u06C1\u06CC\u06D2", "validators", "ur");
  t.add("This value should have exactly {{ limit }} character.|This value should have exactly {{ limit }} characters.", "\u062D\u0631\u0648\u0641 \u06C1\u0648\u0646\u06D2 \u0686\u0627\u06C1\u0626\u06CC\u06BA {{ limit }} \u062D\u0631\u0641 \u06C1\u0648\u0646\u0627 \u0686\u0627\u06C1\u06CC\u06D2\u06D4|\u0627\u0633 \u0648\u064A\u0644\u064A\u0648 \u0645\u06CC\u06BA \u0628\u0627\u0644\u06A9\u0644 {{ limit }} \u0627\u0633 \u0648\u064A\u0644\u064A\u0648 \u0645\u06CC\u06BA \u0628\u0627\u0644\u06A9\u0644", "validators", "ur");
