  t.add("No file was uploaded.", "\u06A9\u0648\u0626\u06CC \u0641\u0627\u0626\u0644 \u0627\u067E \u0644\u0648\u0688 \u0646\u06C1\u06CC\u06BA \u06A9\u06CC \u06AF\u0626\u06CC", "validators", "ur");
  t.add("No temporary folder was configured in php.ini.", "php.ini \u0645\u06CC\u06BA \u06A9\u0648\u0626\u06CC \u0639\u0627\u0631\u0636\u06CC \u0641\u0648\u0644\u0688\u0631 \u062A\u0631\u062A\u06CC\u0628 \u0646\u06C1\u06CC\u06BA \u062F\u06CC\u0627 \u06AF\u06CC\u0627 \u062A\u06BE\u0627\u060C \u06CC\u0627 \u062A\u0631\u062A\u06CC\u0628 \u062F\u06CC\u0627 \u06AF\u06CC\u0627 \u0641\u0648\u0644\u0688\u0631 \u0645\u0648\u062C\u0648\u062F \u0646\u06C1\u06CC\u06BA \u06C1\u06D2\u06D4", "validators", "ur");
