  t.add("A PHP extension caused the upload to fail.", "\u067E\u06CC \u0627\u06CC\u0686 \u067E\u06CC \u06A9\u06CC \u062A\u0648\u0633\u06CC\u0639 \u06A9\u06CC \u0648\u062C\u06C1 \u0633\u06D2 \u0627\u067E \u0644\u0648\u0688 \u0646\u0627\u06A9\u0627\u0645 \u06C1\u0648 \u06AF\u06CC\u0627", "validators", "ur");
  t.add("This collection should contain {{ limit }} element or more.|This collection should contain {{ limit }} elements or more.", "\u0639\u0646\u0627\u0635\u0631 \u06CC\u0627 \u0627\u0633 \u0633\u06D2 \u0632\u06CC\u0627\u062F\u06C1 \u06C1\u0648\u0646\u0627 \u0686\u0627\u06C1\u06CC\u06D2 {{ limit }  \u0639\u0646\u0635\u0631 \u06CC\u0627 \u0627\u0633 \u0633\u06D2 \u0632\u06CC\u0627\u062F\u06C1 \u06C1\u0648\u0646\u0627 \u0686\u0627\u06C1\u06CC\u06D2\u06D4|\u0627\u0633 \u0645\u062C\u0645\u0648\u0639\u06C1 \u0645\u06CC\u06BA {{ limit }} \u0627\u0633 \u0645\u062C\u0645\u0648\u0639\u06C1 \u0645\u06CC\u06BA", "validators", "ur");
  t.add("This collection should contain {{ limit }} element or less.|This collection should contain {{ limit }} elements or less.", "\u0639\u0646\u0627\u0635\u0631 \u06CC\u0627 \u0627\u0633 \u0633\u06D2 \u06A9\u0645 \u06C1\u0648\u0646\u0627 \u0686\u0627\u06C1\u06CC\u06D2 {{ limit } \u0639\u0646\u0635\u0631 \u06CC\u0627 \u0627\u0633 \u0633\u06D2 \u06A9\u0645 \u06C1\u0648\u0646\u0627 \u0686\u0627\u06C1\u06CC\u06D2\u06D4|\u0627\u0633 \u0645\u062C\u0645\u0648\u0639\u06C1 \u0645\u06CC\u06BA {{ limit }} \u0627\u0633 \u0645\u062C\u0645\u0648\u0639\u06C1 \u0645\u06CC\u06BA", "validators", "ur");
  t.add("This collection should contain exactly {{ limit }} element.|This collection should contain exactly {{ limit }} elements.", "\u0639\u0646\u0635\u0631 \u06C1\u0648\u0646\u0627 \u0686\u0627\u06C1\u06CC\u06D2 {{ limit }}  \u0639\u0646\u0635\u0631 \u06C1\u0648\u0646\u0627 \u0686\u0627\u06C1\u06CC\u06D2\u06D4|\u0627\u0633 \u0645\u062C\u0645\u0648\u0639\u06D2 \u0645\u06CC\u06BA \u0628\u0627\u0644\u06A9\u0644 {{ limit }} \u0627\u0633 \u0645\u062C\u0645\u0648\u0639\u06C1 \u0645\u06CC\u06BA \u0628\u0627\u0644\u06A9\u0644", "validators", "ur");
  t.add("Invalid card number.", "\u063A\u0644\u0637 \u06A9\u0627\u0631\u0688 \u0646\u0645\u0628\u0631", "validators", "ur");
  t.add("Unsupported card type or invalid card number.", "\u063A\u06CC\u0631 \u062A\u0639\u0627\u0648\u0646 \u06CC\u0627\u0641\u062A\u06C1 \u06A9\u0627\u0631\u0688 \u06A9\u06CC \u0642\u0633\u0645 \u06CC\u0627 \u063A\u0644\u0637 \u06A9\u0627\u0631\u0688 \u0646\u0645\u0628\u0631", "validators", "ur");
  t.add("This is not a valid International Bank Account Number (IBAN).", "\u06CC\u06C1 \u0642\u06CC\u0645\u062A \u06A9\u0648\u0626\u06CC \u062F\u0631\u0633\u062A \u0628\u06CC\u0646 \u0627\u0644\u0627\u0642\u0648\u0627\u0645\u06CC \u0628\u06CC\u0646\u06A9 \u0627\u06A9\u0627\u0624\u0646\u0679 \u0646\u0645\u0628\u0631 (IBAN) \u0646\u06C1\u06CC\u06BA \u06C1\u06D2\u06D4", "validators", "ur");
  t.add("This value is not a valid ISBN-10.", "\u0646\u06C1\u06CC\u06BA \u06C1\u06D2 ISBN-10 \u06CC\u06BE \u0648\u064A\u0644\u064A\u0648 \u062F\u0631\u0633\u062A\u06D4", "validators", "ur");
  t.add("This value is not a valid ISBN-13.", "\u0646\u06C1\u06CC\u06BA \u06C1\u06D2 ISBN-13 \u06CC\u06BE \u0648\u064A\u0644\u064A\u0648 \u062F\u0631\u0633\u062A\u06D4", "validators", "ur");
  t.add("This value is neither a valid ISBN-10 nor a valid ISBN-13.", "ISBN-13 \u06D2 \u0627\u0648\u0631 \u0646\u06C1 \u06C1\u06CC \u062F\u0631\u0633\u062A ISBN-10 \u06CC\u06C1 \u0648\u064A\u0644\u064A\u0648 \u0646\u06C1 \u062A\u0648 \u062F\u0631\u0633\u062A", "validators", "ur");
  t.add("This value is not a valid ISSN.", "\u0646\u06C1\u06CC\u06BA \u06C1\u06D2 ISSN\u06CC\u06BE \u0648\u064A\u0644\u064A\u0648 \u062F\u0631\u0633\u062A\u06D4", "validators", "ur");
  t.add("This value is not a valid currency.", "\u06CC\u06C1 \u0648\u064A\u0644\u064A\u0648 \u062F\u0631\u0633\u062A \u06A9\u0631\u0646\u0633\u06CC \u0646\u06C1\u06CC\u06BA \u06C1\u06D2", "validators", "ur");
  t.add("This value should be equal to {{ compared_value }}.", "\u06A9\u06D2 \u0628\u0631\u0627\u0628\u0631 \u06C1\u0648\u0646\u0627 \u0686\u0627\u06C1\u06CC\u06D2 {{ compared_value }} \u06CC\u06BE \u0648\u064A\u0644\u064A\u0648", "validators", "ur");
  t.add("This value should be greater than {{ compared_value }}.", "\u0633\u06D2 \u0628\u0688\u064A \u06C1\u0648\u0646\u064A \u0686\u0627\u06C1\u06CC\u06D2 {{ compared_value }} \u06CC\u06BE \u0648\u064A\u0644\u064A\u0648", "validators", "ur");
  t.add("This value should be greater than or equal to {{ compared_value }}.", "\u0633\u06D2 \u0628\u0688\u064A \u06CC\u0627 \u0628\u0631\u0627\u0628\u0631 \u06C1\u0648\u0646\u064A \u0686\u0627\u06C1\u06CC\u06D2 {{ compared_value }} \u06CC\u06BE \u0648\u064A\u0644\u064A\u0648", "validators", "ur");
  t.add("This value should be identical to {{ compared_value_type }} {{ compared_value }}.", "{{ compared_value }} {{ compared_value_type }} \u06CC\u06C1 \u0648\u064A\u0644\u064A\u0648 \u0627\u06CC\u06A9 \u062C\u06CC\u0633\u06CC \u06C1\u0648\u0646\u06CC \u0686\u0627\u06C1\u06CC\u06D2\u06D4", "validators", "ur");
  t.add("This value should be less than {{ compared_value }}.", "\u0633\u06D2 \u06A9\u0645 \u06C1\u0648\u0646\u064A \u0686\u0627\u06C1\u06CC\u06D2 {{ compared_value }} \u06CC\u06BE \u0648\u064A\u0644\u064A\u0648", "validators", "ur");
  t.add("This value should be less than or equal to {{ compared_value }}.", "\u0633\u06D2 \u06A9\u0645 \u06CC\u0627 \u0628\u0631\u0627\u0628\u0631 \u06C1\u0648\u0646\u064A \u0686\u0627\u06C1\u06CC\u06D2 {{ compared_value }} \u06CC\u06BE \u0648\u064A\u0644\u064A\u0648", "validators", "ur");
  t.add("This value should not be equal to {{ compared_value }}.", "\u06A9\u06D2 \u0628\u0631\u0627\u0628\u0631 \u0646\u06BE\u064A\u06BA \u06C1\u0648\u0646\u064A \u0686\u0627\u06C1\u06CC\u06D2 {{ compared_value }} \u06CC\u06BE \u0648\u064A\u0644\u064A\u0648", "validators", "ur");
  t.add("This value should not be identical to {{ compared_value_type }} {{ compared_value }}.", "\u0627\u06CC\u06A9 \u062C\u06CC\u0633\u06CC \u0646\u06CC\u064A\u06BA \u06C1\u0648\u0646\u06CC \u0686\u0627\u06C1\u06CC\u06D2 {{ compared_value }} {{ compared_value_type }} \u06CC\u06C1 \u0648\u064A\u0644\u064A\u0648", "validators", "ur");
  t.add("The image ratio is too big ({{ ratio }}). Allowed maximum ratio is {{ max_ratio }}.", "\u06C1\u06D2 {{ max_ratio }} \u0627\u062C\u0627\u0632\u062A \u0634\u062F\u06C1 \u0632\u06CC\u0627\u062F\u06C1 \u0633\u06D2 \u0632\u06CC\u0627\u062F\u06C1 \u062A\u0646\u0627\u0633\u0628 ({{ ratio }}) \u062A\u0635\u0648\u06CC\u0631 \u06A9\u0627 \u062A\u0646\u0627\u0633\u0628 \u0628\u06C1\u062A \u0628\u0691\u0627 \u06C1\u06D2", "validators", "ur");
  t.add("The image ratio is too small ({{ ratio }}). Minimum ratio expected is {{ min_ratio }}.", "\u06C1\u06D2{{ min_ratio }} ratio \u0645\u062A\u0648\u0642\u0639 \u06A9\u0645 \u0627\u0632 \u06A9\u0645 ({{ ratio }}) \u0628\u06C1\u062A \u0686\u06BE\u0648\u0679\u0627 \u06C1\u06D2 ratio \u062A\u0635\u0648\u06CC\u0631 \u06A9\u0627", "validators", "ur");
  t.add("The image is square ({{ width }}x{{ height }}px). Square images are not allowed.", "\u0645\u0631\u0628\u0639 \u062A\u0635\u0627\u0648\u06CC\u0631 \u06A9\u06CC \u0627\u062C\u0627\u0632\u062A \u0646\u06C1\u06CC\u06BA \u06C1\u06D2 (px{{ height }}x{{ width }})  \u062A\u0635\u0648\u06CC\u0631 \u0645\u0631\u0628\u0639 \u06C1\u06D2", "validators", "ur");
  t.add("The image is landscape oriented ({{ width }}x{{ height }}px). Landscape oriented images are not allowed.", "\u0632\u0645\u06CC\u0646 \u06A9\u06CC \u062A\u0632\u0626\u06CC\u0646 \u067E\u0631 \u0645\u0628\u0646\u06CC \u062A\u0635\u0627\u0648\u06CC\u0631 \u06A9\u06CC \u0627\u062C\u0627\u0632\u062A \u0646\u06C1\u06CC\u06BA \u06C1\u06D2 ({{ width }}x{{ height }}px) \u062A\u0635\u0648\u06CC\u0631 \u0632\u0645\u06CC\u0646 \u06A9\u06CC \u062A\u0632\u0626\u06CC\u0646 \u067E\u0631 \u0645\u0628\u0646\u06CC \u06C1\u06D2", "validators", "ur");
  t.add("The image is portrait oriented ({{ width }}x{{ height }}px). Portrait oriented images are not allowed.", "\u067E\u0648\u0631\u0679\u0631\u06CC\u0679 \u067E\u0631 \u0645\u0628\u0646\u06CC \u062A\u0635\u0627\u0648\u06CC\u0631 \u06A9\u06CC \u0627\u062C\u0627\u0632\u062A \u0646\u06C1\u06CC\u06BA \u06C1\u06D2 ({{ width }}x{{ height }}px) \u062A\u0635\u0648\u06CC\u0631 \u067E\u0648\u0631\u0679\u0631\u06CC\u0679 \u067E\u0631 \u0645\u0628\u0646\u06CC \u06C1\u06D2", "validators", "ur");
  t.add("An empty file is not allowed.", "\u062E\u0627\u0644\u06CC \u0641\u0627\u0626\u0644 \u06A9\u06CC \u0627\u062C\u0627\u0632\u062A \u0646\u06C1\u06CC\u06BA \u06C1\u06D2", "validators", "ur");
  t.add("The host could not be resolved.", "\u0645\u06CC\u0632\u0628\u0627\u0646 \u062D\u0644 \u0646\u06C1\u06CC\u06BA \u06C1\u0648 \u0633\u06A9\u0627", "validators", "ur");
  t.add("This value does not match the expected {{ charset }} charset.", "\u06A9\u06D2 \u062C\u064A\u0633\u064A \u0646\u06C1\u06CC\u06BA \u06C1\u06D2 charset {{ charset }} \u06CC\u06C1 \u0648\u064A\u0644\u064A\u0648 \u0645\u062A\u0648\u0642\u0639", "validators", "ur");
  t.add("This is not a valid Business Identifier Code (BIC).", "\u06CC\u06C1 \u0642\u06CC\u0645\u062A \u06A9\u0648\u0626\u06CC \u062F\u0631\u0633\u062A \u0628\u0632\u0646\u0633 \u0634\u0646\u0627\u062E\u062A\u06CC \u06A9\u0648\u0688 (BIC) \u0646\u06C1\u06CC\u06BA \u06C1\u06D2\u06D4", "validators", "ur");
  t.add("Error", "\u062E\u0631\u0627\u0628\u06CC", "validators", "ur");
  t.add("This is not a valid UUID.", "\u06CC\u06C1 \u0642\u06CC\u0645\u062A \u06A9\u0648\u0626\u06CC \u062F\u0631\u0633\u062A UUID \u0646\u06C1\u06CC\u06BA \u06C1\u06D2\u06D4", "validators", "ur");
  t.add("This value should be a multiple of {{ compared_value }}.", "\u06A9\u0627 \u0636\u0631\u0628 \u06C1\u0648\u0646\u064A \u0686\u0627\u06C1\u06CC\u06D2 {{ compared_value }} \u06CC\u06C1 \u0648\u064A\u0644\u064A\u0648 ", "validators", "ur");
  t.add("This Business Identifier Code (BIC) is not associated with IBAN {{ iban }}.", "\u0633\u06D2 \u0648\u0627\u0628\u0633\u062A\u06C1 \u0646\u06C1\u06CC\u06BA \u06C1\u06D2 IBAN {{ iban }} (BIC) \u06CC\u06C1 \u06A9\u0627\u0631\u0648\u0628\u0627\u0631\u06CC \u0634\u0646\u0627\u062E\u062A\u06CC \u06A9\u0648\u0688", "validators", "ur");
  t.add("This value should be valid JSON.", "\u06C1\u0648\u0646\u06CC \u0686\u0627\u06C1\u06CC\u06D2 JSON \u06CC\u06C1 \u0648\u064A\u0644\u064A\u0648 \u062F\u0631\u0633\u062A", "validators", "ur");
  t.add("This collection should contain only unique elements.", "\u06CC\u06C1 \u0645\u062C\u0645\u0648\u0639\u06C1 \u0635\u0631\u0641 \u0645\u0646\u0641\u0631\u062F \u0639\u0646\u0627\u0635\u0631 \u067E\u0631 \u0645\u0634\u062A\u0645\u0644 \u06C1\u0648\u0646\u0627 \u0686\u0627\u06C1\u06CC\u06D2", "validators", "ur");
  t.add("This value should be positive.", "\u06CC\u06C1 \u0648\u064A\u0644\u064A\u0648 \u0645\u062B\u0628\u062A \u06C1\u0648\u0646\u06CC \u0686\u0627\u06C1\u06CC\u06D2", "validators", "ur");
  t.add("This value should be either positive or zero.", "\u06CC\u06C1 \u0648\u064A\u0644\u064A\u0648 \u06CC\u0627 \u062A\u0648 \u0645\u062B\u0628\u062A \u06CC\u0627 \u0635\u0641\u0631 \u06C1\u0648\u0646\u06CC \u0686\u0627\u06C1\u06CC\u06D2", "validators", "ur");
  t.add("This value should be negative.", "\u06CC\u06C1 \u0648\u064A\u0644\u064A\u0648 \u0645\u0646\u0641\u06CC \u06C1\u0648\u0646\u06CC \u0686\u0627\u06C1\u06CC\u06D2", "validators", "ur");
  t.add("This value should be either negative or zero.", "\u06CC\u06C1 \u0648\u064A\u0644\u064A\u0648 \u06CC\u0627 \u062A\u0648 \u0645\u0646\u0641\u06CC \u06CC\u0627 \u0635\u0641\u0631 \u06C1\u0648\u0646\u06CC \u0686\u0627\u06C1\u06CC\u06D2", "validators", "ur");
  t.add("This value is not a valid timezone.", "\u06CC\u06C1 \u0648\u064A\u0644\u064A\u0648 \u062F\u0631\u0633\u062A \u0679\u0627\u0626\u0645 \u0632\u0648\u0646 \u0646\u06C1\u06CC\u06BA \u06C1\u06D2", "validators", "ur");
  t.add("This password has been leaked in a data breach, it must not be used. Please use another password.", "\u06CC\u06C1 \u067E\u0627\u0633 \u0648\u0631\u0688 \u0688\u06CC\u0679\u0627 \u06A9\u06CC \u062E\u0644\u0627\u0641 \u0648\u0631\u0632\u06CC \u0645\u06CC\u06BA \u0644\u06CC\u06A9 \u06C1\u0648 \u06AF\u06CC\u0627 \u06C1\u06D2\u060C \u0627\u0633\u06D2 \u0627\u0633\u062A\u0639\u0645\u0627\u0644 \u0646\u06C1\u06CC\u06BA \u06A9\u0631\u0646\u0627 \u0686\u0627\u06C1\u06CC\u06D2\u06D4 \u0628\u0631\u0627\u06D3 \u06A9\u0631\u0645 \u062F\u0648\u0633\u0631\u0627 \u067E\u0627\u0633 \u0648\u0631\u0688 \u0627\u0633\u062A\u0639\u0645\u0627\u0644 \u06A9\u0631\u06CC\u06BA", "validators", "ur");
  t.add("This value should be between {{ min }} and {{ max }}.", "\u06A9\u06D2 \u062F\u0631\u0645\u06CC\u0627\u0646 \u06C1\u0648\u0646\u06CC \u0686\u0627\u06C1\u06CC\u06D2 {{ max }} \u0627\u0648\u0631 {{ min }} \u06CC\u06C1 \u0648\u064A\u0644\u064A\u0648", "validators", "ur");
  t.add("This value is not a valid hostname.", "\u0646\u06C1\u06CC\u06BA \u06C1\u06D2 hostname \u06CC\u06C1 \u0648\u064A\u0644\u064A\u0648 \u062F\u0631\u0633\u062A", "validators", "ur");
  t.add("The number of elements in this collection should be a multiple of {{ compared_value }}.", "\u06A9\u06CC \u0636\u0631\u0628 \u06C1\u0648\u0646\u06CC \u0686\u0627\u06C1\u06CC\u06D2 {{ compared_value }} \u0627\u0633 \u0645\u062C\u0645\u0648\u0639\u06C1 \u0645\u06CC\u06BA \u0639\u0646\u0627\u0635\u0631 \u06A9\u06CC \u062A\u0639\u062F\u0627\u062F", "validators", "ur");
  t.add("This value should satisfy at least one of the following constraints:", "\u0627\u0633 \u0648\u064A\u0644\u064A\u0648 \u06A9\u0648 \u062F\u0631\u062C \u0630\u06CC\u0644 \u0631\u06A9\u0627\u0648\u0679\u0648\u06BA \u0645\u06CC\u06BA \u0633\u06D2 \u06A9\u0645 \u0627\u0632 \u06A9\u0645 \u0627\u06CC\u06A9 \u06A9\u0648 \u067E\u0648\u0631\u0627 \u06A9\u0631\u0646\u0627 \u0686\u0627\u06C1\u06CC\u06D2", "validators", "ur");
  t.add("Each element of this collection should satisfy its own set of constraints.", "\u0627\u0633 \u0645\u062C\u0645\u0648\u0639\u06D2 \u06A9\u06D2 \u06C1\u0631 \u0639\u0646\u0635\u0631 \u06A9\u0648 \u0627\u067E\u0646\u06CC \u067E\u0627\u0628\u0646\u062F\u06CC\u0648\u06BA \u06A9\u06D2 \u0633\u06CC\u0679 \u06A9\u0648 \u067E\u0648\u0631\u0627 \u06A9\u0631\u0646\u0627 \u0686\u0627\u06C1\u06CC\u06D2", "validators", "ur");
  t.add("This value is not a valid International Securities Identification Number (ISIN).", "\u0646\u06C1\u06CC\u06BA \u06C1\u06D2 (ISIN) \u06CC\u06C1 \u0648\u064A\u0644\u064A\u0648 \u062F\u0631\u0633\u062A \u0628\u06CC\u0646 \u0627\u0644\u0627\u0642\u0648\u0627\u0645\u06CC \u0633\u06CC\u06A9\u06CC\u0648\u0631\u0679\u06CC\u0632 \u0634\u0646\u0627\u062E\u062A\u06CC \u0646\u0645\u0628\u0631", "validators", "ur");
  t.add("This value should be a valid expression.", "\u06CC\u06C1 \u0648\u064A\u0644\u064A\u0648 \u0627\u06CC\u06A9 \u062F\u0631\u0633\u062A \u0627\u0638\u06C1\u0627\u0631 \u06C1\u0648\u0646\u064A \u0686\u0627\u06C1\u06CC\u06D2", "validators", "ur");
  t.add("This value is not a valid CSS color.", "\u0631\u0646\u06AF \u0646\u06C1\u06CC\u06BA \u06C1\u06D2 CSS \u06CC\u06C1 \u0648\u064A\u0644\u064A\u0648 \u062F\u0631\u0633\u062A", "validators", "ur");
  t.add("This value is not a valid CIDR notation.", "\u0646\u0648\u0679\u06CC\u0634\u0646 \u0646\u06C1\u06CC\u06BA \u06C1\u06D2 CIDR \u06CC\u06C1 \u0648\u064A\u0644\u064A\u0648 \u0627\u06CC\u06A9 \u062F\u0631\u0633\u062A", "validators", "ur");
  t.add("The value of the netmask should be between {{ min }} and {{ max }}.", "\u06A9\u06D2 \u062F\u0631\u0645\u06CC\u0627\u0646 \u06C1\u0648\u0646\u06CC \u0686\u0627\u06C1\u06CC\u06D2 {{ max }} \u0627\u0648\u0631 {{ min }} \u0646\u06CC\u0679 \u0645\u0627\u0633\u06A9 \u06A9\u06CC \u0648\u064A\u0644\u064A\u0648", "validators", "ur");
  t.add("The filename is too long. It should have {{ filename_max_length }} character or less.|The filename is too long. It should have {{ filename_max_length }} characters or less.", "\u0641\u0627\u0626\u0644 \u06A9\u0627 \u0646\u0627\u0645 \u0628\u06C1\u062A \u0644\u0645\u0628\u0627 \u06C1\u06D2\u06D4 \u0627\u0633 \u0645\u06CC\u06BA {{ filename_max_length }} \u062D\u0631\u0641 \u06CC\u0627 \u0627\u0633 \u0633\u06D2 \u06A9\u0645 \u06C1\u0648\u0646\u06D2 \u0686\u0627\u06C1\u0626\u06CC\u06BA\u06D4|\u0641\u0627\u0626\u0644 \u06A9\u0627 \u0646\u0627\u0645 \u0628\u06C1\u062A \u0644\u0645\u0628\u0627 \u06C1\u06D2\u06D4 \u0627\u0633 \u0645\u06CC\u06BA {{ filename_max_length }} \u062D\u0631\u0648\u0641 \u06CC\u0627 \u0627\u0633 \u0633\u06D2 \u06A9\u0645 \u06C1\u0648\u0646\u06D2 \u0686\u0627\u06C1\u0626\u06CC\u06BA\u06D4", "validators", "ur");
  t.add("The password strength is too low. Please use a stronger password.", "\u067E\u0627\u0633 \u0648\u0631\u0688 \u06A9\u06CC \u0637\u0627\u0642\u062A \u0628\u06C1\u062A \u06A9\u0645 \u06C1\u06D2\u06D4 \u0628\u0631\u0627\u06C1 \u06A9\u0631\u0645 \u0645\u0636\u0628\u0648\u0637 \u067E\u0627\u0633 \u0648\u0631\u0688 \u0627\u0633\u062A\u0639\u0645\u0627\u0644 \u06A9\u0631\u06CC\u06BA\u06D4", "validators", "ur");
  t.add("This value contains characters that are not allowed by the current restriction-level.", "\u0627\u0633 \u0642\u062F\u0631 \u0645\u06CC\u06BA \u0627\u06CC\u0633\u06D2 \u062D\u0631\u0648\u0641 \u0645\u0648\u062C\u0648\u062F \u06C1\u06CC\u06BA \u062C\u0648 \u0645\u0648\u062C\u0648\u062F\u06C1 \u067E\u0627\u0628\u0646\u062F\u06CC \u06A9\u06CC \u0633\u0637\u062D \u06A9\u06CC \u0637\u0631\u0641 \u0633\u06D2 \u0627\u062C\u0627\u0632\u062A \u0646\u06C1\u06CC\u06BA \u06C1\u06CC\u06BA\u06D4", "validators", "ur");
  t.add("Using invisible characters is not allowed.", "\u0646\u0627\u062F\u06CC\u062F\u06C1 \u062D\u0631\u0648\u0641 \u0627\u0633\u062A\u0639\u0645\u0627\u0644 \u06A9\u0631\u0646\u06D2 \u06A9\u06CC \u0627\u062C\u0627\u0632\u062A \u0646\u06C1\u06CC\u06BA \u06C1\u06D2\u06D4", "validators", "ur");
  t.add("Mixing numbers from different scripts is not allowed.", "\u0645\u062E\u062A\u0644\u0641 \u0627\u0633\u06A9\u0631\u067E\u0679\u0633 \u0633\u06D2 \u0646\u0645\u0628\u0631\u0648\u06BA \u06A9\u0648 \u0645\u0644\u0627 \u06A9\u0631 \u0627\u0633\u062A\u0639\u0645\u0627\u0644 \u06A9\u0631\u0646\u06D2 \u06A9\u06CC \u0627\u062C\u0627\u0632\u062A \u0646\u06C1\u06CC\u06BA \u06C1\u06D2\u06D4", "validators", "ur");
  t.add("Using hidden overlay characters is not allowed.", "\u0686\u06BE\u067E\u06D2 \u06C1\u0648\u0626\u06D2 \u0627\u0648\u0648\u0631\u0644\u06D2 \u06A9\u0631\u06CC\u06A9\u0679\u0631\u0632 \u06A9\u0627 \u0627\u0633\u062A\u0639\u0645\u0627\u0644 \u06A9\u0631\u0646\u06D2 \u06A9\u06CC \u0627\u062C\u0627\u0632\u062A \u0646\u06C1\u06CC\u06BA \u06C1\u06D2\u06D4", "validators", "ur");
  t.add("The extension of the file is invalid ({{ extension }}). Allowed extensions are {{ extensions }}.", "\u0641\u0627\u0626\u0644 \u06A9\u06CC \u062A\u0648\u0633\u06CC\u0639 \u0646\u0627\u0645\u0646\u0627\u0633\u0628 \u06C1\u06D2 ({{ extension }})\u06D4 \u0627\u062C\u0627\u0632\u062A \u0634\u062F\u06C1 \u062A\u0648\u0633\u06CC\u0639\u0627\u062A {{ extensions }} \u06C1\u06CC\u06BA\u06D4", "validators", "ur");
  t.add("The detected character encoding is invalid ({{ detected }}). Allowed encodings are {{ encodings }}.", "\u067E\u062A\u06C1 \u0686\u0644\u0646\u06D2 \u0648\u0627\u0644\u06CC \u06A9\u0631\u06CC\u06A9\u0679\u0631 \u0627\u0646\u06A9\u0648\u0688\u0646\u06AF \u0646\u0627\u0645\u0646\u0627\u0633\u0628 \u06C1\u06D2 ({{ detected }})\u06D4 \u0627\u062C\u0627\u0632\u062A \u0634\u062F\u06C1 \u0627\u0646\u06A9\u0648\u0688\u0646\u06AF\u0632 {{ encodings }} \u06C1\u06CC\u06BA\u06D4", "validators", "ur");
  t.add("This value is not a valid MAC address.", "\u06CC\u06C1 \u0642\u06CC\u0645\u062A \u06A9\u0648\u0626\u06CC \u062F\u0631\u0633\u062A MAC \u067E\u062A\u06C1 \u0646\u06C1\u06CC\u06BA \u06C1\u06D2\u06D4", "validators", "ur");
  t.add("This URL is missing a top-level domain.", "\u0627\u0633 URL \u0645\u06CC\u06BA \u0679\u0627\u067E \u0644\u06CC\u0648\u0644 \u0688\u0648\u0645\u06CC\u0646 \u0645\u0648\u062C\u0648\u062F \u0646\u06C1\u06CC\u06BA \u06C1\u06D2\u06D4", "validators", "ur");
  t.add("This value is too short. It should contain at least one word.|This value is too short. It should contain at least {{ min }} words.", "This value is too short. It should contain at least one word.|This value is too short. It should contain at least {{ min }} words.", "validators", "ur");
  t.add("This value is too long. It should contain one word.|This value is too long. It should contain {{ max }} words or less.", "This value is too long. It should contain one word.|This value is too long. It should contain {{ max }} words or less.", "validators", "ur");
  t.add("This value does not represent a valid week in the ISO 8601 format.", "This value does not represent a valid week in the ISO 8601 format.", "validators", "ur");
  t.add("This value is not a valid week.", "This value is not a valid week.", "validators", "ur");
