  t.add("This form should not contain extra fields.", "\u0627\u0633 \u0641\u0627\u0631\u0645 \u0645\u06CC\u06BA \u0627\u0636\u0627\u0641\u06CC \u0641\u06CC\u0644\u0688\u0632 \u0646\u06C1\u06CC\u06BA \u06C1\u0648\u0646\u06CC \u0686\u0627\u06C1\u0626\u06CC\u06BA", "validators", "ur");
  t.add("The uploaded file was too large. Please try to upload a smaller file.", "\u0627\u067E \u0644\u0648\u0688 \u06A9\u0631\u062F\u06BE \u0641\u0627\u0626\u0644 \u0628\u06C1\u062A \u0628\u0691\u06CC \u062A\u06BE\u06CC\u06D4 \u0628\u0631\u0627\u06C1 \u06A9\u0631\u0645 \u0627\u06CC\u06A9 \u0686\u06BE\u0648\u0679\u06CC \u0641\u0627\u0626\u0644 \u0627\u067E \u0644\u0648\u0688 \u06A9\u0631\u0646\u06D2 \u06A9\u06CC \u06A9\u0648\u0634\u0634 \u06A9\u0631\u06CC\u06BA", "validators", "ur");
  t.add("The CSRF token is invalid. Please try to resubmit the form.", "\u0679\u0648\u06A9\u0646 \u063A\u0644\u0637 \u06C1\u06D2\u06D4 \u0628\u0631\u0627\u06D3 \u06A9\u0631\u0645 \u0641\u0627\u0631\u0645 \u06A9\u0648 \u062F\u0648\u0628\u0627\u0631\u06C1 \u062C\u0645\u0639 \u06A9\u0631\u0627\u0646\u06D2 \u06A9\u06CC \u06A9\u0648\u0634\u0634 \u06A9\u0631\u06CC\u06BA CSRF", "validators", "ur");
  t.add("This value is not a valid HTML5 color.", "\u0631 \u0646\u06AF \u0646\u06BE\u06CC\u06BA \u06BE\u06D2HTML \u06CC\u06BE \u0648\u0644\u06CC\u0648 \u062F\u0631 \u0633\u062A", "validators", "ur");
  t.add("Please enter a valid birthdate.", "\u0628\u0631\u0627\u06D3 \u06A9\u0631\u0645 \u062F\u0631\u0633\u062A \u062A\u0627\u0631\u06CC\u062E \u067E\u06CC\u062F\u0627\u0626\u0634 \u062F\u0631\u062C \u06A9\u0631\u06CC\u06BA", "validators", "ur");
  t.add("The selected choice is invalid.", "\u0645\u0646\u062A\u062E\u0628 \u06A9\u0631\u062F\u06C1 \u0627\u0646\u062A\u062E\u0627\u0628 \u063A\u0644\u0637 \u06C1\u06D2", "validators", "ur");
  t.add("The collection is invalid.", "\u06CC\u06BE \u0645\u062C\u0645\u0648\u0639\u06C1 \u063A\u0644\u0637 \u06C1\u06D2", "validators", "ur");
  t.add("Please select a valid color.", "\u0628\u0631\u0627\u06D3 \u06A9\u0631\u0645 \u0627\u06CC\u06A9 \u062F\u0631\u0633\u062A \u0631\u0646\u06AF \u0645\u0646\u062A\u062E\u0628 \u06A9\u0631\u06CC\u06BA", "validators", "ur");
  t.add("Please select a valid country.", "\u0628\u0631\u0627\u06D3 \u06A9\u0631\u0645 \u0627\u06CC\u06A9 \u062F\u0631\u0633\u062A \u0645\u0644\u06A9 \u0645\u0646\u062A\u062E\u0628 \u06A9\u0631\u06CC\u06BA", "validators", "ur");
  t.add("Please select a valid currency.", "\u0628\u0631\u0627\u06D3 \u06A9\u0631\u0645 \u0627\u06CC\u06A9 \u062F\u0631\u0633\u062A \u06A9\u0631\u0646\u0633\u06CC \u0645\u0646\u062A\u062E\u0628 \u06A9\u0631\u06CC\u06BA", "validators", "ur");
  t.add("Please choose a valid date interval.", "\u0628\u0631\u0627\u06D3 \u06A9\u0631\u0645 \u0627\u06CC\u06A9 \u062F\u0631\u0633\u062A \u062A\u0627\u0631\u06CC\u062E\u06CC \u0648\u0642\u0641\u06BE\u06C1 \u0645\u0646\u062A\u062E\u0628 \u06A9\u0631\u06CC\u06BA", "validators", "ur");
  t.add("Please enter a valid date and time.", "\u0628\u0631\u0627\u06D3 \u06A9\u0631\u0645 \u0627\u06CC\u06A9 \u062F\u0631\u0633\u062A \u062A\u0627\u0631\u06CC\u062E \u0627\u0648\u0631 \u0648\u0642\u062A \u062F\u0631\u062C \u06A9\u0631\u06CC\u06BA", "validators", "ur");
  t.add("Please enter a valid date.", "\u0628\u0631\u0627\u06D3 \u06A9\u0631\u0645 \u0627\u06CC\u06A9 \u062F\u0631\u0633\u062A \u062A\u0627\u0631\u06CC\u062E \u062F\u0631\u062C \u06A9\u0631\u06CC\u06BA", "validators", "ur");
  t.add("Please select a valid file.", "\u0628\u0631\u0627\u06D3 \u06A9\u0631\u0645 \u0627\u06CC\u06A9 \u062F\u0631\u0633\u062A \u0641\u0627\u0626\u0644 \u0645\u0646\u062A\u062E\u0628 \u06A9\u0631\u06CC\u06BA", "validators", "ur");
  t.add("The hidden field is invalid.", "\u067E\u0648\u0634\u06CC\u062F\u06BE\u06C1 \u0641\u06CC\u0644\u0688 \u063A\u0644\u0637 \u06C1\u06D2", "validators", "ur");
  t.add("Please enter an integer.", "\u0628\u0631\u0627\u06D3 \u06A9\u0631\u0645 \u0627\u06CC\u06A9 \u0639\u062F\u062F \u062F\u0631\u062C \u06A9\u0631\u06CC\u06BA", "validators", "ur");
  t.add("Please select a valid language.", "\u0628\u0631\u0627\u06D3 \u06A9\u0631\u0645 \u0627\u06CC\u06A9 \u062F\u0631\u0633\u062A \u0632\u0628\u0627\u0646 \u0645\u0646\u062A\u062E\u0628 \u06A9\u0631\u06CC\u06BA", "validators", "ur");
  t.add("Please select a valid locale.", "\u0628\u0631\u0627\u06D3 \u06A9\u0631\u0645 \u0627\u06CC\u06A9 \u062F\u0631\u0633\u062A \u0645\u0642\u0627\u0645 \u0645\u0646\u062A\u062E\u0628 \u06A9\u0631\u06CC\u06BA", "validators", "ur");
  t.add("Please enter a valid money amount.", "\u0628\u0631\u0627\u06D3 \u06A9\u0631\u0645 \u0627\u06CC\u06A9 \u062F\u0631\u0633\u062A \u0631\u0642\u0645 \u062F\u0631\u062C \u06A9\u0631\u06CC\u06BA", "validators", "ur");
