  t.add("Please enter a percentage value.", "\u0628\u0631\u0627\u06C1 \u06A9\u0631\u0645 \u0641\u06CC\u0635\u062F \u06A9\u06CC \u0648\u064A\u0644\u0648 \u062F\u0631\u062C \u06A9\u0631\u06CC\u06BA", "validators", "ur");
  t.add("The values do not match.", "\u0648\u064A\u0644\u064A\u0648\u0630 \u0679\u06BE\u064A\u06A9 \u0646\u06C1\u06CC\u06BA \u06C1\u06CC\u06BA", "validators", "ur");
  t.add("Please enter a valid time.", "\u0628\u0631\u0627\u06D3 \u06A9\u0631\u0645 \u0627\u06CC\u06A9 \u062F\u0631\u0633\u062A \u0648\u0642\u062A \u062F\u0631\u062C \u06A9\u0631\u06CC\u06BA", "validators", "ur");
  t.add("Please select a valid timezone.", "\u0628\u0631\u0627\u06D3 \u06A9\u0631\u0645 \u0627\u06CC\u06A9 \u062F\u0631\u0633\u062A \u0679\u0627\u0626\u0645 \u0632\u0648\u0646 \u0645\u0646\u062A\u062E\u0628 \u06A9\u0631\u06CC\u06BA", "validators", "ur");
  t.add("Please enter a valid URL.", "\u0628\u0631\u0627\u06D3 \u06A9\u0631\u0645 \u0627\u06CC\u06A9 \u062F\u0631\u0633\u062A \u0627\u062F\u0631\u064A\u0633 \u062F\u0631\u062C \u06A9\u0631\u06CC\u06BA", "validators", "ur");
  t.add("Please enter a valid search term.", "\u0628\u0631\u0627\u06D3 \u06A9\u0631\u0645 \u0627\u06CC\u06A9 \u062F\u0631\u0633\u062A \u0648\u064A\u0644\u0648 \u062A\u0644\u0627\u0634 \u06A9\u064A\u0644\u06D3 \u062F\u0631\u062C \u06A9\u0631\u06CC\u06BA", "validators", "ur");
  t.add("Please provide a valid phone number.", "\u0628\u0631\u0627\u06D3 \u06A9\u0631\u0645 \u0627\u06CC\u06A9 \u062F\u0631\u0633\u062A \u0641\u0648\u0646 \u0646\u0645\u0628\u0631 \u0641\u0631\u0627\u06C1\u0645 \u06A9\u0631\u06CC\u06BA", "validators", "ur");
  t.add("The checkbox has an invalid value.", "\u0686\u06CC\u06A9 \u0628\u0627\u06A9\u0633 \u0645\u06CC\u06BA \u0627\u06CC\u06A9 \u063A\u0644\u0637 \u0648\u064A\u0644\u0648 \u06C1\u06D2", "validators", "ur");
  t.add("Please enter a valid email address.", "\u0628\u0631\u0627\u06D3 \u0645\u06C1\u0631\u0628\u0627\u0646\u06CC \u0642\u0627\u0628\u0644 \u0642\u0628\u0648\u0644 \u0627\u06CC \u0645\u06CC\u0644 \u0627\u06CC\u0688\u0631\u06CC\u0633 \u0644\u06A9\u06BE\u06CC\u06BA", "validators", "ur");
  t.add("Please select a valid option.", "\u0628\u0631\u0627\u06D3 \u06A9\u0631\u0645 \u0627\u06CC\u06A9 \u062F\u0631\u0633\u062A \u0622\u067E\u0634\u0646 \u0645\u0646\u062A\u062E\u0628 \u06A9\u0631\u06CC\u06BA", "validators", "ur");
  t.add("Please select a valid range.", "\u0628\u0631\u0627\u06D3 \u06A9\u0631\u0645 \u0627\u06CC\u06A9 \u062F\u0631\u0633\u062A \u0631\u06CC\u0646\u062C \u0645\u0646\u062A\u062E\u0628 \u06A9\u0631\u06CC\u06BA", "validators", "ur");
  t.add("Please enter a valid week.", "\u0628\u0631\u0627\u06D3 \u06A9\u0631\u0645 \u0627\u06CC\u06A9 \u062F\u0631\u0633\u062A \u06C1\u0641\u062A\u06C1 \u062F\u0631\u062C \u06A9\u0631\u06CC\u06BA", "validators", "ur");
