  t.add("The image height is too big ({{ height }}px). Allowed maximum height is {{ max_height }}px.", "Chi\u1EC1u cao c\u1EE7a h\xECnh qu\xE1 cao ({{ height }}px). Chi\u1EC1u cao t\u1ED1i \u0111a ph\u1EA3i l\xE0 {{ max_height }}px.", "validators", "vi");
  t.add("The image height is too small ({{ height }}px). Minimum height expected is {{ min_height }}px.", "Chi\u1EC1u cao c\u1EE7a h\xECnh qu\xE1 th\u1EA5p ({{ height }}px). Chi\u1EC1u cao t\u1ED1i thi\u1EC3u ph\u1EA3i l\xE0 {{ min_height }}px.", "validators", "vi");
