  t.add("This value should have exactly {{ limit }} character.|This value should have exactly {{ limit }} characters.", "Gi\xE1 tr\u1ECB n\xE0y ph\u1EA3i c\xF3 ch\xEDnh x\xE1c {{ limit }} k\xED t\u1EF1.|Gi\xE1 tr\u1ECB n\xE0y ph\u1EA3i c\xF3 ch\xEDnh x\xE1c {{ limit }} k\xED t\u1EF1.", "validators", "vi");
