  t.add("This collection should contain {{ limit }} element or more.|This collection should contain {{ limit }} elements or more.", "Danh s\xE1ch ph\u1EA3i ch\u1EE9a {{ limit }} th\xE0nh ph\u1EA7n ho\u1EB7c nhi\u1EC1u h\u01A1n.|Danh s\xE1ch ph\u1EA3i ch\u1EE9a {{ limit }} th\xE0nh ph\u1EA7n ho\u1EB7c nhi\u1EC1u h\u01A1n.", "validators", "vi");
  t.add("This collection should contain {{ limit }} element or less.|This collection should contain {{ limit }} elements or less.", "Danh s\xE1ch ph\u1EA3i ch\u1EE9a {{ limit }} th\xE0nh ph\u1EA7n ho\u1EB7c \xEDt h\u01A1n.|Danh s\xE1ch ph\u1EA3i ch\u1EE9a {{ limit }} th\xE0nh ph\u1EA7n ho\u1EB7c \xEDt h\u01A1n.", "validators", "vi");
  t.add("This collection should contain exactly {{ limit }} element.|This collection should contain exactly {{ limit }} elements.", "Danh s\xE1ch ph\u1EA3i ch\u1EE9a ch\xEDnh x\xE1c {{ limit }} th\xE0nh ph\u1EA7n.|Danh s\xE1ch ph\u1EA3i ch\u1EE9a ch\xEDnh x\xE1c {{ limit }} th\xE0nh ph\u1EA7n.", "validators", "vi");
