  t.add("This is not a valid International Bank Account Number (IBAN).", "Gi\xE1 tr\u1ECB n\xE0y kh\xF4ng ph\u1EA3i l\xE0 S\u1ED1 T\xE0i Kho\u1EA3n Ng\xE2n H\xE0ng Qu\u1ED1c T\u1EBF (IBAN) h\u1EE3p l\u1EC7.", "validators", "vi");
  t.add("This value is not a valid ISBN-10.", "Gi\xE1 tr\u1ECB kh\xF4ng ph\u1EA3i l\xE0 ISBN-10 h\u1EE3p l\u1EC7.", "validators", "vi");
