  t.add("This value is not a valid ISSN.", "Gi\xE1 tr\u1ECB kh\xF4ng ph\u1EA3i l\xE0 ISSN h\u1EE3p l\u1EC7.", "validators", "vi");
  t.add("This value is not a valid currency.", "Gi\xE1 tr\u1ECB kh\xF4ng ph\u1EA3i l\xE0 \u0111\u01A1n v\u1ECB ti\u1EC1n t\u1EC7 h\u1EE3p l\u1EC7.", "validators", "vi");
  t.add("This value should be equal to {{ compared_value }}.", "Gi\xE1 tr\u1ECB ph\u1EA3i b\u1EB1ng {{ compared_value }}.", "validators", "vi");
