  t.add("This value should be identical to {{ compared_value_type }} {{ compared_value }}.", "Gi\xE1 tr\u1ECB ph\u1EA3i gi\u1ED1ng  {{ compared_value_type }} {{ compared_value }}.", "validators", "vi");
  t.add("This value should be less than {{ compared_value }}.", "Gi\xE1 tr\u1ECB ph\u1EA3i b\xE9 h\u01A1n {{ compared_value }}.", "validators", "vi");
  t.add("This value should be less than or equal to {{ compared_value }}.", "Gi\xE1 tr\u1ECB ph\u1EA3i nh\u1ECF h\u01A1n ho\u1EB7c b\u1EB1ng {{ compared_value }}.", "validators", "vi");
  t.add("This value should not be equal to {{ compared_value }}.", "Gi\xE1 tr\u1ECB kh\xF4ng \u0111\u01B0\u1EE3c ph\xE9p b\u1EB1ng {{ compared_value }}.", "validators", "vi");
  t.add("This value should not be identical to {{ compared_value_type }} {{ compared_value }}.", "Gi\xE1 tr\u1ECB kh\xF4ng \u0111\u01B0\u1EE3c ph\xE9p gi\u1ED1ng nh\u01B0 {{ compared_value_type }} {{ compared_value }}.", "validators", "vi");
  t.add("The image ratio is too big ({{ ratio }}). Allowed maximum ratio is {{ max_ratio }}.", "T\u1EF7 l\u1EC7 b\u1EE9c \u1EA3nh qu\xE1 l\u1EDBn ({{ ratio }}). T\u1EF7 l\u1EC7 t\u1ED1i \u0111a cho ph\xE9p l\xE0 {{ max_ratio }}.", "validators", "vi");
  t.add("The image ratio is too small ({{ ratio }}). Minimum ratio expected is {{ min_ratio }}.", "T\u1EF7 l\u1EC7 b\u1EE9c \u1EA3nh qu\xE1 nh\u1ECF ({{ ratio }}). T\u1EF7 l\u1EC7 t\u1ED1i thi\u1EC3u mong mu\u1ED1n l\xE0 {{ min_ratio }}.", "validators", "vi");
  t.add("The image is square ({{ width }}x{{ height }}px). Square images are not allowed.", "B\u1EE9c \u1EA3nh l\xE0 h\xECnh vu\xF4ng ({{ width }}x{{ height }}px). \u1EA2nh h\xECnh vu\xF4ng kh\xF4ng \u0111\u01B0\u1EE3c ph\xE9p.", "validators", "vi");
  t.add("The image is landscape oriented ({{ width }}x{{ height }}px). Landscape oriented images are not allowed.", "B\u1EE9c \u1EA3nh theo chi\u1EC1u ngang ({{ width }}x{{ height }}px). \u1EA2nh chi\u1EC1u ngang kh\xF4ng \u0111\u01B0\u1EE3c ph\xE9p.", "validators", "vi");
  t.add("The image is portrait oriented ({{ width }}x{{ height }}px). Portrait oriented images are not allowed.", "B\u1EE9c \u1EA3nh theo chi\u1EC1u d\u1ECDc ({{ width }}x{{ height }}px). \u1EA2nh chi\u1EC1u d\u1ECDc kh\xF4ng \u0111\u01B0\u1EE3c ph\xE9p.", "validators", "vi");
  t.add("An empty file is not allowed.", "M\u1ED9t file r\u1ED7ng kh\xF4ng \u0111\u01B0\u1EE3c ph\xE9p.", "validators", "vi");
  t.add("The host could not be resolved.", "M\xE1y ch\u1EE7 kh\xF4ng th\u1EC3 \u0111\u01B0\u1EE3c t\xECm th\u1EA5y.", "validators", "vi");
  t.add("This value does not match the expected {{ charset }} charset.", "Gi\xE1 tr\u1ECB n\xE0y kh\xF4ng \u0111\xFAng \u0111\u1ECBnh d\u1EA1ng b\u1ED9 k\xFD t\u1EF1 mong mu\u1ED1n {{ charset }}.", "validators", "vi");
  t.add("This is not a valid Business Identifier Code (BIC).", "Gi\xE1 tr\u1ECB n\xE0y kh\xF4ng ph\u1EA3i l\xE0 M\xE3 \u0110\u1ECBnh Danh Doanh Nghi\u1EC7p (BIC) h\u1EE3p l\u1EC7.", "validators", "vi");
  t.add("Error", "L\u1ED7i", "validators", "vi");
  t.add("This is not a valid UUID.", "Gi\xE1 tr\u1ECB n\xE0y kh\xF4ng ph\u1EA3i l\xE0 UUID h\u1EE3p l\u1EC7.", "validators", "vi");
  t.add("This value should be a multiple of {{ compared_value }}.", "Gi\xE1 tr\u1ECB n\xE0y n\xEAn l\xE0 b\u1ED9i s\u1ED1 c\u1EE7a {{ compared_value }}.", "validators", "vi");
  t.add("This Business Identifier Code (BIC) is not associated with IBAN {{ iban }}.", "M\xE3 \u0111\u1ECBnh danh doanh nghi\u1EC7p (BIC) n\xE0y kh\xF4ng li\xEAn k\u1EBFt v\u1EDBi IBAN {{ iban }}.", "validators", "vi");
  t.add("This value should be valid JSON.", "Gi\xE1 tr\u1ECB n\xE0y n\xEAn \u0111\xFAng \u0111\u1ECBnh d\u1EA1ng JSON.", "validators", "vi");
  t.add("This collection should contain only unique elements.", "Danh s\xE1ch n\xE0y ch\u1EC9 n\xEAn ch\u1EE9a c\xE1c ph\u1EA7n t\u1EED kh\xE1c nhau.", "validators", "vi");
  t.add("This value should be positive.", "Gi\xE1 tr\u1ECB n\xE0y c\xF3 th\u1EC3 th\u1EF1c hi\u1EC7n \u0111\u01B0\u1EE3c.", "validators", "vi");
  t.add("This value should be either positive or zero.", "Gi\xE1 tr\u1ECB n\xE0y c\xF3 th\u1EC3 th\u1EF1c hi\u1EC7n \u0111\u01B0\u1EE3c ho\u1EB7c b\u1EB1ng kh\xF4ng.", "validators", "vi");
  t.add("This value should be negative.", "Gi\xE1 tr\u1ECB n\xE0y n\xEAn b\u1ECB t\u1EEB ch\u1ED1i.", "validators", "vi");
  t.add("This value should be either negative or zero.", "Gi\xE1 tr\u1ECB n\xE0y n\xEAn b\u1ECB t\u1EEB ch\u1ED1i ho\u1EB7c b\u1EB1ng kh\xF4ng.", "validators", "vi");
  t.add("This value is not a valid timezone.", "Gi\xE1 tr\u1ECB n\xE0y kh\xF4ng ph\u1EA3i l\xE0 m\xFAi gi\u1EDD h\u1EE3p l\u1EC7.", "validators", "vi");
  t.add("This password has been leaked in a data breach, it must not be used. Please use another password.", "M\u1EADt kh\u1EA9u n\xE0y \u0111\xE3 b\u1ECB r\xF2 r\u1EC9 d\u1EEF li\u1EC7u, kh\xF4ng \u0111\u01B0\u1EE3c s\u1EED d\u1EE5ng n\u1EEFa. Xin vui l\xF2ng s\u1EED d\u1EE5ng m\u1EADt kh\u1EA9u kh\xE1c.", "validators", "vi");
  t.add("This value should be between {{ min }} and {{ max }}.", "Gi\xE1 tr\u1ECB n\xE0y n\xEAn thu\u1ED9c gi\u1EEFa {{ min }} v\xE0 {{ max }}.", "validators", "vi");
  t.add("This value is not a valid hostname.", "Gi\xE1 tr\u1ECB n\xE0y kh\xF4ng ph\u1EA3i l\xE0 t\xEAn m\xE1y ch\u1EE7 h\u1EE3p l\u1EC7.", "validators", "vi");
  t.add("The number of elements in this collection should be a multiple of {{ compared_value }}.", "S\u1ED1 l\u01B0\u1EE3ng c\xE1c ph\u1EA7n t\u1EED trong b\u1ED9 s\u01B0u t\u1EADp n\xE0y n\xEAn l\xE0 b\u1ED9i s\u1ED1 c\u1EE7a {{ compared_value }}.", "validators", "vi");
  t.add("This value should satisfy at least one of the following constraints:", "Gi\xE1 tr\u1ECB n\xE0y n\xEAn th\u1ECFa m\xE3n \xEDt nh\u1EA5t m\u1ED9t trong nh\u1EEFng r\xE0ng bu\u1ED9c sau:", "validators", "vi");
  t.add("Each element of this collection should satisfy its own set of constraints.", "M\u1ED7i ph\u1EA7n t\u1EED trong b\u1ED9 s\u01B0u t\u1EADp n\xE0y n\xEAn th\u1ECFa m\xE3n nh\u1EEFng r\xE0ng bu\u1ED9c c\u1EE7a n\xF3.", "validators", "vi");
  t.add("This value is not a valid International Securities Identification Number (ISIN).", "Gi\xE1 tr\u1ECB n\xE0y kh\xF4ng ph\u1EA3i l\xE0 m\xE3 s\u1ED1 ch\u1EE9ng kho\xE1n qu\u1ED1c t\u1EBF (ISIN) h\u01A1\u0323p l\xEA\u0323.", "validators", "vi");
  t.add("This value should be a valid expression.", "Gi\xE1 tr\u1ECB n\xE0y ph\u1EA3i l\xE0 m\u1ED9t bi\u1EC3u th\u1EE9c h\u1EE3p l\u1EC7.", "validators", "vi");
  t.add("This value is not a valid CSS color.", "Gi\xE1 tr\u1ECB n\xE0y kh\xF4ng ph\u1EA3i l\xE0 m\xE0u CSS h\u1EE3p l\u1EC7.", "validators", "vi");
  t.add("This value is not a valid CIDR notation.", "Gi\xE1 tr\u1ECB n\xE0y kh\xF4ng ph\u1EA3i l\xE0 k\xFD hi\u1EC7u CIDR h\u1EE3p l\u1EC7.", "validators", "vi");
  t.add("The value of the netmask should be between {{ min }} and {{ max }}.", "Gi\xE1 tr\u1ECB c\u1EE7a m\u1EB7t n\u1EA1 m\u1EA1ng ph\u1EA3i n\u1EB1m trong kho\u1EA3ng t\u1EEB {{ min }} \u0111\u1EBFn {{ max }}.", "validators", "vi");
  t.add("The filename is too long. It should have {{ filename_max_length }} character or less.|The filename is too long. It should have {{ filename_max_length }} characters or less.", "T\xEAn t\u1EC7p qu\xE1 d\xE0i. Ph\u1EA3i b\u1EB1ng {{ filename_max_length }} k\xFD t\u1EF1 ho\u1EB7c \xEDt h\u01A1n.|T\xEAn t\u1EC7p qu\xE1 d\xE0i. Ph\u1EA3i b\u1EB1ng {{ filename_max_length }} k\xFD t\u1EF1 ho\u1EB7c \xEDt h\u01A1n.", "validators", "vi");
  t.add("The password strength is too low. Please use a stronger password.", "S\u1EE9c m\u1EA1nh m\u1EADt kh\u1EA9u qu\xE1 th\u1EA5p. Vui l\xF2ng s\u1EED d\u1EE5ng m\u1EADt kh\u1EA9u m\u1EA1nh h\u01A1n.", "validators", "vi");
