  t.add("This value is too short. It should have {{ limit }} character or more.|This value is too short. It should have {{ limit }} characters or more.", "\u9019\u500B\u6578\u503C\u904E\u77ED\u3002\u6700\u5C11\u8981\u6709 {{ limit }} \u500B\u5B57\u5143\u3002|\u9019\u500B\u6578\u503C\u904E\u77ED\u3002\u6700\u5C11\u8981\u6709 {{ limit }} \u500B\u5B57\u5143\u3002", "validators", "zh_TW");
  t.add("This value should not be blank.", "\u9019\u500B\u6578\u503C\u4E0D\u5141\u8A31\u7559\u767D\u3002", "validators", "zh_TW");
  t.add("This value should not be null.", "\u9019\u500B\u6578\u503C\u4E0D\u80FD\u70BA\u7A7A\u503C\uFF08null\uFF09\u3002", "validators", "zh_TW");
  t.add("This value should be null.", "\u9019\u500B\u6578\u503C\u61C9\u70BA\u7A7A\u503C\uFF08null\uFF09\u3002", "validators", "zh_TW");
  t.add("This value is not valid.", "\u9019\u500B\u6578\u503C\u7121\u6548\u3002", "validators", "zh_TW");
  t.add("This value is not a valid time.", "\u9019\u500B\u6578\u503C\u4E0D\u662F\u6709\u6548\u7684\u6642\u9593\u3002", "validators", "zh_TW");
  t.add("This value is not a valid URL.", "\u9019\u500B\u6578\u503C\u4E0D\u662F URL \u683C\u5F0F\u3002", "validators", "zh_TW");
  t.add("The two values should be equal.", "\u9019\u5169\u500B\u6578\u503C\u61C9\u8A72\u76F8\u540C\u3002", "validators", "zh_TW");
  t.add("The file is too large. Allowed maximum size is {{ limit }} {{ suffix }}.", "\u9019\u500B\u6A94\u6848\u904E\u5927\u3002\u5141\u8A31\u7684\u5927\u5C0F\u4E0A\u9650\u70BA {{ limit }} {{ suffix }}\u3002", "validators", "zh_TW");
  t.add("The file is too large.", "\u9019\u500B\u6A94\u6848\u904E\u5927\u3002", "validators", "zh_TW");
  t.add("The file could not be uploaded.", "\u7121\u6CD5\u4E0A\u50B3\u6A94\u6848\u3002", "validators", "zh_TW");
  t.add("This value should be a valid number.", "\u9019\u500B\u6578\u503C\u4E0D\u662F\u6709\u6548\u7684\u6578\u5B57\u3002", "validators", "zh_TW");
  t.add("This file is not a valid image.", "\u9019\u500B\u6A94\u6848\u4E0D\u662F\u6709\u6548\u7684\u5F71\u50CF\u3002", "validators", "zh_TW");
  t.add("This is not a valid IP address.", "\u9019\u500B\u6578\u503C\u4E0D\u662F\u6709\u6548\u7684 IP \u5730\u5740\u3002", "validators", "zh_TW");
  t.add("This value is not a valid language.", "\u9019\u500B\u6578\u503C\u4E0D\u662F\u6709\u6548\u7684\u8A9E\u8A00\u3002", "validators", "zh_TW");
  t.add("This value is not a valid locale.", "\u9019\u500B\u6578\u503C\u4E0D\u662F\u6709\u6548\u7684\u5730\u5340\u3002", "validators", "zh_TW");
  t.add("This value is not a valid country.", "\u9019\u500B\u6578\u503C\u4E0D\u662F\u6709\u6548\u7684\u570B\u5BB6\u3002", "validators", "zh_TW");
  t.add("This value is already used.", "\u5DF2\u7D93\u7528\u904E\u9019\u500B\u6578\u503C\u3002", "validators", "zh_TW");
  t.add("The size of the image could not be detected.", "\u7121\u6CD5\u5075\u6E2C\u9019\u500B\u5F71\u50CF\u7684\u5927\u5C0F\u3002", "validators", "zh_TW");
  t.add("The image width is too big ({{ width }}px). Allowed maximum width is {{ max_width }}px.", "\u5F71\u50CF\u904E\u5BEC\uFF08{{ width }}px\uFF09\u3002\u5141\u8A31\u7684\u5BEC\u5EA6\u4E0A\u9650\u662F {{ max_width }}px\u3002", "validators", "zh_TW");
  t.add("The image width is too small ({{ width }}px). Minimum width expected is {{ min_width }}px.", "\u5F71\u50CF\u904E\u7A84\uFF08{{ width }}px\uFF09\u3002\u5141\u8A31\u7684\u5BEC\u5EA6\u4E0B\u9650\u662F {{ max_width }}px\u3002", "validators", "zh_TW");
  t.add("The image height is too big ({{ height }}px). Allowed maximum height is {{ max_height }}px.", "\u5F71\u50CF\u904E\u9577\uFF08{{ height }}px\uFF09\u3002\u5141\u8A31\u7684\u9577\u5EA6\u4E0A\u9650\u662F {{ max_height }}px\u3002", "validators", "zh_TW");
  t.add("The image height is too small ({{ height }}px). Minimum height expected is {{ min_height }}px.", "\u5F71\u50CF\u904E\u77ED\uFF08{{ height }}px\uFF09\u3002\u5141\u8A31\u7684\u9577\u5EA6\u4E0B\u9650\u662F {{ max_height }}px\u3002", "validators", "zh_TW");
  t.add("This value should be the user's current password.", "\u9019\u500B\u6578\u503C\u61C9\u70BA\u4F7F\u7528\u8005\u76EE\u524D\u4F7F\u7528\u7684\u5BC6\u78BC\u3002", "validators", "zh_TW");
  t.add("This value should have exactly {{ limit }} character.|This value should have exactly {{ limit }} characters.", "\u9019\u500B\u6578\u503C\u61C9\u525B\u597D\u70BA {{ limit }} \u500B\u5B57\u5143\u9577\u3002|\u9019\u500B\u6578\u503C\u61C9\u525B\u597D\u70BA {{ limit }} \u500B\u5B57\u5143\u9577\u3002", "validators", "zh_TW");
  t.add("The file was only partially uploaded.", "\u6A94\u6848\u53EA\u4E0A\u50B3\u4E86\u4E00\u90E8\u5206\u3002", "validators", "zh_TW");
  t.add("No file was uploaded.", "\u672A\u4E0A\u50B3\u6A94\u6848\u3002", "validators", "zh_TW");
  t.add("No temporary folder was configured in php.ini.", "\u672A\u5728 php.ini \u8A2D\u5B9A\u66AB\u5B58\u8CC7\u6599\u593E\uFF0C\u6216\u8005\u662F\u66AB\u5B58\u8CC7\u6599\u593E\u4E0D\u5B58\u5728\u3002", "validators", "zh_TW");
  t.add("Cannot write temporary file to disk.", "\u7121\u6CD5\u5C07\u66AB\u5B58\u6A94\u5BEB\u5165\u78C1\u789F\u3002", "validators", "zh_TW");
  t.add("A PHP extension caused the upload to fail.", "\u6709\u500B PHP \u64F4\u5145\u5957\u4EF6\u5C0E\u81F4\u4E0A\u50B3\u5931\u6557\u3002", "validators", "zh_TW");
  t.add("This collection should contain {{ limit }} element or more.|This collection should contain {{ limit }} elements or more.", "\u9019\u500B\u96C6\u5408\u61C9\u8A72\u81F3\u5C11\u6709 {{ limit }} \u500B\u5143\u7D20\u3002|\u9019\u500B\u96C6\u5408\u61C9\u8A72\u81F3\u5C11\u6709 {{ limit }} \u500B\u5143\u7D20\u3002", "validators", "zh_TW");
  t.add("This collection should contain {{ limit }} element or less.|This collection should contain {{ limit }} elements or less.", "\u9019\u500B\u96C6\u5408\u6700\u591A\u53EA\u80FD\u6709 {{ limit }} \u500B\u5143\u7D20\u3002|\u9019\u500B\u96C6\u5408\u6700\u591A\u53EA\u80FD\u6709 {{ limit }} \u500B\u5143\u7D20\u3002", "validators", "zh_TW");
  t.add("This collection should contain exactly {{ limit }} element.|This collection should contain exactly {{ limit }} elements.", "\u9019\u500B\u96C6\u5408\u53EA\u80FD\u6709\u525B\u597D {{ limit }} \u500B\u5143\u7D20\u3002|\u9019\u500B\u96C6\u5408\u53EA\u80FD\u6709\u525B\u597D {{ limit }} \u500B\u5143\u7D20\u3002", "validators", "zh_TW");
  t.add("Invalid card number.", "\u5361\u865F\u7121\u6548\u3002", "validators", "zh_TW");
  t.add("Unsupported card type or invalid card number.", "\u4E0D\u652F\u63F4\u9019\u500B\u5361\u7247\u985E\u578B\uFF0C\u6216\u5361\u865F\u4E0D\u6B63\u78BA\u3002", "validators", "zh_TW");
  t.add("This is not a valid International Bank Account Number (IBAN).", "\u9019\u500B\u6578\u503C\u7684\u683C\u5F0F\u4E0D\u662F\u570B\u969B\u9280\u884C\u5E33\u6236\u865F\u78BC\uFF08IBAN\uFF09\u3002", "validators", "zh_TW");
  t.add("This value is not a valid ISBN-10.", "\u9019\u500B\u6578\u503C\u7684\u683C\u5F0F\u4E0D\u662F ISBN-10\u3002", "validators", "zh_TW");
  t.add("This value is not a valid ISBN-13.", "\u9019\u500B\u6578\u503C\u7684\u683C\u5F0F\u4E0D\u662F ISBN-13\u3002", "validators", "zh_TW");
  t.add("This value is neither a valid ISBN-10 nor a valid ISBN-13.", "\u9019\u500B\u6578\u503C\u7684\u683C\u5F0F\u4E0D\u662F ISBN-10 \u6216 ISBN-13\u3002", "validators", "zh_TW");
  t.add("This value is not a valid ISSN.", "\u9019\u500B\u6578\u503C\u7684\u683C\u5F0F\u4E0D\u662F ISSN\u3002", "validators", "zh_TW");
  t.add("This value is not a valid currency.", "\u9019\u500B\u6578\u503C\u4E0D\u662F\u6709\u6548\u7684\u8CA8\u5E63\u3002", "validators", "zh_TW");
  t.add("This value should be equal to {{ compared_value }}.", "\u9019\u500B\u6578\u503C\u61C9\u7B49\u65BC {{ compared_value }}\u3002", "validators", "zh_TW");
  t.add("This value should be greater than {{ compared_value }}.", "\u9019\u500B\u6578\u503C\u61C9\u5927\u65BC {{ compared_value }}\u3002", "validators", "zh_TW");
  t.add("This value should be greater than or equal to {{ compared_value }}.", "\u9019\u500B\u6578\u503C\u61C9\u5927\u65BC\u7B49\u65BC {{ compared_value }}\u3002", "validators", "zh_TW");
  t.add("This value should be identical to {{ compared_value_type }} {{ compared_value }}.", "\u9019\u500B\u6578\u503C\u61C9\u7B49\u65BC {{ compared_value_type }} {{ compared_value }}\u3002", "validators", "zh_TW");
  t.add("This value should be less than {{ compared_value }}.", "\u9019\u500B\u6578\u503C\u61C9\u5C0F\u65BC {{ compared_value }}\u3002", "validators", "zh_TW");
  t.add("This value should be less than or equal to {{ compared_value }}.", "\u9019\u500B\u6578\u503C\u61C9\u5C0F\u65BC\u7B49\u65BC {{ compared_value }}\u3002", "validators", "zh_TW");
  t.add("This value should not be equal to {{ compared_value }}.", "\u9019\u500B\u6578\u503C\u4E0D\u61C9\u7B49\u65BC {{ compared_value }}\u3002", "validators", "zh_TW");
  t.add("This value should not be identical to {{ compared_value_type }} {{ compared_value }}.", "\u9019\u500B\u6578\u503C\u4E0D\u61C9\u7B49\u65BC {{ compared_value_type }} {{ compared_value }}\u3002", "validators", "zh_TW");
  t.add("The image ratio is too big ({{ ratio }}). Allowed maximum ratio is {{ max_ratio }}.", "\u5F71\u50CF\u7684\u6BD4\u4F8B\u904E\u5927\uFF08{{ ratio }}\uFF09\u3002\u5141\u8A31\u7684\u6700\u5927\u6BD4\u4F8B\u662F {{ max_ratio }}\u3002", "validators", "zh_TW");
  t.add("The image ratio is too small ({{ ratio }}). Minimum ratio expected is {{ min_ratio }}.", "\u5F71\u50CF\u7684\u6BD4\u4F8B\u904E\u5C0F\uFF08{{ ratio }}\uFF09\u3002\u5141\u8A31\u7684\u6700\u5C0F\u6BD4\u4F8B\u662F {{ min_ratio }}\u3002", "validators", "zh_TW");
  t.add("The image is square ({{ width }}x{{ height }}px). Square images are not allowed.", "\u5F71\u50CF\u70BA\u6B63\u65B9\u5F62\uFF08{{ width }}x{{ height }}px\uFF09\u3002\u4E0D\u5141\u8A31\u4F7F\u7528\u6B63\u65B9\u5F62\u5F71\u50CF\u3002", "validators", "zh_TW");
  t.add("The image is landscape oriented ({{ width }}x{{ height }}px). Landscape oriented images are not allowed.", "\u5F71\u50CF\u70BA\u6A6B\u5411\uFF08{{ width }}x{{ height }}px\uFF09\u3002\u4E0D\u5141\u8A31\u4F7F\u7528\u6A6B\u5411\u5F71\u50CF\u3002", "validators", "zh_TW");
  t.add("The image is portrait oriented ({{ width }}x{{ height }}px). Portrait oriented images are not allowed.", "\u5F71\u50CF\u70BA\u7E31\u5411\uFF08{{ width }}x{{ height }}px\uFF09\u3002\u4E0D\u5141\u8A31\u4F7F\u7528\u7E31\u5411\u5F71\u50CF\u3002", "validators", "zh_TW");
  t.add("An empty file is not allowed.", "\u4E0D\u5141\u8A31\u7A7A\u767D\u6A94\u6848\u3002", "validators", "zh_TW");
  t.add("The host could not be resolved.", "\u7121\u6CD5\u89E3\u6790\u4E3B\u6A5F\u3002", "validators", "zh_TW");
  t.add("This value does not match the expected {{ charset }} charset.", "\u9019\u500B\u6578\u503C\u4E0D\u7B26\u5408\u9810\u671F\u7684 {{ charset }} \u5B57\u5143\u96C6\u3002", "validators", "zh_TW");
  t.add("This is not a valid Business Identifier Code (BIC).", "\u9019\u500B\u6578\u503C\u4E0D\u662F\u6709\u6548\u7684\u5546\u696D\u8B58\u5225\u78BC\uFF08BIC\uFF09\u3002", "validators", "zh_TW");
  t.add("Error", "\u932F\u8AA4", "validators", "zh_TW");
  t.add("This is not a valid UUID.", "\u9019\u500B\u6578\u503C\u4E0D\u662F\u6709\u6548\u7684 UUID\u3002", "validators", "zh_TW");
  t.add("This value should be a multiple of {{ compared_value }}.", "\u9019\u500B\u6578\u503C\u61C9\u70BA {{ compared_value }} \u7684\u500D\u6578\u3002", "validators", "zh_TW");
  t.add("This Business Identifier Code (BIC) is not associated with IBAN {{ iban }}.", "\u9019\u500B\u5546\u696D\u8B58\u5225\u78BC\uFF08BIC\uFF09\u8207 IBAN {{ iban }} \u6C92\u6709\u95DC\u806F\u3002", "validators", "zh_TW");
  t.add("This value should be valid JSON.", "\u9019\u500B\u6578\u503C\u61C9\u70BA\u6709\u6548\u7684 JSON\u3002", "validators", "zh_TW");
  t.add("This collection should contain only unique elements.", "\u9019\u500B\u96C6\u5408\u4E0D\u5141\u8A31\u6709\u91CD\u8907\u5143\u7D20\u3002", "validators", "zh_TW");
  t.add("This value should be positive.", "\u9019\u500B\u6578\u503C\u61C9\u70BA\u6B63\u6578\u3002", "validators", "zh_TW");
  t.add("This value should be either positive or zero.", "\u9019\u500B\u6578\u503C\u61C9\u70BA\u6B63\u6578\u6216 0\u3002", "validators", "zh_TW");
  t.add("This value should be negative.", "\u9019\u500B\u6578\u503C\u61C9\u70BA\u8CA0\u6578\u3002", "validators", "zh_TW");
  t.add("This value should be either negative or zero.", "\u9019\u500B\u6578\u503C\u61C9\u70BA\u8CA0\u6578\u6216 0\u3002", "validators", "zh_TW");
  t.add("This value is not a valid timezone.", "\u9019\u500B\u6578\u503C\u4E0D\u662F\u6709\u6548\u7684\u6642\u5340\u3002", "validators", "zh_TW");
  t.add("This password has been leaked in a data breach, it must not be used. Please use another password.", "\u9019\u500B\u5BC6\u78BC\u5DF2\u5728\u8CC7\u6599\u6D29\u9732\u4E2D\u66DD\u5149\uFF0C\u4E0D\u61C9\u518D\u4F7F\u7528\u3002\u8ACB\u4F7F\u7528\u5176\u4ED6\u5BC6\u78BC\u3002", "validators", "zh_TW");
  t.add("This value should be between {{ min }} and {{ max }}.", "\u9019\u500B\u6578\u503C\u61C9\u4ECB\u65BC {{ min }} \u548C {{ max }} \u4E4B\u9593\u3002", "validators", "zh_TW");
  t.add("This value is not a valid hostname.", "\u9019\u500B\u6578\u503C\u4E0D\u662F\u6709\u6548\u7684\u4E3B\u6A5F\u540D\u7A31\u3002", "validators", "zh_TW");
  t.add("The number of elements in this collection should be a multiple of {{ compared_value }}.", "\u9019\u500B\u96C6\u5408\u4E2D\u7684\u5143\u7D20\u6578\u91CF\u61C9\u70BA {{ compared_value }} \u7684\u500D\u6578\u3002", "validators", "zh_TW");
  t.add("This value should satisfy at least one of the following constraints:", "\u9019\u500B\u6578\u503C\u61C9\u6EFF\u8DB3\u4EE5\u4E0B\u81F3\u5C11\u4E00\u9805\u9650\u5236\uFF1A", "validators", "zh_TW");
  t.add("Each element of this collection should satisfy its own set of constraints.", "\u9019\u500B\u96C6\u5408\u4E2D\u7684\u6BCF\u500B\u5143\u7D20\u61C9\u6EFF\u8DB3\u5176\u81EA\u8EAB\u7684\u7D04\u675F\u689D\u4EF6\u3002", "validators", "zh_TW");
  t.add("This value is not a valid International Securities Identification Number (ISIN).", "\u9019\u500B\u6578\u503C\u4E0D\u662F\u6709\u6548\u7684\u570B\u969B\u8B49\u5238\u8B58\u5225\u865F\u78BC\uFF08ISIN\uFF09\u3002", "validators", "zh_TW");
  t.add("This value should be a valid expression.", "\u9019\u500B\u6578\u503C\u61C9\u70BA\u6709\u6548\u7684\u8868\u9054\u5F0F\u3002", "validators", "zh_TW");
  t.add("This value is not a valid CSS color.", "\u9019\u500B\u6578\u503C\u4E0D\u662F\u6709\u6548\u7684 CSS \u984F\u8272\u3002", "validators", "zh_TW");
  t.add("This value is not a valid CIDR notation.", "\u9019\u500B\u6578\u503C\u4E0D\u662F\u6709\u6548\u7684 CIDR \u8868\u793A\u6CD5\u3002", "validators", "zh_TW");
  t.add("The value of the netmask should be between {{ min }} and {{ max }}.", "\u7DB2\u8DEF\u906E\u7F69\u7684\u503C\u61C9\u4ECB\u65BC {{ min }} \u548C {{ max }} \u4E4B\u9593\u3002", "validators", "zh_TW");
  t.add("The filename is too long. It should have {{ filename_max_length }} character or less.|The filename is too long. It should have {{ filename_max_length }} characters or less.", "\u6A94\u6848\u540D\u7A31\u904E\u9577\u3002\u61C9\u6700\u591A\u6709 {{ filename_max_length }} \u500B\u5B57\u5143\u3002|\u6A94\u6848\u540D\u7A31\u904E\u9577\u3002\u61C9\u6700\u591A\u6709 {{ filename_max_length }} \u500B\u5B57\u5143\u3002", "validators", "zh_TW");
  t.add("The password strength is too low. Please use a stronger password.", "\u5BC6\u78BC\u5F37\u5EA6\u592A\u4F4E\u3002\u8ACB\u4F7F\u7528\u66F4\u5F37\u7684\u5BC6\u78BC\u3002", "validators", "zh_TW");
  t.add("This value contains characters that are not allowed by the current restriction-level.", "\u9019\u500B\u6578\u503C\u5305\u542B\u76EE\u524D\u9650\u5236\u7D1A\u5225\u4E0D\u5141\u8A31\u7684\u5B57\u5143\u3002", "validators", "zh_TW");
  t.add("Using invisible characters is not allowed.", "\u4E0D\u5141\u8A31\u4F7F\u7528\u96B1\u5F62\u5B57\u5143\u3002", "validators", "zh_TW");
